"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["9028"],{6827(e){e.exports=JSON.parse('[{"slug":"budget-50-30-20","name":"50/30/20 Budget and Zero-Based Check","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Budgeting methods (50/30/20, zero-based)","group":"Personal finance","aliases":["budgeting","needs wants savings","zero-based budget","budget split"],"finds":"Whether your spending matches a target split and what is left unassigned","needs":"Monthly income and spending in three groups","text":"Targets: needs 50%, wants 30%, savings and debt repayment 20% of after-tax income. Zero-based check: income - needs - wants - savings should equal 0"},{"slug":"abs-excess-spread","name":"ABS Excess Spread and Overcollateralization","level":"Intermediate","subject":"Fixed Income","section":"Securitized Products","topic":"Asset-backed securities (ABS)","group":"Markets and instruments","aliases":["asset backed securities","credit enhancement","excess spread","OC"],"finds":"The protection built into an asset-backed security","needs":"Pool and note balances and rates, fees, losses","text":"Excess spread = Interest earned on the pool - Interest paid on the notes - Fees - Credit losses; Overcollateralization = (Pool balance - Notes outstanding) / Pool balance"},{"slug":"accretion-dilution","name":"Accretion/Dilution Analysis (Stock Deal)","level":"Intermediate","subject":"Corporate Finance","section":"Mergers & Restructuring","topic":"Accretion/dilution analysis","group":"Companies and valuation","aliases":["EPS accretion","pro forma EPS","merger EPS impact"],"finds":"EPS effect of a share-funded acquisition","needs":"Both firms\' net income, acquirer shares and price, price paid","text":"Pro forma EPS = (Acquirer NI + Target NI) / (Acquirer shares + New shares), where New shares = Price paid / Acquirer share price"},{"slug":"accrual-ratio","name":"Accrual Ratio (Earnings Quality)","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Earnings quality","group":"Companies and valuation","aliases":["Sloan accrual","earnings quality","cash versus accrual earnings"],"finds":"How much profit is not backed by cash","needs":"Net income, operating cash flow, average assets","text":"Accrual ratio = (Net income - Cash flow from operations) / Average total assets"},{"slug":"accrued-interest-dirty-price","name":"Accrued Interest and Dirty Price","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Government bonds","group":"Markets and instruments","aliases":["clean price","full price","government bond settlement","treasury note"],"finds":"What a buyer pays between coupon dates","needs":"Face value, coupon, days, clean price","text":"Accrued interest = Coupon payment x Days since last coupon / Days in the coupon period; Dirty (full) price = Clean (quoted) price + Accrued interest"},{"slug":"afn-external-financing","name":"Additional Funds Needed (Percent-of-Sales Forecast)","level":"Intermediate","subject":"Accounting Mastery & Financial Modeling","section":"Modeling craft","topic":"Modeling craft","group":"Companies and valuation","aliases":["external financing needed","AFN","percent of sales method","forecasting balance sheet"],"finds":"How much outside funding growth needs","needs":"Sales, growth, asset and liability ratios, margin, payout","text":"Additional funds needed = (Assets/Sales) x Change in sales - (Spontaneous liabilities/Sales) x Change in sales - Net margin x New sales x (1 - Payout ratio)"},{"slug":"adjusted-leverage-off-balance","name":"Adjusted Leverage with Off-Balance-Sheet Items","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Off-balance-sheet items","group":"Companies and valuation","aliases":["off balance sheet debt","lease adjusted debt","pension deficit","guarantees","debt like items"],"finds":"Debt including hidden obligations","needs":"Reported debt, leases, pension deficit, guarantees, EBITDA, rent","text":"Adjusted debt = Reported debt + Capitalized operating leases + Pension deficit + Probability x Guarantees; Adjusted leverage = Adjusted debt / EBITDAR"},{"slug":"after-tax-cost-of-debt","name":"After-Tax Cost of Debt","level":"Beginner","subject":"Corporate Finance","section":"Cost of Capital","topic":"Cost of debt (after-tax)","group":"Companies and valuation","aliases":["cost of debt","interest tax shield rate","rd after tax"],"finds":"Cost of borrowing after the tax saving","needs":"Borrowing rate, tax rate","text":"After-tax cost of debt = Pre-tax cost of debt x (1 - Tax rate)"},{"slug":"after-tax-return-tey","name":"After-Tax Return and Tax-Equivalent Yield","level":"Beginner","subject":"Investments & Portfolio Theory","section":"Portfolio Management","topic":"Tax-aware investing","group":"Markets and instruments","aliases":["tax equivalent yield","municipal bond yield","tax aware investing","after tax yield"],"finds":"Which of a taxable and a tax-free investment pays more after tax","needs":"Taxable yield, tax-free yield, tax rate","text":"After-tax return = Pre-tax return x (1 - tax rate); Tax-equivalent yield = Tax-free yield / (1 - tax rate)"},{"slug":"after-tax-salvage","name":"After-Tax Salvage Value","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Incremental cash flows","group":"Companies and valuation","aliases":["salvage value tax","sale of asset tax effect","terminal cash flow"],"finds":"Cash received when an asset is sold","needs":"Sale price, book value, tax rate","text":"After-tax salvage = Sale price - T x (Sale price - Book value)"},{"slug":"age-based-allocation","name":"Age-Based Asset Allocation and Portfolio Risk","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Asset allocation by age and goals","group":"Personal finance","aliases":["asset allocation by age and goals","110 minus age","glide path","equity share"],"finds":"A starting stock and bond mix for your age, with its expected return and risk","needs":"Age, base number, return and risk assumptions","text":"Equity share = (base number - age) / 100, kept between 0% and 100%; Portfolio return = equity share x equity return + (1 - equity share) x bond return; Portfolio risk uses the two-asset variance formula"},{"slug":"ai-fraud-model-value","name":"AI Fraud Model: Net Value of Alerts","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"AI in banking, trading and advice","group":"Modern finance and practice","aliases":["AI in banking, trading and advice","fraud detection model","false positives","alert review cost","precision and recall"],"finds":"What a detection model is worth in money","needs":"Alert counts, missed frauds, loss per fraud, review cost","text":"Fraud stopped = true alerts x average loss per fraud; Review cost = all alerts (true + false) x cost to review one alert; Net value = fraud stopped - review cost; Missed fraud = missed cases x average loss; Precision = true alerts / all alerts; Recall = true alerts / all frauds"},{"slug":"all-in-loan-cost","name":"All-In Cost of a Loan (One Year)","level":"Intermediate","subject":"Corporate Finance","section":"Raising Capital","topic":"Bank loans and syndicated loans","group":"Companies and valuation","aliases":["effective cost of borrowing","loan fees APR","bank loan cost","syndicated loan cost"],"finds":"True yearly cost of a loan with fees","needs":"Loan amount, rate, fee","text":"All-in cost = (Interest + Fees) / Net proceeds, for a one-year loan"},{"slug":"altman-z-score","name":"Altman Z-Score","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Credit analysis of bond issuers","group":"Markets and instruments","aliases":["bankruptcy prediction","credit analysis","financial distress score","Z score"],"finds":"How likely a company is to fail","needs":"Balance sheet and income figures, market value of equity","text":"Z = 1.2 x Working capital/Total assets + 1.4 x Retained earnings/Total assets + 3.3 x EBIT/Total assets + 0.6 x Market value of equity/Total liabilities + 1.0 x Sales/Total assets"},{"slug":"aml-customer-risk-score","name":"AML/KYC Customer Risk Score","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Anti-money laundering (AML) and KYC","group":"Modern finance and practice","aliases":["anti-money laundering","know your customer","risk-based approach","customer due diligence","enhanced due diligence"],"finds":"A customer risk rating and how much extra checking it triggers","needs":"Weights and scores for each risk factor","text":"Customer risk score = sum of (weight x score) over factors such as country, product, customer type, delivery channel and transaction pattern, each scored 1 (low) to 5 (high), weights adding up to 1; Rating bands set by the firm (here: 3.5 or more is high risk and gets enhanced due diligence)"},{"slug":"anchoring-adjustment-bias","name":"Anchoring and Insufficient Adjustment","level":"Beginner","subject":"Behavioral Finance","section":"Behavioral","topic":"Anchoring and framing","group":"Modern finance and practice","aliases":["anchoring and framing","anchoring bias","estimate from a starting point"],"finds":"How far a starting number biases an estimate","needs":"Anchor, informed value, adjustment share","text":"Estimate = anchor + adjustment share x (true value - anchor); Bias = estimate - true value = - (1 - adjustment share) x (true value - anchor). An adjustment share below 1 means the estimate stays too close to the anchor"},{"slug":"annual-report-scorecard","name":"Annual Report Scorecard","level":"Intermediate","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Analyze a public company\'s annual report end to end","group":"Modern finance and practice","aliases":["analyze a public company annual report","ratio dashboard","profitability, leverage, cash conversion","company health check"],"finds":"A quick read of profit, leverage and cash","needs":"Seven to ten numbers from the annual report","text":"Operating margin = operating profit / revenue; Net margin = net income / revenue; ROE = net income / equity; ROA = net income / assets; Net debt / EBITDA is common but needs depreciation, so net debt / operating profit is used here; Net debt = debt - cash; Interest cover = operating profit / interest; Free cash flow = operating cash flow - capital spending; Cash conversion = free cash flow / net income"},{"slug":"annualized-loss-expectancy","name":"Annualized Loss Expectancy (Cyber Risk)","level":"Beginner","subject":"Risk Management","section":"Risk","topic":"Operational risk and cyber risk","group":"Risk and quantitative methods","aliases":["ALE","SLE","ARO","cyber risk quantification","security investment return"],"finds":"The yearly expected cost of a cyber risk and whether a control pays","needs":"Asset value, exposure, incident rates, control cost","text":"Annualized loss expectancy = Single loss expectancy x Annual rate of occurrence; Single loss expectancy = Asset value x Exposure factor"},{"slug":"annualized-hpr","name":"Annualizing a Holding Period Return","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Interest rate and day-count conventions","group":"Foundations","aliases":["annualized return","annualize a return","return per year from a short period"],"finds":"A yearly rate from a return over a shorter or longer period","needs":"Return and days held","text":"Annualized return = (1 + HPR)^(365 / days) - 1"},{"slug":"annualized-volatility","name":"Annualizing Volatility","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Variance and standard deviation of returns","group":"Foundations","aliases":["square root of time rule","annual standard deviation","scale volatility"],"finds":"Yearly volatility from monthly or daily volatility","needs":"Period standard deviation, periods per year","text":"Annual volatility = period volatility x square root of m"},{"slug":"apt-expected-return","name":"Arbitrage Pricing Theory (APT) Expected Return","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Arbitrage Pricing Theory (APT)","group":"Markets and instruments","aliases":["APT","multi factor model","factor betas","arbitrage pricing"],"finds":"Return implied by several risk factors","needs":"Risk-free rate, betas, factor premiums","text":"Expected return = rf + beta1 x premium1 + beta2 x premium2 + ..."},{"slug":"arithmetic-mean-return","name":"Arithmetic Mean Return","level":"Beginner","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Arithmetic vs. geometric mean returns","group":"Foundations","aliases":["average return","mean return","simple average return"],"finds":"Average return per period","needs":"List of returns","text":"Mean return = (R1 + R2 + ... + Rn) / n"},{"slug":"asian-option-payoff","name":"Asian Option Payoff","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Exotic options","group":"Markets and instruments","aliases":["average price option","exotic options","path dependent option"],"finds":"What an average-price option pays","needs":"Observed prices, strike","text":"Asian call payoff = max(Average price over the period - Strike, 0); the average of the prices recorded on set dates"},{"slug":"asset-manager-economics","name":"Asset Manager Revenue and Fee Sensitivity","level":"Beginner","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Asset management firms","group":"Money, banks and the economy","aliases":["asset management firms","AUM growth","fee compression","operating margin"],"finds":"How AUM, fees and margin drive profit","needs":"AUM, flows, market return, fee, margin","text":"Ending AUM = starting AUM x (1 + market return) + net flows; Revenue = average AUM x fee rate; Operating profit = revenue x operating margin"},{"slug":"strategy-backtest-metrics","name":"Backtest Performance Metrics","level":"Beginner","subject":"Quantitative Finance","section":"Quant","topic":"Backtesting trading strategies","group":"Risk and quantitative methods","aliases":["backtesting trading strategies","maximum drawdown","Sharpe ratio of a backtest","Calmar ratio","hit rate"],"finds":"The headline numbers for a backtest","needs":"A list of periodic returns and the risk-free rate","text":"Annual return = (product of (1 + monthly return))^(12 / months) - 1; Sharpe = (average monthly return x 12 - risk-free rate) / (monthly sd x sqrt 12); Maximum drawdown = largest fall from a previous peak; Calmar = annual return / maximum drawdown"},{"slug":"backtest-performance-summary","name":"Backtest Summary: Return, Risk, Drawdown and Information Ratio","level":"Intermediate","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Construct and backtest a diversified portfolio","group":"Modern finance and practice","aliases":["construct and backtest a diversified portfolio","backtest report","CAGR volatility Sharpe drawdown","tracking error"],"finds":"A full performance report for a tested strategy","needs":"Monthly returns of portfolio and benchmark, risk-free rate","text":"Growth of 1 = product of (1 + monthly return); Annualized return (CAGR) = growth^(12 / months) - 1; Volatility = monthly standard deviation x square root of 12; Sharpe = 12 x (average monthly return - monthly risk-free rate) / volatility; Maximum drawdown = largest fall from a previous peak; Tracking error = standard deviation of monthly excess returns x square root of 12; Information ratio = annualized average excess return / tracking error"},{"slug":"balance-of-payments-identity","name":"Balance of Payments Identity","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Balance of payments and capital flows","group":"Money, banks and the economy","aliases":["balance of payments and capital flows","current account","financial account","saving investment gap"],"finds":"How a current account gap is financed","needs":"Trade balance, income, transfers, capital account, GDP, saving and investment","text":"Current account = trade balance + primary income (investment income, wages) + secondary income (transfers and remittances); Current account + capital account + financial account + errors = 0, where the financial account is net inflows (+) of capital; Current account = national saving - domestic investment"},{"slug":"bank-balance-sheet-ratios","name":"Bank Balance Sheet Ratios","level":"Beginner","subject":"Banking & Financial Institutions","section":"Banking","topic":"Bank balance sheet structure","group":"Money, banks and the economy","aliases":["bank balance sheet structure","loan to deposit ratio","leverage","funding mix"],"finds":"How a bank is funded and how thin its buffer is","needs":"Main asset and funding lines","text":"Loan-to-deposit ratio = loans / deposits; Equity ratio = equity / assets; Deposit funding share = deposits / total funding; The balance sheet balances: assets = deposits + wholesale funding + equity"},{"slug":"bank-profitability-dupont","name":"Bank Profitability: Income Statement, ROA and ROE","level":"Beginner","subject":"Banking & Financial Institutions","section":"Banking","topic":"How commercial banks make money","group":"Money, banks and the economy","aliases":["how commercial banks make money","efficiency ratio","net interest income","DuPont for banks"],"finds":"A bank\'s profit, efficiency and return on equity","needs":"Income statement lines, average assets and equity","text":"Net interest income = interest income - interest expense; Revenue = NII + fee income; Net income = (revenue - non-interest expense - loan loss provisions) x (1 - tax rate); Efficiency ratio = non-interest expense / revenue (lower is better); ROE = ROA x (assets / equity)"},{"slug":"bank-run-liquidity-shortfall","name":"Bank Run: Liquidity Shortfall and Fire-Sale Loss","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Banking","topic":"Bank runs and liquidity crises","group":"Money, banks and the economy","aliases":["bank runs and liquidity crises","fire sale","run threshold","liquid assets coverage"],"finds":"How large a run a bank can survive","needs":"Liquid assets, loans, equity, run size, haircut","text":"Cash needed = withdrawal fraction x deposits; Shortfall = cash needed - liquid assets; Assets to sell (at book value) = shortfall / (1 - haircut); Fire-sale loss = book value sold - shortfall; Withdrawal fraction that wipes out equity = (liquid assets + equity x (1 - h) / h) / deposits"},{"slug":"irrbb-eve-nii","name":"Banking Book Interest Rate Risk: EVE and NII","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Interest rate risk in the banking book","group":"Risk and quantitative methods","aliases":["duration gap","repricing gap","economic value of equity","net interest income sensitivity"],"finds":"A bank\'s value and earnings sensitivity to rates","needs":"Assets, liabilities, durations, repricing amounts, rate change","text":"Change in economic value of equity = -(Asset duration x Assets - Liability duration x Liabilities) x Rate change / (1 + yield); Change in net interest income = (Rate-sensitive assets - Rate-sensitive liabilities) x Rate change"},{"slug":"barrier-option-payoff","name":"Barrier Option Payoff","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Exotic options","group":"Markets and instruments","aliases":["knock-out option","knock-in option","up and out call","down and in put"],"finds":"What a knock-out call pays","needs":"Price path, strike, barrier","text":"An up-and-out call pays max(ST - K, 0) only if the price never touched the barrier B; an up-and-in call pays it only if the barrier was touched"},{"slug":"basel-capital-buffers","name":"Basel III Capital Requirement Stack and Buffers","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Basel I, II, III and the Basel III endgame","group":"Modern finance and practice","aliases":["Basel I, II, III","capital conservation buffer","countercyclical buffer","G-SIB surcharge","maximum distributable amount","CET1 requirement"],"finds":"How far a bank is above its capital requirement","needs":"CET1 capital, risk-weighted assets, buffer settings","text":"Required CET1 ratio = 4.5% minimum + capital conservation buffer (2.5%) + countercyclical buffer (set by the country, 0% to 2.5%) + surcharge for global systemically important banks (1% to 3.5%); Headroom = actual CET1 ratio - requirement (this is the loss the bank can absorb before restrictions); Capital needed = shortfall x risk-weighted assets; Banks inside the buffers face limits on dividends and bonuses"},{"slug":"basel-output-floor","name":"Basel III Endgame: Output Floor on Risk-Weighted Assets","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Basel I, II, III and the Basel III endgame","group":"Modern finance and practice","aliases":["Basel III endgame","72.5% floor","internal models floor","standardized approach floor"],"finds":"Whether the output floor reduces a bank\'s capital ratio","needs":"Internal and standardized RWA, CET1 capital","text":"Risk-weighted assets used for the capital ratio = the larger of (assets as measured by the bank\'s own models) and (72.5% of assets as measured by the standardized approach); The floor binds when internal models give less than 72.5% of the standardized amount; Capital ratio = CET1 / floored RWA"},{"slug":"lcr-nsfr","name":"Basel Liquidity Ratios: LCR and NSFR","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Bank liquidity rules: LCR and NSFR","group":"Risk and quantitative methods","aliases":["liquidity coverage ratio","net stable funding ratio","HQLA","available stable funding"],"finds":"Whether a bank meets the Basel liquidity rules","needs":"Liquid assets, flows, funding and asset lists with factors","text":"LCR = High-quality liquid assets / (30-day outflows - min(30-day inflows, 75% of outflows)); NSFR = Available stable funding / Required stable funding; both must be at least 100%"},{"slug":"baumol-cash-model","name":"Baumol Cash Management Model","level":"Intermediate","subject":"Corporate Finance","section":"Working Capital Management","topic":"Cash management","group":"Companies and valuation","aliases":["optimal cash balance","Baumol model","cash conversion size"],"finds":"Cash to hold and transfer","needs":"Transaction cost, annual cash needs, interest rate","text":"Optimal cash transfer C = square root of (2 x Fixed cost per transaction x Annual cash needs / Interest rate)"},{"slug":"bayes-theorem","name":"Bayes\' Theorem","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Probability basics: expected value and conditional probability","group":"Foundations","aliases":["Bayes rule","update a probability","false positive","posterior probability"],"finds":"A probability updated by evidence","needs":"Prior probability, hit rate, false alarm rate","text":"P(A given B) = P(B given A) x P(A) / (P(B given A) x P(A) + P(B given not A) x P(not A))"},{"slug":"beneish-m-score","name":"Beneish M-Score","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Accounting fraud warning signs","group":"Companies and valuation","aliases":["earnings manipulation","accounting fraud warning signs","fraud detection model"],"finds":"A flag for possible earnings manipulation","needs":"The eight index values","text":"M = -4.84 + 0.920 x DSRI + 0.528 x GMI + 0.404 x AQI + 0.892 x SGI + 0.115 x DEPI - 0.172 x SGAI + 4.679 x TATA - 0.327 x LVGI. A score above about -1.78 flags a likely manipulator"},{"slug":"best-execution-price-improvement","name":"Best Execution: Price Improvement and Execution Cost","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"MiFID II","group":"Modern finance and practice","aliases":["MiFID II","best execution","price improvement","execution quality","NBBO"],"finds":"How good an order execution was","needs":"Bid, offer, execution price, shares","text":"For a buy order: price improvement = (best offer at order time - price paid) x shares; Execution cost vs mid-point = (price paid - mid-point) x shares; Effective half-spread paid = (price paid - mid-point) / mid-point; Firms under MiFID II must show they took steps to get the best result for clients, including price, costs, speed and likelihood of execution"},{"slug":"beta","name":"Beta (Regression Slope)","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Linear regression and beta estimation","group":"Foundations","aliases":["stock beta","market beta","regression slope","systematic risk"],"finds":"Stock sensitivity to the market","needs":"Stock returns, market returns","text":"Beta = Cov(stock, market) / Var(market)"},{"slug":"bid-ask-spread","name":"Bid-Ask Spread and Trading Cost","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Bid-ask spread and market makers","group":"Markets and instruments","aliases":["spread","market maker spread","round trip cost","mid price"],"finds":"The cost of buying and selling straight away","needs":"Bid, ask, shares","text":"Spread = Ask - Bid; Relative spread = Spread / Mid price"},{"slug":"binomial-option-two-step","name":"Binomial Option Pricing (Two Steps)","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Binomial option pricing model","group":"Markets and instruments","aliases":["Cox Ross Rubinstein","CRR","binomial tree","risk neutral probability"],"finds":"Option values from a binomial tree","needs":"Stock, strike, rate, volatility, time","text":"u = e^(sigma x sqrt(dt)); d = 1/u; risk-neutral probability q = (e^(r x dt) - d) / (u - d); Option value = e^(-r x dt) x [q x Value if up + (1 - q) x Value if down], worked back from expiry"},{"slug":"miner-breakeven-price","name":"Bitcoin Mining: Revenue, Electricity Cost and Break-Even Price","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Bitcoin","group":"Modern finance and practice","aliases":["mining profitability","hash rate share","electricity cost per BTC","hashprice"],"finds":"The price needed to cover electricity","needs":"Hash rates, reward, fees, power use, electricity price","text":"Share of the network = miner hash rate / network hash rate; Coins won per day = share x blocks per day (144) x (block reward + average fees per block); Daily electricity cost = power in kW x 24 x price per kWh; Break-even price = daily cost / coins won per day"},{"slug":"bitcoin-supply-schedule","name":"Bitcoin Supply Schedule and Issuance Rate","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Bitcoin","group":"Modern finance and practice","aliases":["Bitcoin halving","21 million cap","stock-to-flow","block reward","annual inflation of supply"],"finds":"How many coins exist and how fast new ones arrive","needs":"Number of halvings","text":"Block reward after k halvings = 50 / 2^k coins; Each halving period lasts 210,000 blocks; Total supply after h halvings = 210,000 x sum of the rewards over those periods (the limit is 21 million); Yearly issuance = reward x 6 blocks an hour x 24 x 365 (about 52,560 blocks); Annual supply growth = yearly issuance / supply; Stock-to-flow = supply / yearly issuance"},{"slug":"black-76-option","name":"Black-76: Caplet or Swaption Price","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Swaptions, caps and floors","group":"Markets and instruments","aliases":["Black model","payer swaption","receiver swaption","caplet pricing","forward rate option"],"finds":"The price of a caplet, floorlet or swaption","needs":"Forward rate, strike, volatility, time, annuity, notional","text":"Payer option (caplet, or payer swaption) = Notional x Annuity x [F x N(d1) - K x N(d2)]; Receiver option = Notional x Annuity x [K x N(-d2) - F x N(-d1)]; d1 = [ln(F/K) + sigma^2 x T / 2] / (sigma x sqrt(T)); d2 = d1 - sigma x sqrt(T)"},{"slug":"black-litterman-one-asset","name":"Black-Litterman: Blending a View with Equilibrium (One Asset)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Black-Litterman model","group":"Markets and instruments","aliases":["Black Litterman","posterior return","investor views","bayesian portfolio"],"finds":"A return that blends the market and an opinion","needs":"Equilibrium return, asset risk, tau, your view, view uncertainty","text":"Blended return = (Equilibrium / (tau x s^2) + View / w) / (1 / (tau x s^2) + 1 / w)"},{"slug":"bs-pde-check","name":"Black-Scholes PDE Check","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Deriving the Black-Scholes PDE","group":"Risk and quantitative methods","aliases":["Black Scholes partial differential equation","deriving Black Scholes","delta hedged portfolio return"],"finds":"That a Black-Scholes price satisfies the pricing equation","needs":"Option inputs","text":"Theta + r x S x Delta + 0.5 x sigma^2 x S^2 x Gamma - r x V = 0 for any option price V that follows from Black-Scholes"},{"slug":"black-scholes-merton","name":"Black-Scholes-Merton Option Price","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Black-Scholes-Merton model","group":"Markets and instruments","aliases":["Black Scholes","BSM","European option pricing","d1 and d2"],"finds":"The fair price of a European call and put","needs":"Stock, strike, rate, dividend yield, volatility, time","text":"Call = S x e^(-qT) x N(d1) - K x e^(-rT) x N(d2); Put = K x e^(-rT) x N(-d2) - S x e^(-qT) x N(-d1); d1 = [ln(S/K) + (r - q + sigma^2 / 2) x T] / (sigma x sqrt(T)); d2 = d1 - sigma x sqrt(T)"},{"slug":"double-spend-probability","name":"Blockchain Double-Spend Probability (Nakamoto)","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Blockchain fundamentals","group":"Modern finance and practice","aliases":["blockchain fundamentals","51% attack","confirmations","proof of work security","attacker catch-up probability"],"finds":"How many confirmations make a payment safe","needs":"Attacker power share and number of confirmations","text":"Let q be the attacker\'s share of total computing power and p = 1 - q the honest share. After z confirmations, the chance the attacker can still catch up and replace the chain = 1 - sum for k = 0 to z of Poisson(k; lambda) x (1 - (q/p)^(z-k)), with lambda = z x q / p; If q is 50% or more the attacker eventually succeeds"},{"slug":"bollinger-bands","name":"Bollinger Bands","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Technical analysis","group":"Markets and instruments","aliases":["volatility bands","technical analysis bands","standard deviation bands"],"finds":"A price range based on recent volatility","needs":"Closing prices, days, number of standard deviations","text":"Bands = Simple moving average of the last n prices plus and minus k standard deviations (k is usually 2)"},{"slug":"bond-features-cash-flows","name":"Bond Cash Flows: Par, Coupon, Maturity","level":"Beginner","subject":"Fixed Income","section":"Bonds","topic":"Bond features: par, coupon, maturity","group":"Markets and instruments","aliases":["coupon payment","face value","par value","bond basics"],"finds":"The payments a bond makes","needs":"Face value, coupon rate, years, payments per year","text":"Coupon payment = Coupon rate x Face value / Payments per year; Number of payments = Years x Payments per year"},{"slug":"convexity","name":"Bond Convexity","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Convexity","group":"Markets and instruments","aliases":["curvature of the price-yield curve","second order interest rate risk"],"finds":"The curvature that duration misses","needs":"Bond terms, yield, yield change","text":"Convexity = [sum over each period k of k x (k + 1) x PV of cash flow k] / [Price x (1 + y/m)^2 x m^2]"},{"slug":"bond-futures-invoice","name":"Bond Futures Invoice Price and Basis","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Interest rate futures: SOFR and bond futures","group":"Markets and instruments","aliases":["conversion factor","cheapest to deliver","treasury bond futures","delivery"],"finds":"The cash for delivery and the basis of a bond","needs":"Futures price, conversion factor, accrued interest, clean price","text":"Invoice price = Futures price x Conversion factor + Accrued interest; Basis = Clean price of the bond - Futures price x Conversion factor"},{"slug":"bond-price","name":"Bond Price","level":"Beginner","subject":"Fixed Income","section":"Bonds","topic":"Bond pricing","group":"Markets and instruments","aliases":["present value of a bond","price of a coupon bond","bond valuation","premium and discount bonds"],"finds":"What a bond is worth at a given yield","needs":"Face value, coupon rate, yield, years, payments per year","text":"Price = Coupon x [1 - (1 + r)^-N] / r + Face value / (1 + r)^N, where r = yield / payments per year and N = number of payments"},{"slug":"bootstrap-spot-rates","name":"Bootstrapping Spot Rates from Par Yields","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Spot rates, forward rates and bootstrapping","group":"Markets and instruments","aliases":["zero curve","discount factors","spot curve","par curve to zero curve"],"finds":"Zero-coupon rates from a par curve","needs":"Par yields for consecutive years","text":"Discount factor for year n = (1 - par yield n x sum of earlier discount factors) / (1 + par yield n); Spot rate n = DF^(-1/n) - 1"},{"slug":"break-even-analysis","name":"Break-Even Analysis","level":"Beginner","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Sensitivity, scenario and break-even analysis","group":"Companies and valuation","aliases":["break even units","accounting break-even","contribution margin","break-even point"],"finds":"Sales needed to cover costs","needs":"Fixed costs, price, variable cost, expected sales","text":"Break-even quantity = Fixed costs / (Price - Variable cost per unit)"},{"slug":"brownian-motion-facts","name":"Brownian Motion Probabilities","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Brownian motion","group":"Risk and quantitative methods","aliases":["Wiener process","random walk limit","reflection principle","correlation of Brownian increments"],"finds":"Chances and spreads for a Brownian path","needs":"A level, a horizon and two times","text":"W_T is normal with mean 0 and variance T; P(W_T > a) = 1 - N(a / sqrt(T)); P(the path touches a before T) = 2 x P(W_T >= a); Correlation of W at times s < t = sqrt(s / t)"},{"slug":"bull-call-spread","name":"Bull Call Spread","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Option strategies: spreads, straddles, strangles, collars","group":"Markets and instruments","aliases":["vertical spread","debit spread","call spread"],"finds":"The limits and breakeven of a bull call spread","needs":"Two strikes, two premiums, price at expiry","text":"Buy a call at the lower strike K1 and sell a call at the higher strike K2. Net cost = C1 - C2; Max profit = (K2 - K1) - net cost; Breakeven = K1 + net cost"},{"slug":"bnpl-merchant-breakeven","name":"Buy Now Pay Later: Merchant Break-Even Sales Lift","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Buy now, pay later","group":"Modern finance and practice","aliases":["BNPL","pay in four","merchant fee","conversion uplift"],"finds":"Whether BNPL pays for the merchant and the lender","needs":"Margin, fee, expected lift, default rate, basket size","text":"Merchant profit per 100 of base sales = base sales x margin; with BNPL: sales x (1 + lift) x (margin - fee); Break-even lift u* = fee / (margin - fee); Customer pays nothing extra when paid on time, so the lender earns from merchant fees and late fees"},{"slug":"buyout-value-creation","name":"Buyout Returns and Value Creation Bridge","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Private equity: buyouts and growth equity","group":"Modern finance and practice","aliases":["PE buyout returns","EBITDA growth multiple expansion deleveraging","LBO value bridge","growth equity returns"],"finds":"Buyout returns and what drove them","needs":"Entry and exit EBITDA and multiples, leverage, debt repaid, years","text":"Entry equity = EBITDA x entry multiple x (1 - debt share); Exit equity = EBITDA at exit x exit multiple - remaining debt; MOIC = exit equity / entry equity; IRR = MOIC^(1/years) - 1 when there are no interim payouts; Gain splits into EBITDA growth x entry multiple, multiple change x exit EBITDA, and debt paid down"},{"slug":"option-payoffs","name":"Call and Put Payoffs and Profit","level":"Beginner","subject":"Derivatives","section":"Derivatives","topic":"Option payoffs and profit diagrams","group":"Markets and instruments","aliases":["option profit","breakeven","long call","short call","long put","short put","payoff diagram"],"finds":"What an option pays at expiry and the profit after cost","needs":"Strike, price at expiry, premiums","text":"Call payoff = max(Spot at expiry - Strike, 0); Put payoff = max(Strike - Spot at expiry, 0); Profit = Payoff - Premium paid (a seller\'s profit is the opposite)"},{"slug":"callable-bond-value","name":"Callable and Putable Bond Value","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Callable and putable bonds","group":"Markets and instruments","aliases":["embedded option","callable bond price","putable bond price","call option on a bond"],"finds":"What a bond with an embedded option is worth","needs":"Straight price, option value","text":"Callable bond price = Straight bond price - Value of the call option; Putable bond price = Straight bond price + Value of the put option"},{"slug":"capital-allocation-line","name":"Capital Allocation Line and Optimal Risky Weight","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Capital allocation line","group":"Markets and instruments","aliases":["CAL","risk free and risky mix","optimal y","complete portfolio"],"finds":"Return, risk and best split between risky and safe assets","needs":"Risk-free rate, risky return and risk, allocation, risk aversion","text":"Complete portfolio return = rf + y x (E(Rp) - rf); risk = y x sp; optimal y = (E(Rp) - rf) / (A x sp^2)"},{"slug":"urr-implicit-tax","name":"Capital Controls: Reserve Requirement Implicit Tax","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Capital controls","group":"Money, banks and the economy","aliases":["capital controls","unremunerated reserve requirement","Tobin tax","cost of controls","Chile encaje"],"finds":"The effective annual cost of a capital control","needs":"Rate, deposit share, holding periods, tax rate","text":"Implicit tax of an unremunerated reserve requirement (annualized) = interest rate x share of the inflow that must be deposited x (years the deposit is held / years of the loan); Transaction tax annualized = tax per transaction x 365 / holding days"},{"slug":"capital-gains-tax","name":"Capital Gains and Dividend Tax","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Taxes on investments: capital gains and dividends","group":"Personal finance","aliases":["taxes on investments","short term vs long term gains","after tax proceeds","tax loss offset"],"finds":"The tax cost of a sale and of dividends","needs":"Basis, proceeds, losses, holding period, rates, dividends","text":"Capital gain = sale proceeds - cost basis; Taxable gain = gain minus any capital losses used against it (not below 0); Tax = capital gains rate (short-term or long-term depending on holding period) x taxable gain + dividend tax rate x dividends"},{"slug":"capital-market-line","name":"Capital Market Line (CML)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Capital market line","group":"Markets and instruments","aliases":["CML","market portfolio line","efficient portfolios with a risk-free asset"],"finds":"Efficient return for a given total risk","needs":"Risk-free rate, market return and risk, portfolio risk","text":"Expected return = rf + (E(Rm) - rf) / sm x sp"},{"slug":"carbon-abatement-decision","name":"Carbon Markets: Abate or Buy Permits","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"Carbon markets","group":"Modern finance and practice","aliases":["carbon markets","cap and trade","marginal abatement cost","emissions trading","carbon price"],"finds":"The cheapest way to meet an emissions limit","needs":"Emissions, permits, permit price, abatement options","text":"Shortfall = emissions - permits held; Abate each metric ton whose marginal abatement cost (MAC) is below the permit price, cheapest first, until the shortfall is closed; Cost of abatement = sum of (metric tons x MAC) over measures used; Permits to buy = shortfall not abated; Total cost = abatement cost + permits bought x price; Compare with buying permits for the whole shortfall"},{"slug":"carhart-model","name":"Carhart Four-Factor Model Return","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Carhart momentum factor","group":"Markets and instruments","aliases":["Carhart","momentum factor","WML","four factor model"],"finds":"Return implied by four factors including momentum","needs":"Risk-free rate, four betas, four premiums","text":"Expected return = rf + b_mkt x MKT + b_smb x SMB + b_hml x HML + b_wml x WML"},{"slug":"carry-trade-return","name":"Carry Trade Return and Break-Even","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Carry trade","group":"Money, banks and the economy","aliases":["carry trade","funding currency","currency crash risk","leveraged carry"],"finds":"Whether a currency carry trade pays for its risk","needs":"Both rates, leverage, a currency move","text":"Return per unit borrowed = (1 + high-yield rate) x (1 + change in the high-yield currency) - (1 + funding rate); Break-even currency move = (1 + funding rate) / (1 + high rate) - 1; Levered return = leverage x return per unit"},{"slug":"cash-conversion-cycle","name":"Cash Conversion Cycle","level":"Intermediate","subject":"Corporate Finance","section":"Working Capital Management","topic":"Cash management","group":"Companies and valuation","aliases":["CCC","working capital cycle","DIO DSO DPO","operating cycle"],"finds":"Days cash is tied up in operations","needs":"Inventory, receivables, payables, sales, COGS","text":"Cash conversion cycle = Days inventory + Days sales outstanding - Days payables"},{"slug":"cash-conversion-from-statements","name":"Cash Conversion Cycle from the Financial Statements","level":"Intermediate","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Cash conversion cycle","group":"Companies and valuation","aliases":["DIO","DSO","DPO","operating cycle","days payable outstanding","days inventory outstanding"],"finds":"Days cash is tied up in operations","needs":"Revenue, COGS, average inventory, receivables, payables","text":"DIO = Average inventory / COGS x 365; DSO = Average receivables / Revenue x 365; DPO = Average payables / COGS x 365; Cash conversion cycle = DIO + DSO - DPO"},{"slug":"cash-flow-quality","name":"Cash Flow Quality Ratios","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Cash flow quality: operating cash flow vs. earnings","group":"Companies and valuation","aliases":["operating cash flow to net income","cash flow adequacy","CFO to EBITDA"],"finds":"Whether profit turns into cash and cash covers needs","needs":"CFO, net income, EBITDA, capex, dividends, debt repayments","text":"CFO / Net income; CFO / EBITDA; Cash flow adequacy = CFO / (Capex + Dividends + Debt repayments)"},{"slug":"cash-ratio-defensive-interval","name":"Cash Ratio and Defensive Interval","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Liquidity ratios: current, quick, cash","group":"Companies and valuation","aliases":["liquidity ratios","cash ratio","defensive interval measure","days of cash"],"finds":"How long a company can pay its way from liquid assets","needs":"Cash, securities, receivables, current liabilities, expenses","text":"Cash ratio = (Cash + Marketable securities) / Current liabilities; Defensive interval = (Cash + Securities + Receivables) / Daily cash operating expenses"},{"slug":"cash-runway","name":"Cash Runway","level":"Beginner","subject":"Corporate Finance","section":"Corporate Risk Management","topic":"Treasury management and liquidity planning","group":"Companies and valuation","aliases":["burn rate","months of cash","treasury liquidity planning","runway"],"finds":"Months before the cash runs out","needs":"Cash, monthly burn","text":"Runway (months) = Cash balance / Net monthly cash burn"},{"slug":"cat-bond-expected-loss","name":"Catastrophe Bond: Expected Loss and Risk Multiple","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Insurance-linked securities and catastrophe bonds","group":"Modern finance and practice","aliases":["insurance-linked securities","cat bond","expected loss","multiple at risk","ILS spread"],"finds":"What a catastrophe bond pays for the risk it carries","needs":"Attachment probability, loss given attachment, spread, risk-free rate","text":"Expected loss = probability of attachment (the event hits the bond) x average share of principal lost when it does; Multiple = spread / expected loss; Expected return = risk-free rate + spread - expected loss; Probability of losing money in a year = probability of attachment"},{"slug":"cdo-equity-return","name":"CDO Equity Tranche Return","level":"Intermediate","subject":"Fixed Income","section":"Securitized Products","topic":"Collateralized debt obligations (CDOs)","group":"Markets and instruments","aliases":["collateralized debt obligation","arbitrage CDO","equity tranche","leverage in structured credit"],"finds":"The equity return of a collateralized debt obligation","needs":"Asset pool and yield, debt tranches, fees, losses","text":"Equity return = (Interest earned on the assets - Interest paid on each debt tranche - Fees - Credit losses) / Equity invested"},{"slug":"ccp-initial-margin","name":"Central Counterparty Initial Margin (Value-at-Risk Method)","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Central clearing and counterparty risk","group":"Markets and instruments","aliases":["central clearing","CCP margin","margin period of risk","OTC vs exchange margin","initial margin"],"finds":"The collateral a clearing house asks for","needs":"Confidence level, volatility, margin period, position","text":"Initial margin = z-score x Daily volatility x Square root of margin period of risk (days) x Position size"},{"slug":"cet1-ratio","name":"CET1, Tier 1 and Leverage Ratios","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Banking","topic":"Capital ratios: CET1 and Tier 1","group":"Money, banks and the economy","aliases":["capital ratios","risk weighted assets","Basel III","capital buffers"],"finds":"Whether a bank\'s capital covers its risks","needs":"Exposures with weights, capital by tier, total exposure, requirement","text":"Risk-weighted assets = sum of (risk weight x exposure); CET1 ratio = common equity tier 1 capital / RWA; Tier 1 ratio = (CET1 + additional tier 1) / RWA; Total capital ratio = (Tier 1 + Tier 2) / RWA; Leverage ratio = Tier 1 / total (unweighted) exposure"},{"slug":"classification-metrics","name":"Classification Metrics: Precision, Recall and F1","level":"Beginner","subject":"Quantitative Finance","section":"Quant","topic":"Machine learning in finance","group":"Risk and quantitative methods","aliases":["confusion matrix","machine learning in finance","accuracy","false positives","default prediction"],"finds":"How good a yes/no model really is when the event is rare","needs":"The four confusion matrix counts","text":"Precision = TP / (TP + FP); Recall = TP / (TP + FN); F1 = 2 x Precision x Recall / (Precision + Recall); Accuracy = (TP + TN) / total"},{"slug":"weighted-average-carbon-intensity","name":"Climate Disclosure: Carbon Intensity and Financed Emissions","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"Climate risk disclosure (TCFD, ISSB)","group":"Modern finance and practice","aliases":["climate risk disclosure","TCFD","ISSB","WACI","PCAF","financed emissions","carbon footprint"],"finds":"A portfolio\'s carbon exposure","needs":"Weights, emissions, revenues, stakes, enterprise values","text":"Weighted average carbon intensity = sum of (portfolio weight x company emissions / company revenue), in metric tons of CO2 equivalent per million of revenue; Financed emissions = sum of (amount invested or lent / company enterprise value including cash) x company emissions; Portfolio footprint per million invested = financed emissions / total invested"},{"slug":"clo-oc-test","name":"CLO Overcollateralization Test","level":"Intermediate","subject":"Fixed Income","section":"Securitized Products","topic":"Collateralized loan obligations (CLOs)","group":"Markets and instruments","aliases":["collateralized loan obligation","coverage test","OC trigger","cash flow diversion"],"finds":"Whether each CLO class is within its coverage test","needs":"Collateral par, note classes, triggers","text":"OC ratio for class k = Collateral par value / (Total of the notes in class k and every class senior to it)"},{"slug":"coefficient-of-variation","name":"Coefficient of Variation","level":"Intermediate","subject":"Finance Foundations","section":"What Finance Is","topic":"Risk and return: the core trade-off","group":"Foundations","aliases":["CV","risk per unit of return","relative risk"],"finds":"Risk per unit of return","needs":"List of returns","text":"CV = standard deviation / mean return"},{"slug":"cointegration-half-life","name":"Cointegration: Hedge Ratio, Spread Z-Score and Half-Life","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Cointegration","group":"Risk and quantitative methods","aliases":["cointegration","Engle Granger","mean reversion of spread","half-life of mean reversion"],"finds":"Whether a pair behaves like a stable spread and how fast it reverts","needs":"Two aligned price lists","text":"Hedge ratio beta = Covariance(Y, X) / Variance(X); Spread = Y - beta x X - alpha; Fit spread today = phi x spread yesterday; Half-life = -ln 2 / ln(phi)"},{"slug":"collar-payoff","name":"Collar (Protective Put Financed by a Covered Call)","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Option strategies: spreads, straddles, strangles, collars","group":"Markets and instruments","aliases":["zero cost collar","protective put","covered call","floor and cap"],"finds":"The floor, cap and profit of a collar","needs":"Stock cost, strikes, premiums, price at expiry","text":"Collar value at expiry = min( max(Price at expiry, Put strike), Call strike ); Profit = Value - Stock price paid - Net premium"},{"slug":"collectible-net-return","name":"Collectibles: Repeat-Sale Return after Costs","level":"Beginner","subject":"Alternative Investments","section":"Alternatives","topic":"Collectibles, art and other alternatives","group":"Modern finance and practice","aliases":["art investing","collectibles and alternatives","buyer premium seller commission","holding costs of art","repeat sales"],"finds":"What a collectible really earns after costs","needs":"Purchase and sale prices, trading costs, holding costs, years","text":"Annual return before holding costs = [ (sale price x (1 - seller cost)) / (purchase price x (1 + buyer cost)) ] ^ (1 / years) - 1; Net return = that return - insurance rate - storage rate; Break-even sale price = purchase price x (1 + buyer cost) x (1 + hurdle)^years / (1 - seller cost)"},{"slug":"combined-ratio","name":"Combined Ratio (Insurers)","level":"Beginner","subject":"Valuation","section":"Valuation","topic":"Valuing banks and insurers","group":"Companies and valuation","aliases":["insurance combined ratio","loss ratio","expense ratio","underwriting profit"],"finds":"Underwriting profitability of an insurer","needs":"Claims, expenses, premiums","text":"Combined ratio = (Claims paid + Operating expenses) / Premiums earned"},{"slug":"commercial-paper-yield","name":"Commercial Paper Price and Yield","level":"Intermediate","subject":"Corporate Finance","section":"Working Capital Management","topic":"Short-term financing: commercial paper, credit lines","group":"Companies and valuation","aliases":["discount instrument","commercial paper","treasury bill yield","short-term financing"],"finds":"Price and true yield of short-term paper","needs":"Face value, discount rate, days","text":"Price = Face x (1 - discount rate x days / 360); Yield = (Face - Price) / Price x 365 / days"},{"slug":"commodity-roll-yield","name":"Commodity Futures: Basis and Roll Yield","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Commodity futures: contango and backwardation","group":"Markets and instruments","aliases":["contango","backwardation","roll return","futures curve"],"finds":"The gain or cost of rolling commodity futures","needs":"Spot, near price, next price, months between contracts","text":"Basis = Spot - Futures; Roll yield = Near futures price / Next futures price - 1 (negative in contango, positive in backwardation)"},{"slug":"commodity-futures-total-return","name":"Commodity Futures: Roll Yield and Total Return","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Commodities and commodity futures","group":"Modern finance and practice","aliases":["commodities and commodity futures","contango","backwardation","roll return","convenience yield"],"finds":"What rolling futures costs or earns and what the curve implies","needs":"Spot and futures prices, roll spacing, collateral rate, storage cost","text":"Roll yield per roll = (near futures price - next futures price) / near futures price (negative in contango, positive in backwardation); Annualized roll = (1 + roll)^(12 / months between contracts) - 1; Total return of a futures investment = spot price change + roll yield + interest on the cash collateral; Implied convenience yield y = interest rate + storage cost - (1/T) x ln(F / S)"},{"slug":"commodity-hedge-effective-price","name":"Commodity Hedge: Effective Price, Basis and Hedge Ratio","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Commodity risk hedging","group":"Risk and quantitative methods","aliases":["short hedge","basis risk","producer hedge","optimal hedge ratio"],"finds":"What a producer actually receives with a futures hedge","needs":"Futures and spot prices, correlation, volatilities, quantity","text":"Effective price = Spot at sale + Futures gain = Initial futures price + Final basis; Optimal hedge ratio = Correlation x Std dev of spot changes / Std dev of futures changes"},{"slug":"common-size-statement","name":"Common-Size Statements","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Common-size statements","group":"Companies and valuation","aliases":["vertical analysis","percentage of sales","percentage of total assets"],"finds":"Each line as a share of revenue or total assets","needs":"Line items, base","text":"Common-size percentage = Line item / Base, where the base is revenue for an income statement and total assets for a balance sheet"},{"slug":"comparative-advantage","name":"Comparative Advantage and Gains from Trade","level":"Beginner","subject":"Economics for Finance","section":"Markets and the Economy","topic":"Global trade and supply chains","group":"Money, banks and the economy","aliases":["global trade and supply chains","opportunity cost","terms of trade","specialization"],"finds":"Who should produce what, and the price range at which both gain","needs":"Hours per unit for each good in each country","text":"Opportunity cost of one unit of wine, in cloth = hours per wine / hours per cloth. The country with the lower opportunity cost has the comparative advantage. Both gain if they trade at a price (terms of trade) between the two opportunity costs"},{"slug":"cagr","name":"Compound Annual Growth Rate (CAGR)","level":"Beginner","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Arithmetic vs. geometric mean returns","group":"Foundations","aliases":["CAGR","average annual growth rate","solve for r","annualized return","compound growth rate"],"finds":"Smooth yearly growth rate","needs":"Start value, end value, years","text":"CAGR = (End value / Start value)^(1/n) - 1"},{"slug":"conditional-probability","name":"Conditional Probability","level":"Beginner","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Probability basics: expected value and conditional probability","group":"Foundations","aliases":["P(A|B)","probability given","Bayes basics"],"finds":"A probability updated by new information","needs":"P(A and B), P(B)","text":"P(A given B) = P(A and B) / P(B)"},{"slug":"confidence-interval-mean","name":"Confidence Interval for a Mean","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Sampling and confidence intervals","group":"Foundations","aliases":["confidence interval","margin of error","95% confidence interval"],"finds":"A likely range for the true average","needs":"Sample mean, standard deviation, sample size, z","text":"mean +/- z x s / sqrt(n)"},{"slug":"conflict-of-interest-cost","name":"Conflicted Advice: Long-Run Cost of a Hidden Commission","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Ethics, fiduciary standards and conflicts of interest","group":"Modern finance and practice","aliases":["ethics, fiduciary standards and conflicts of interest","fiduciary vs suitability","commission cost","best interest standard"],"finds":"What a conflict of interest costs over time","needs":"Amount, return, costs, years","text":"Value with a fiduciary adviser who charges f = V0 x (1 + r - f)^n; Value with a product that also pays the adviser a yearly commission c = V0 x (1 + r - f - c)^n; Cost of the conflict = difference between the two; Share of ending value lost = 1 - (1 + r - f - c)^n / (1 + r - f)^n"},{"slug":"laspeyres-cpi","name":"Consumer Price Index (Laspeyres) and Substitution Bias","level":"Intermediate","subject":"Economics for Finance","section":"How the Economy Works","topic":"Inflation: causes and measurement (CPI, PCE)","group":"Money, banks and the economy","aliases":["CPI","inflation measurement","PCE","Paasche","Fisher ideal index"],"finds":"Inflation from a basket of goods and how much substitution matters","needs":"Prices and quantities in two periods","text":"Laspeyres (CPI style) = cost of the OLD basket at new prices / cost of the old basket at old prices x 100; Paasche = cost of the NEW basket at new prices / cost of the new basket at old prices x 100; Fisher = square root of (Laspeyres x Paasche)"},{"slug":"short-term-fee-apr","name":"Consumer Protection: Annualized Cost of a Short-Term Fee","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Consumer financial protection","group":"Modern finance and practice","aliases":["consumer financial protection","payday loan APR","overdraft fee APR","truth in lending","cost of credit disclosure"],"finds":"The annual rate hidden in a short-term fee","needs":"Fee, amount, days","text":"Simple annualized rate = (fee / amount borrowed) x (365 / days borrowed); Effective annual rate if the loan is rolled over again and again = (1 + fee / amount)^(365 / days) - 1; Consumer rules require firms to disclose the annual percentage rate so short-term products can be compared with other credit"},{"slug":"continuous-compounding","name":"Continuous Compounding","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Continuous compounding","group":"Foundations","aliases":["e to the rt","continuously compounded interest","exponential growth","Pert"],"finds":"Future value with continuous compounding","needs":"Amount today, rate, years","text":"FV = PV x e^(r x t)"},{"slug":"convertible-bond-value","name":"Convertible Bond: Conversion Value and Premium","level":"Intermediate","subject":"Corporate Finance","section":"Raising Capital","topic":"Convertible securities","group":"Companies and valuation","aliases":["conversion ratio","conversion premium","convertible security"],"finds":"What a convertible is worth as shares and its premium","needs":"Par, conversion price, share price, bond price","text":"Conversion ratio = Par / Conversion price; Conversion value = Conversion ratio x Share price; Premium = Bond price / Conversion value - 1"},{"slug":"convertible-premium","name":"Convertible Bond: Conversion Value and Premiums","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Warrants and convertible bonds","group":"Markets and instruments","aliases":["conversion ratio","conversion price","conversion premium","bond floor","parity"],"finds":"What a convertible bond is worth against its parts","needs":"Face value, conversion ratio, share price, bond price, straight value","text":"Conversion value = Conversion ratio x Share price; Conversion price = Face value / Conversion ratio; Premium over conversion value = Bond price / Conversion value - 1; Floor = higher of conversion value and straight bond value"},{"slug":"ear-to-apr","name":"Converting EAR to a Periodic Rate and APR","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Effective annual rate vs. APR","group":"Foundations","aliases":["EAR to APR","monthly rate from annual rate","nominal rate from effective rate","equivalent periodic rate"],"finds":"Monthly or periodic rate from a yearly effective rate","needs":"Effective annual rate, times per year","text":"Periodic rate = (1 + EAR)^(1/m) - 1, and APR = m x periodic rate"},{"slug":"corporate-bond-yield","name":"Corporate Bond Yield Build-Up","level":"Beginner","subject":"Fixed Income","section":"Bonds","topic":"Corporate bonds","group":"Markets and instruments","aliases":["risk free rate plus spread","corporate bond pricing","yield components"],"finds":"Yield and price of a corporate bond built from the government curve","needs":"Government yield, spread, premium, bond terms","text":"Corporate bond yield = Government yield for the same maturity + Credit spread + Liquidity premium"},{"slug":"correlation","name":"Correlation Coefficient","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Covariance and correlation","group":"Foundations","aliases":["correlation","Pearson correlation","rho"],"finds":"Strength of the link between two returns","needs":"Two lists of returns","text":"Correlation = Cov(X,Y) / (sX x sY)"},{"slug":"capm-cost-of-equity","name":"Cost of Equity (CAPM)","level":"Intermediate","subject":"Corporate Finance","section":"Cost of Capital","topic":"Cost of equity","group":"Companies and valuation","aliases":["CAPM","capital asset pricing model","required return on equity"],"finds":"Required return on equity","needs":"Risk-free rate, beta, equity risk premium","text":"Cost of equity = Risk-free rate + Beta x Equity risk premium"},{"slug":"dividend-growth-cost-of-equity","name":"Cost of Equity (Dividend Growth)","level":"Intermediate","subject":"Corporate Finance","section":"Cost of Capital","topic":"Cost of equity","group":"Companies and valuation","aliases":["dividend discount cost of equity","Gordon cost of equity","D1/P0 + g"],"finds":"Required return on equity from dividends","needs":"Next dividend, price, growth","text":"Cost of equity = Next dividend / Current price + Growth rate"},{"slug":"mm-cost-of-equity","name":"Cost of Equity with Leverage (Modigliani-Miller Proposition II)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Structure","topic":"Modigliani-Miller propositions (with and without taxes)","group":"Companies and valuation","aliases":["MM proposition II","levered cost of equity","cost of equity rises with debt"],"finds":"How leverage raises the cost of equity","needs":"Unlevered cost, cost of debt, debt-to-equity, tax rate","text":"Cost of equity = r0 + (r0 - rd) x D/E x (1 - T)"},{"slug":"fee-drag","name":"Cost of Fees: Active vs. Passive","level":"Beginner","subject":"Investments & Portfolio Theory","section":"Market Efficiency","topic":"Active vs. passive management debate","group":"Markets and instruments","aliases":["expense ratio impact","fee drag","active versus passive","cost of active management"],"finds":"How fees reduce wealth over time","needs":"Amount, gross return, two fees, years","text":"Final value = Amount invested x (1 + gross return - annual fee)^years"},{"slug":"cost-of-goods-sold","name":"Cost of Goods Sold (Inventory Roll-Forward)","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Inventory accounting (FIFO, LIFO, weighted average)","group":"Foundations","aliases":["COGS","cost of sales","inventory formula"],"finds":"Cost of the items sold","needs":"Beginning inventory, purchases, ending inventory","text":"COGS = Beginning inventory + Purchases - Ending inventory"},{"slug":"flotation-adjusted-cost-of-equity","name":"Cost of New Equity with Flotation Costs","level":"Intermediate","subject":"Corporate Finance","section":"Raising Capital","topic":"Seasoned equity offerings","group":"Companies and valuation","aliases":["seasoned equity offering cost","flotation cost","new equity issue cost"],"finds":"Cost of raising new equity","needs":"Dividend, price, flotation cost, growth","text":"Cost of new equity = Next dividend / (Price x (1 - flotation cost)) + Growth rate"},{"slug":"cost-of-preferred","name":"Cost of Preferred Stock","level":"Beginner","subject":"Corporate Finance","section":"Cost of Capital","topic":"Cost of preferred stock","group":"Companies and valuation","aliases":["preferred stock cost","preferred dividend yield"],"finds":"Cost of preferred financing","needs":"Dividend, price, flotation cost","text":"Cost of preferred = Preferred dividend / (Price x (1 - flotation cost))"},{"slug":"cost-of-trade-credit","name":"Cost of Skipping an Early-Payment Discount","level":"Intermediate","subject":"Corporate Finance","section":"Working Capital Management","topic":"Payables management","group":"Companies and valuation","aliases":["2/10 net 30","trade credit cost","early payment discount","payables management"],"finds":"The true cost of not paying early","needs":"Discount, discount days, due day","text":"Effective annual cost = (1 + d / (1 - d))^(365 / (Final due day - Discount day)) - 1"},{"slug":"regulation-cost-benefit","name":"Cost-Benefit Test of a Financial Rule","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Why financial regulation exists","group":"Modern finance and practice","aliases":["why financial regulation exists","systemic crisis cost","net benefit of regulation","externality"],"finds":"Whether a financial rule is worth its cost","needs":"Fall in crisis probability, crisis cost, compliance cost","text":"Expected yearly benefit = reduction in the yearly chance of a crisis x cost of a crisis to the economy; Net benefit = expected benefit - yearly cost of complying; Break-even reduction in crisis chance = compliance cost / crisis cost"},{"slug":"counterparty-exposure-netting","name":"Counterparty Exposure, Netting and Potential Future Exposure","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Counterparty credit risk and CVA","group":"Risk and quantitative methods","aliases":["counterparty credit risk","PFE","netting agreement","exposure at default derivatives"],"finds":"Counterparty exposure with and without netting","needs":"Trade values, notional, volatility, horizon, confidence","text":"Gross exposure = sum of the positive trade values; Net exposure = max(sum of all trade values, 0); Potential future exposure = z-score x volatility x sqrt(time) x Notional"},{"slug":"country-risk-premium","name":"Country Risk Premium","level":"Intermediate","subject":"Corporate Finance","section":"Cost of Capital","topic":"Country risk premium","group":"Companies and valuation","aliases":["CRP","sovereign spread method","emerging market risk premium"],"finds":"Extra return for country risk","needs":"Sovereign spread, volatilities, rf, beta, ERP","text":"CRP = Sovereign default spread x (Equity volatility / Bond volatility); Cost of equity = rf + beta x ERP + CRP"},{"slug":"covariance","name":"Covariance","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Covariance and correlation","group":"Foundations","aliases":["sample covariance","how two returns move together"],"finds":"Whether two returns move together","needs":"Two lists of returns","text":"Cov(X,Y) = sum of (xi - mean x)(yi - mean y) / (n - 1)"},{"slug":"covered-bond-overcollateralization","name":"Covered Bond Overcollateralization","level":"Beginner","subject":"Fixed Income","section":"Securitized Products","topic":"Covered bonds","group":"Markets and instruments","aliases":["cover pool","asset cover test","pfandbrief","dual recourse"],"finds":"The cushion behind covered bonds","needs":"Cover pool value, bonds, minimum cover","text":"Overcollateralization = Cover pool value / Covered bonds outstanding - 1"},{"slug":"covered-interest-arbitrage","name":"Covered Interest Parity and Arbitrage","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Interest rate parity (covered and uncovered)","group":"Money, banks and the economy","aliases":["interest rate parity","CIP","covered arbitrage","forward premium deviation"],"finds":"Whether a forward rate offers a free profit","needs":"Spot, market forward, both rates, days, amount","text":"Parity says the forward rate F = S x (1 + domestic rate T) / (1 + foreign rate T). If the market forward differs, borrow where it is cheaper, convert at spot, invest abroad, and sell the proceeds forward: profit = foreign proceeds at the market forward - domestic proceeds. Compare: invest K in domestic currency = K x (1 + r_d T)"},{"slug":"cir-moments-feller","name":"Cox-Ingersoll-Ross Moments and Feller Condition","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Interest rate models (Vasicek, CIR, Hull-White)","group":"Risk and quantitative methods","aliases":["CIR model","square root process","Feller condition","non-negative interest rates"],"finds":"Where a square-root rate is expected to be and whether it stays positive","needs":"Rate, long-run mean, speed, sigma, time","text":"Expected rate = theta + (r0 - theta) x e^(-kappa t); Variance = r0 x sigma^2 / kappa x (e^(-kappa t) - e^(-2 kappa t)) + theta x sigma^2 / (2 kappa) x (1 - e^(-kappa t))^2; the rate stays above zero if 2 x kappa x theta >= sigma^2"},{"slug":"credit-card-payoff","name":"Credit Card Payoff Time and Interest","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Credit cards and interest traps","group":"Personal finance","aliases":["credit cards","minimum payment trap","card interest","months to pay off"],"finds":"How long a card balance lasts and what it costs","needs":"Balance, APR, monthly payment","text":"Months to pay off = -ln(1 - i x Balance / Payment) / ln(1 + i), where i is the monthly rate (APR / 12); Payment needed to clear in n months = i x Balance / (1 - (1 + i)^(-n))"},{"slug":"cds-spread-upfront","name":"Credit Default Swap: Spread, Upfront and Payout","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Credit default swaps (CDS)","group":"Markets and instruments","aliases":["CDS","credit triangle","CDS premium","protection buyer","risky annuity"],"finds":"A fair CDS spread, the upfront and the payout","needs":"Default probability, recovery, rate, term, coupon, notional","text":"CDS spread = Hazard rate (annual default probability) x (1 - Recovery); Upfront = (Spread - Standard coupon) x Risky annuity x Notional; Payout on default = Notional x (1 - Recovery)"},{"slug":"credit-scoring-logit","name":"Credit Scoring: Logistic Default Probability","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Credit risk models (Merton, credit scoring)","group":"Risk and quantitative methods","aliases":["logistic regression","scorecard","probability of default model","logit"],"finds":"A default probability from borrower data","needs":"Model coefficients, borrower variables","text":"Probability of default = 1 / (1 + e^-(intercept + b1 x x1 + b2 x x2 + ...))"},{"slug":"credit-spread","name":"Credit Spread and Spread Duration","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Credit spreads","group":"Markets and instruments","aliases":["option adjusted spread","yield spread","spread widening","basis points over treasuries"],"finds":"The credit spread and its price effect","needs":"Two yields, spread duration, spread change","text":"Credit spread = Corporate yield - Government yield; Percentage price change = -Spread duration x Change in spread"},{"slug":"credit-union-member-benefit","name":"Credit Union Member Benefit and Net Worth Ratio","level":"Beginner","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Credit unions and cooperatives","group":"Money, banks and the economy","aliases":["credit unions","cooperative bank","member dividend","net worth ratio"],"finds":"What membership is worth and how strong the credit union\'s capital is","needs":"Rates at both institutions, balances, net worth and assets","text":"Yearly member benefit = (bank loan rate - credit union loan rate) x loans + (credit union savings rate - bank savings rate) x savings; Net worth ratio = net worth / total assets (7% or more counts as well capitalized in the US)"},{"slug":"credit-utilization","name":"Credit Utilization Ratio","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Credit scores and credit reports","group":"Personal finance","aliases":["credit scores","credit score factors","revolving utilization","credit limit usage"],"finds":"How much of your available credit you are using","needs":"Balances and limits on each card","text":"Credit utilization = total revolving balances / total credit limits. A common guideline is to keep it under 30%, and lower is better"},{"slug":"cva-approximation","name":"Credit Valuation Adjustment (CVA)","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Central clearing and counterparty risk","group":"Markets and instruments","aliases":["counterparty credit risk","expected exposure","OTC derivatives credit charge","bilateral risk"],"finds":"The expected loss from a derivative counterparty\'s default","needs":"Expected exposures, default probability, recovery, discount rate","text":"CVA = (1 - Recovery) x Sum over each year of [Expected positive exposure x Probability of default in that year x Discount factor]"},{"slug":"triangular-arbitrage","name":"Cross Rates and Triangular Arbitrage","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Foreign exchange market structure","group":"Money, banks and the economy","aliases":["foreign exchange market structure","bid ask spread in pips","three currency arbitrage","implied cross rate"],"finds":"Whether three currency quotes are consistent","needs":"Bid and ask for three currency pairs","text":"Implied cross rate = EUR/USD rate x USD/JPY rate. Triangular arbitrage trades around the three currencies at the dealer\'s prices (buy at the ask, sell at the bid) and profits if the quoted cross differs from the implied cross by more than the spread; Spread in pips = (ask - bid) / pip size"},{"slug":"cross-border-payment-cost","name":"Cross-Border Payment All-In Cost","level":"Beginner","subject":"Banking & Financial Institutions","section":"Banking","topic":"Correspondent banking and SWIFT","group":"Money, banks and the economy","aliases":["correspondent banking and SWIFT","remittance cost","FX margin","intermediary bank fees"],"finds":"What a cross-border payment costs in all","needs":"Amount, each fee, mid-market and applied rate","text":"Amount received = (amount sent - sender fee - correspondent fee) x bank exchange rate - receiving bank fee; All-in cost = 1 - amount received / (amount sent x mid-market exchange rate)"},{"slug":"crowdfunding-net-proceeds","name":"Crowdfunding: Net Proceeds after Fees","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Crowdfunding","group":"Modern finance and practice","aliases":["reward crowdfunding","platform fee","payment processing fee","campaign goal"],"finds":"What a crowdfunding campaign must raise to fund a project","needs":"Pledges, backers, fee rates, target","text":"Net proceeds = money raised x (1 - platform fee - payment fee) - fixed fee per backer x number of backers; Raise needed to receive a target G = (G + fixed fees) / (1 - platform fee - payment fee)"},{"slug":"crypto-etf-fee-drag","name":"Crypto ETF vs Direct Holding: Fee Drag and Cost","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Bitcoin and crypto ETFs","group":"Modern finance and practice","aliases":["Bitcoin and crypto ETFs","spot bitcoin ETF","expense ratio","self custody cost","tracking"],"finds":"Which route is cheaper over time","needs":"Amount, return, ETF fee, direct costs, years","text":"Value of an ETF after n years = start value x (1 + coin return - fee) multiplied over the years; Value of holding the coin directly = start value x (1 + coin return) multiplied over the years, less custody and trading costs paid; Fee drag = (direct value - ETF value) / direct value; Break-even yearly cost of self-custody = ETF fee"},{"slug":"abnormal-return-event-window","name":"Cumulative Abnormal Return before an Announcement","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Insider trading","group":"Modern finance and practice","aliases":["detecting insider trading","event study","market-adjusted return","abnormal return surveillance"],"finds":"Whether a pre-announcement price move is unusual","needs":"Stock and market returns, alpha, beta, residual volatility","text":"Abnormal return on day t = stock return - (alpha + beta x market return); Cumulative abnormal return = sum of abnormal returns over the window before the announcement; z-score = CAR / (daily residual volatility x square root of the number of days); Large unexplained run-ups before news can prompt an investigation"},{"slug":"cumulative-voting","name":"Cumulative Voting: Shares Needed to Elect Directors","level":"Intermediate","subject":"Corporate Finance","section":"Corporate Governance","topic":"Proxy voting","group":"Companies and valuation","aliases":["proxy voting","minority shareholder board seats","shares needed to elect a director"],"finds":"Votes needed to win board seats","needs":"Total shares, seats wanted, seats up for election","text":"Shares needed = rounded down (Total shares x Seats wanted / (Seats up for election + 1)) + 1"},{"slug":"currency-swap-cash-flows","name":"Currency Swap Cash Flows and Value","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Currency swaps","group":"Markets and instruments","aliases":["cross currency swap","principal exchange","FX swap legs"],"finds":"Cash flows and value of a currency swap","needs":"Notionals, rates, exchange rates, remaining years","text":"Foreign notional = Home notional / Exchange rate at the start; Value to the party paying USD and receiving EUR = Exchange rate now x Value of the EUR leg - Value of the USD leg"},{"slug":"current-ratio","name":"Current Ratio","level":"Beginner","subject":"Finance Foundations","section":"What Finance Is","topic":"Liquidity, solvency and leverage (concepts)","group":"Foundations","aliases":["liquidity ratio","working capital ratio","short-term liquidity"],"finds":"Short-term liquidity","needs":"Current assets, current liabilities","text":"Current ratio = Current assets / Current liabilities"},{"slug":"current-yield-ytc","name":"Current Yield and Yield to Call","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Current yield and yield to call","group":"Markets and instruments","aliases":["yield to call","YTC","yield to worst","callable bond yield"],"finds":"Income yield and the worst-case yield on a callable bond","needs":"Price, coupon, call price, call date, maturity","text":"Current yield = Annual coupon / Price; Yield to call = the yield that makes the coupons up to the call date plus the call price worth today\'s price"},{"slug":"ltv-to-cac","name":"Customer Lifetime Value to Acquisition Cost (LTV:CAC)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Valuing startups and high-growth firms","group":"Companies and valuation","aliases":["LTV","CAC","unit economics","customer lifetime value"],"finds":"Whether customers pay back their acquisition cost","needs":"Revenue per customer, margin, churn, acquisition cost","text":"LTV = Yearly revenue per customer x Gross margin / Yearly churn rate; LTV:CAC = LTV / Cost to acquire a customer"},{"slug":"security-control-rosi","name":"Cybersecurity: Return on Security Investment","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Cybersecurity and digital fraud","group":"Modern finance and practice","aliases":["cybersecurity and digital fraud","ROSI","risk reduction","expected annual loss"],"finds":"Whether a security control is worth its cost","needs":"Loss per incident, incident rates, control cost","text":"Expected yearly loss (ALE) = loss per incident x incidents per year, summed over threats; Risk reduction = ALE before - ALE after the control; Return on security investment = (risk reduction - cost of the control) / cost of the control; Break-even reduction = cost of the control / ALE before"},{"slug":"days-sales-outstanding","name":"Days Sales Outstanding and Receivables Turnover","level":"Beginner","subject":"Corporate Finance","section":"Working Capital Management","topic":"Receivables management","group":"Companies and valuation","aliases":["DSO","collection period","receivables turnover","average collection period"],"finds":"How fast customers pay","needs":"Receivables, annual credit sales","text":"DSO = Receivables / Sales x 365; Receivables turnover = Sales / Receivables"},{"slug":"dcf-capstone-bridge","name":"DCF Capstone: From Cash Flows to Value per Share","level":"Intermediate","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Build a full DCF valuation of a real company","group":"Modern finance and practice","aliases":["build a full DCF valuation","enterprise value to equity bridge","terminal value share","WACC sensitivity"],"finds":"A value per share with its sensitivity to the discount rate","needs":"Forecast cash flows, WACC, growth, net debt, shares","text":"Enterprise value = present value of five forecast free cash flows + present value of terminal value; Terminal value = last cash flow x (1 + growth) / (WACC - growth); Equity value = enterprise value - net debt; Value per share = equity value / shares; Share of value in the terminal value = PV of terminal value / enterprise value"},{"slug":"dcf-enterprise-value","name":"DCF Enterprise Value (Explicit Period plus Terminal Value)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Discounted cash flow (DCF) model build","group":"Companies and valuation","aliases":["DCF","discounted cash flow","DCF model build","enterprise value from cash flows"],"finds":"Business value from forecast cash flows","needs":"Forecast FCFF, WACC, terminal growth","text":"EV = sum of FCFF_t / (1 + WACC)^t for t = 1 to n, plus Terminal value / (1 + WACC)^n"},{"slug":"trial-balance","name":"Debits Equal Credits (Trial Balance)","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Double-entry bookkeeping","group":"Foundations","aliases":["trial balance check","double entry check","debit credit rule"],"finds":"Whether the books balance","needs":"Debit balances, credit balances","text":"Total debits = Total credits"},{"slug":"debt-ratio","name":"Debt Ratio","level":"Beginner","subject":"Finance Foundations","section":"What Finance Is","topic":"Liquidity, solvency and leverage (concepts)","group":"Foundations","aliases":["total debt ratio","liabilities to assets","leverage"],"finds":"Share of assets funded by debt","needs":"Total liabilities, total assets","text":"Debt ratio = Total liabilities / Total assets"},{"slug":"debt-to-equity","name":"Debt-to-Equity Ratio","level":"Beginner","subject":"Finance Foundations","section":"What Finance Is","topic":"Liquidity, solvency and leverage (concepts)","group":"Foundations","aliases":["D/E ratio","leverage ratio","gearing"],"finds":"How much a company relies on borrowing","needs":"Total debt, total equity","text":"D/E = Total debt / Total equity"},{"slug":"dti-ratios","name":"Debt-to-Income Ratios and Affordable Housing Payment","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Mortgages: fixed vs. adjustable","group":"Personal finance","aliases":["DTI","front end ratio","back end ratio","mortgage affordability"],"finds":"How lenders will view your debt load and the most they would allow","needs":"Gross income, housing payment, other debts","text":"Front-end ratio = housing payment / gross monthly income; Back-end ratio = (housing payment + other debt payments) / gross monthly income; Maximum housing payment = the smaller of 28% of income and 36% of income - other debt payments"},{"slug":"default-enrollment-effect","name":"Default Enrollment: Effect on Retirement Savings","level":"Beginner","subject":"Behavioral Finance","section":"Behavioral","topic":"Nudges and choice architecture","group":"Modern finance and practice","aliases":["nudges and choice architecture","auto-enrollment","opt-out default","participation rate"],"finds":"What making saving the default is worth","needs":"Workers, participation rates, salary, contribution rate, years, return","text":"Extra participants = workers x (participation with automatic enrollment - participation with opt-in); Extra savings per year = extra participants x salary x contribution rate; Extra retirement balance = extra participants x yearly contribution x ((1 + r)^n - 1) / r"},{"slug":"default-probability-from-spread","name":"Default Probability and Recovery from Credit Spread","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Default probability and recovery rates","group":"Markets and instruments","aliases":["credit triangle","expected loss","loss given default","cumulative default probability"],"finds":"Default probability and expected loss from a spread","needs":"Spread, recovery rate, years, exposure","text":"Annual default probability = Spread / (1 - Recovery rate); Cumulative default probability over n years = 1 - (1 - PD)^n; Expected loss = PD x (1 - R) x Exposure"},{"slug":"deferred-tax","name":"Deferred Tax from Accelerated Depreciation","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Deferred taxes","group":"Companies and valuation","aliases":["deferred tax liability","temporary difference","tax expense vs tax paid","DTL"],"finds":"Why tax expense differs from tax paid","needs":"Pre-tax profit, tax rate, extra tax depreciation","text":"Tax expense = Tax rate x Pre-tax book profit; Current tax payable = Tax rate x (Pre-tax profit - Extra depreciation allowed for tax); Deferred tax = Tax expense - Current tax"},{"slug":"amm-constant-product-swap","name":"DeFi Automated Market Maker: Constant-Product Swap","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Decentralized finance (DeFi)","group":"Modern finance and practice","aliases":["DeFi","Uniswap","x*y=k","slippage","price impact","liquidity pool"],"finds":"What a swap pays and how far it moves the price","needs":"Pool amounts, trade size, fee","text":"A pool holds x of token A and y of token B and keeps x times y constant; Selling dx of A (after a fee share phi) pays out dy = y - x y / (x + dx x (1 - phi)); Pool price before = y / x; Average price paid = dy / dx; Slippage = 1 - average price / pool price"},{"slug":"db-vs-dc-pension","name":"Defined Benefit vs Defined Contribution Pension","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Pension funds: defined benefit vs. defined contribution","group":"Money, banks and the economy","aliases":["pension funds","final salary pension","pension pot","replacement ratio"],"finds":"What each pension type delivers and who carries the risk","needs":"Accrual, service, salary, contribution, returns, retirement length","text":"Defined benefit pension = accrual rate x years of service x final salary; Its value at retirement = pension x annuity factor, where annuity factor = (1 - (1 + r)^(-n)) / r; Defined contribution pot = yearly contribution x ((1 + g)^N - 1) / g; Income the pot can buy = pot / annuity factor"},{"slug":"degree-of-combined-leverage","name":"Degree of Combined Leverage (DCL)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Structure","topic":"Leverage: operating and financial","group":"Companies and valuation","aliases":["DCL","total leverage","DOL times DFL"],"finds":"Combined sensitivity to sales from fixed costs and debt","needs":"Units, price, variable cost, fixed costs, interest","text":"DCL = DOL x DFL"},{"slug":"degree-of-financial-leverage","name":"Degree of Financial Leverage (DFL)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Structure","topic":"Leverage: operating and financial","group":"Companies and valuation","aliases":["DFL","financial leverage","interest leverage"],"finds":"Sensitivity of earnings to EBIT because of debt","needs":"EBIT, interest","text":"DFL = EBIT / (EBIT - Interest)"},{"slug":"degree-of-operating-leverage","name":"Degree of Operating Leverage (DOL)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Structure","topic":"Leverage: operating and financial","group":"Companies and valuation","aliases":["DOL","operating leverage","fixed cost leverage"],"finds":"Sensitivity of operating profit to sales","needs":"Units, price, variable cost, fixed costs","text":"DOL = Contribution margin / EBIT = Q x (P - VC) / (Q x (P - VC) - FC)"},{"slug":"delta-hedge-shares","name":"Delta Hedge and Hedging Error","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Delta hedging and replication","group":"Markets and instruments","aliases":["delta neutral","dynamic hedging","gamma risk","hedge a short call"],"finds":"Shares needed to hedge options and the leftover gamma loss","needs":"Delta, gamma, contracts, stock move","text":"Shares held to hedge short options = Delta x Number of options x Shares per option; Option price change = Delta x Stock change + 0.5 x Gamma x Stock change^2"},{"slug":"deposit-insurance-coverage","name":"Deposit Insurance Coverage and Premium","level":"Beginner","subject":"Banking & Financial Institutions","section":"Banking","topic":"Deposit insurance","group":"Money, banks and the economy","aliases":["deposit insurance","insured deposits","coverage limit","FDIC premium"],"finds":"How much of the deposit base is protected","needs":"Depositor balances, limit, premium rate","text":"Insured amount = sum over depositors of the smaller of their balance and the coverage limit; Uninsured = total deposits - insured; Premium = premium rate x assessment base (often insured deposits or total liabilities, depending on the scheme)"},{"slug":"disability-coverage-gap","name":"Disability Insurance Income Gap","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Insurance: life, health, property, disability","group":"Personal finance","aliases":["disability insurance","income replacement","elimination period","waiting period"],"finds":"Whether cash plus a policy would cover a period of disability","needs":"Income, expenses, replacement share, waiting period, cash","text":"Monthly benefit = replacement % x monthly income; Monthly gap = monthly expenses - benefit; Cash needed for the waiting period = months waiting x monthly expenses"},{"slug":"illiquidity-discount","name":"Discount for Lack of Marketability (Private Companies)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Valuing private companies and illiquidity discounts","group":"Companies and valuation","aliases":["DLOM","private company discount","illiquidity discount","control premium"],"finds":"Value of a private firm from listed comparables","needs":"Marketable value, discount, control premium","text":"Private company value = Marketable minority value x (1 - Discount for lack of marketability)"},{"slug":"discounted-payback","name":"Discounted Payback Period","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Payback and discounted payback","group":"Companies and valuation","aliases":["discounted payback","payback with discounting"],"finds":"Payback that allows for the time value of money","needs":"Initial investment, rate, cash flows","text":"Discounted payback = payback calculated on each cash flow divided by (1 + r)^t"},{"slug":"disposition-effect-pgr-plr","name":"Disposition Effect: Gains vs Losses Realized","level":"Beginner","subject":"Behavioral Finance","section":"Behavioral","topic":"Disposition effect","group":"Modern finance and practice","aliases":["disposition effect","selling winners too early","Odean PGR PLR","holding losers"],"finds":"Whether you sell winners faster than losers","needs":"Counts of realized and paper gains and losses","text":"Proportion of gains realized = realized gains / (realized gains + paper gains); Proportion of losses realized = realized losses / (realized losses + paper losses); Disposition effect = PGR - PLR (positive means winners are sold more readily than losers)"},{"slug":"diversification-n-assets","name":"Diversification: Risk of an Equally Weighted Portfolio","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Diversification: systematic vs. unsystematic risk","group":"Markets and instruments","aliases":["systematic risk","unsystematic risk","idiosyncratic risk","number of stocks needed"],"finds":"How much risk diversification can remove","needs":"Asset standard deviation, average correlation, number of assets","text":"Variance of n equal-weighted assets = s^2 / n + (1 - 1/n) x rho x s^2"},{"slug":"gordon-growth-model","name":"Dividend Discount Model (Gordon Growth)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Dividend discount model (Gordon growth)","group":"Companies and valuation","aliases":["DDM","Gordon growth","constant growth dividend model","dividend valuation"],"finds":"Value of a steadily growing dividend stream","needs":"Dividend, growth, required return","text":"Price = D0 x (1 + g) / (r - g) = D1 / (r - g)"},{"slug":"dividend-payout-ratio","name":"Dividend Payout Ratio","level":"Beginner","subject":"Corporate Finance","section":"Payout Policy","topic":"Dividends: types and process","group":"Companies and valuation","aliases":["payout ratio","retention ratio","plowback ratio","dividend cover"],"finds":"How much profit is paid out versus kept","needs":"Dividends, net income","text":"Payout ratio = Dividends / Net income, and Retention ratio b = 1 - Payout ratio"},{"slug":"drip-shares","name":"Dividend Reinvestment (DRIP)","level":"Beginner","subject":"Corporate Finance","section":"Payout Policy","topic":"Dividend reinvestment plans","group":"Companies and valuation","aliases":["DRIP","reinvested dividends","dividend reinvestment plan"],"finds":"Extra shares from reinvesting","needs":"Shares held, dividend per share, price","text":"New shares = (Shares held x Dividend per share) / Reinvestment price"},{"slug":"dividend-yield","name":"Dividend Yield and Total Shareholder Yield","level":"Beginner","subject":"Corporate Finance","section":"Payout Policy","topic":"Share buybacks","group":"Companies and valuation","aliases":["yield","buyback yield","shareholder yield"],"finds":"Cash returned to owners as a percentage of value","needs":"Dividend per share, price, buybacks, market cap","text":"Dividend yield = Dividend per share / Price; Buyback yield = Buybacks / Market capitalization; Total shareholder yield = the sum"},{"slug":"yield-on-cost","name":"Dividend Yield on Cost","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Dividend investing","group":"Markets and instruments","aliases":["dividend growth investing","income investing","dividend investing","dividend income"],"finds":"Income growth on the original investment","needs":"Starting dividend, growth, years, prices","text":"Yield on cost = Dividend now / Price you originally paid, where dividend now = starting dividend x (1 + growth)^years"},{"slug":"dollar-cost-averaging","name":"Dollar-Cost Averaging Average Cost","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Dollar-cost averaging","group":"Personal finance","aliases":["regular investing","average cost per share","harmonic mean cost","invest monthly"],"finds":"Your average cost when investing a fixed amount regularly","needs":"A list of purchase prices and the amount invested","text":"Average cost per share = total invested / total shares bought = n / (sum of 1 / price). It is the harmonic mean of the prices, which is never above the plain average price"},{"slug":"double-declining-balance","name":"Double-Declining-Balance Depreciation","level":"Intermediate","subject":"Finance Foundations","section":"Accounting Basics","topic":"Depreciation and amortization","group":"Foundations","aliases":["declining balance","accelerated depreciation","DDB"],"finds":"Depreciation in a chosen year with faster early write-off","needs":"Cost, salvage value, life, year","text":"Depreciation in year t = (2 / L) x book value at the start of the year"},{"slug":"dual-class-voting-power","name":"Dual-Class Shares: Voting Power vs. Ownership","level":"Intermediate","subject":"Corporate Finance","section":"Corporate Governance","topic":"Dual-class shares","group":"Companies and valuation","aliases":["dual class shares","supervoting shares","control versus ownership","wedge"],"finds":"Control compared with ownership","needs":"Shares and votes per class","text":"Voting power = A shares x A votes / (A shares x A votes + B shares x B votes); Economic share = A shares / (A shares + B shares)"},{"slug":"dupont-analysis","name":"DuPont Analysis (3-Step and 5-Step)","level":"Intermediate","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"DuPont analysis","group":"Companies and valuation","aliases":["DuPont identity","ROE decomposition","tax burden","interest burden"],"finds":"What drives ROE: margin, efficiency or leverage","needs":"Net income, EBT, EBIT, sales, average assets and equity","text":"ROE = Net margin x Asset turnover x Equity multiplier. Five-step: ROE = Tax burden x Interest burden x EBIT margin x Asset turnover x Equity multiplier"},{"slug":"duration-gap","name":"Duration Gap and Equity Sensitivity","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Banking","topic":"Asset-liability management","group":"Money, banks and the economy","aliases":["asset liability management","ALM","interest rate risk of a bank","DGAP"],"finds":"A bank\'s equity risk from a parallel rate move","needs":"Durations, asset and liability values, yield change","text":"Duration gap = duration of assets - (liabilities / assets) x duration of liabilities; Change in equity value = - duration gap x assets x (change in yield) / (1 + yield)"},{"slug":"dv01","name":"DV01 (Dollar Value of a Basis Point)","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"DV01 and key rate duration","group":"Markets and instruments","aliases":["PV01","price value of a basis point","PVBP","key rate duration","rate risk in money terms"],"finds":"Rate risk in money for a 1 basis-point move","needs":"Bond terms, yield, position size","text":"DV01 = Modified duration x Price x 0.0001 (the money change in price for a 1 basis-point change in yield)"},{"slug":"supply-chain-finance-return","name":"Early-Payment Discount Return (Supply Chain Finance)","level":"Intermediate","subject":"Corporate Finance","section":"Working Capital Management","topic":"Supply chain finance","group":"Companies and valuation","aliases":["dynamic discounting","supply chain finance","annualized discount return"],"finds":"Annual return on paying a supplier early","needs":"Discount, days paid early","text":"Annualized return = d / (1 - d) x 365 / Days paid early"},{"slug":"eps","name":"Earnings per Share (EPS)","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Income statement","group":"Foundations","aliases":["EPS","profit per share","basic earnings per share"],"finds":"Profit per ordinary share","needs":"Net income, preferred dividends, shares","text":"EPS = (Net income - Preferred dividends) / Weighted average shares"},{"slug":"ebitda-and-its-limits","name":"EBITDA and Its Limits","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"EBITDA and its limits","group":"Companies and valuation","aliases":["EBITDA","EBITDA minus capex","cash EBITDA"],"finds":"How much of EBITDA is real cash","needs":"Net income, tax, interest, D&A, capex, working capital","text":"EBITDA = Net income + Tax + Interest + Depreciation and amortization; Cash proxy = EBITDA - Cash tax - Capex - Increase in working capital - Interest"},{"slug":"economic-order-quantity","name":"Economic Order Quantity (EOQ)","level":"Intermediate","subject":"Corporate Finance","section":"Working Capital Management","topic":"Inventory management","group":"Companies and valuation","aliases":["EOQ","inventory ordering","optimal order size"],"finds":"The cost-minimizing order size","needs":"Annual demand, cost per order, holding cost","text":"EOQ = square root of (2 x Annual demand x Cost per order / Holding cost per unit)"},{"slug":"economic-value-added","name":"Economic Value Added (EVA)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Residual income / economic value added (EVA)","group":"Companies and valuation","aliases":["EVA","economic profit","NOPAT less capital charge"],"finds":"Profit after the full cost of capital","needs":"NOPAT, WACC, invested capital","text":"EVA = NOPAT - WACC x Invested capital"},{"slug":"ear","name":"Effective Annual Rate (EAR)","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Effective annual rate vs. APR","group":"Foundations","aliases":["EAR","effective annual interest rate","APR to EAR","APY","annual percentage yield"],"finds":"True yearly rate after compounding","needs":"Quoted rate, times per year","text":"EAR = (1 + APR/m)^m - 1"},{"slug":"effective-duration-convexity","name":"Effective Duration and Convexity","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Callable and putable bonds","group":"Markets and instruments","aliases":["option adjusted duration","duration of callable bonds","empirical duration","full repricing"],"finds":"Rate sensitivity for bonds with embedded options","needs":"Prices after yields shift down and up","text":"Effective duration = (Price when yields fall - Price when yields rise) / (2 x Price now x Yield change); Effective convexity = (P- + P+ - 2 x P0) / (P0 x Yield change^2)"},{"slug":"effective-spread","name":"Effective Spread and Price Impact","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Market microstructure","group":"Markets and instruments","aliases":["realized spread","market microstructure","trade execution quality","adverse selection"],"finds":"The true cost of a trade and who kept it","needs":"Trade price, mid prices before and after, direction","text":"Effective spread = 2 x D x (Trade price - Mid price before the trade); Realized spread uses the mid price some minutes later; D = +1 for a buy and -1 for a sell"},{"slug":"efficiency-turnover-ratios","name":"Efficiency Ratios: Asset, Inventory, Receivable and Payable Turnover","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Efficiency ratios: asset turnover, inventory turnover, DSO, DPO","group":"Companies and valuation","aliases":["asset turnover","inventory turnover","receivables turnover","payables turnover","fixed asset turnover"],"finds":"How many times a year each balance is used up and replaced","needs":"Revenue, COGS, average balances","text":"Asset turnover = Revenue / Average total assets; Fixed asset turnover = Revenue / Average net fixed assets; Inventory turnover = COGS / Average inventory; Receivables turnover = Revenue / Average receivables; Payables turnover = COGS / Average payables"},{"slug":"embedded-finance-revenue","name":"Embedded Finance: Platform Revenue from Financial Products","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Embedded finance","group":"Modern finance and practice","aliases":["embedded finance","banking as a service","attach rate","take rate","revenue share"],"finds":"What a platform earns from embedded finance","needs":"Volume, attach rate, take rate, partner cost, fixed cost","text":"Revenue = platform sales volume x share of sales that use the financial product (attach rate) x take rate; Profit = volume x attach rate x (take rate - partner cost rate) - fixed cost; Break-even attach rate = fixed cost / (volume x (take rate - cost rate))"},{"slug":"emergency-fund-target","name":"Emergency Fund Target and Monthly Saving","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Emergency funds","group":"Personal finance","aliases":["emergency funds","rainy day fund","months of expenses","cash reserve"],"finds":"How much to hold in cash and how much to save each month","needs":"Essential spending, months of cover, current fund, timeline","text":"Target = months of cover x monthly essential spending; Monthly saving = (Target - current fund x (1 + i)^n) / [((1 + i)^n - 1) / i], where i is the monthly interest rate and n is the number of months"},{"slug":"unhedged-foreign-return","name":"Emerging Market Return: Local, Unhedged and Hedged","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Emerging markets investing","group":"Money, banks and the economy","aliases":["emerging markets investing","currency return","hedging cost","local currency return"],"finds":"What a local return is worth in dollars, hedged and unhedged","needs":"Local return, currency change, interest rates","text":"Dollar return unhedged = (1 + local return) x (1 + change in the local currency against the dollar) - 1; Dollar return hedged with a forward = (1 + local return) x (1 + dollar interest rate) / (1 + local interest rate) - 1. Hedging cost is roughly the local rate minus the dollar rate"},{"slug":"employer-match-vesting","name":"Employer Match and Vesting","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Employer pension contributions, matching and vesting","group":"Personal finance","aliases":["pension matching","401k match","vested balance","free money"],"finds":"Employer money earned, vested and left on the table","needs":"Salary, contribution, match terms, vesting terms","text":"Employer match = match rate x min(your contribution %, match cap %) x salary; Vested share v rises with years of service (0 before the start year, 1 after the full year, in between linear for a graded schedule); Vested match = match x v"},{"slug":"endowment-spending-rule","name":"Endowment Spending Rule (Yale)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Management","topic":"Endowment model (Yale)","group":"Markets and instruments","aliases":["Yale endowment model","smoothed spending","endowment spending policy"],"finds":"A smoothed yearly spending amount","needs":"Last spending, market value, weight, target rate","text":"Spending this year = rho x Last year\'s spending + (1 - rho) x Target spending rate x Last year\'s market value"},{"slug":"erm-risk-aggregation","name":"Enterprise Risk Aggregation with Correlation","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Enterprise risk management","group":"Risk and quantitative methods","aliases":["ERM","diversification of risk types","capital aggregation","correlation matrix of risks"],"finds":"Combined capital after diversification","needs":"Capital per risk, correlation matrix","text":"Total capital = square root of the sum over all pairs of (Correlation between risks i and j x Capital for risk i x Capital for risk j)"},{"slug":"ev-to-equity-value","name":"Enterprise Value to Equity Value","level":"Beginner","subject":"Valuation","section":"Valuation","topic":"Enterprise value vs. equity value","group":"Companies and valuation","aliases":["EV bridge","equity bridge","net debt","value per share"],"finds":"Value belonging to ordinary shareholders","needs":"EV, debt, cash, minority interest, preferred, shares","text":"Equity value = Enterprise value - Debt + Cash - Minority interest - Preferred stock"},{"slug":"equity-multiplier","name":"Equity Multiplier","level":"Beginner","subject":"Finance Foundations","section":"What Finance Is","topic":"Liquidity, solvency and leverage (concepts)","group":"Foundations","aliases":["financial leverage","assets to equity"],"finds":"Assets held per unit of owners\' money","needs":"Total assets, total equity","text":"Equity multiplier = Total assets / Total equity"},{"slug":"research-pitch-risk-reward","name":"Equity Research Pitch: Target Price and Risk/Reward","level":"Intermediate","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Write an equity research pitch","group":"Modern finance and practice","aliases":["write an equity research pitch","target price","bull base bear","upside downside ratio","implied multiple"],"finds":"The numbers at the core of a stock recommendation","needs":"EPS forecast, target multiple, scenario prices and probabilities","text":"Base target price = forecast earnings per share x target price-to-earnings multiple; Expected value = sum of probability x price over bull, base and bear; Upside to expected value = expected price / current price - 1; Risk/reward = (bull price - current price) / (current price - bear price); Implied multiple at the current price = price / forecast EPS"},{"slug":"equivalent-annual-annuity","name":"Equivalent Annual Annuity (EAA)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"NPV rule","group":"Companies and valuation","aliases":["EAA","equivalent annual cost","unequal project lives","EAC"],"finds":"A yearly figure to compare projects of different lengths","needs":"NPV, rate, project life","text":"EAA = NPV / ((1 - (1 + r)^-n) / r)"},{"slug":"esg-rating-divergence","name":"ESG Rating Divergence Between Providers","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"ESG ratings and their criticisms","group":"Modern finance and practice","aliases":["ESG ratings and their criticisms","rater disagreement","rating correlation","rank correlation"],"finds":"How much two ESG ratings disagree","needs":"Scores for the same companies from two providers","text":"Correlation between two providers\' scores = covariance of the scores / (standard deviation of A x standard deviation of B); Mean absolute gap = average of |score A - score B|; Share of companies on which the providers rank in opposite halves = count of firms above the median on one and below on the other / number of firms. Credit rating agencies tend to have correlations near 0.99, ESG raters much lower (studies report about 0.5 to 0.6)"},{"slug":"estate-tax-basic","name":"Estate Tax Estimate","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Estate planning basics","group":"Personal finance","aliases":["estate planning basics","inheritance tax","exemption threshold","taxable estate"],"finds":"A rough estate tax and what is left","needs":"Estate size, debts, gifts, threshold, rate","text":"Taxable estate = gross estate - debts and expenses - charitable gifts; Tax = tax rate x the part of the taxable estate above the exemption threshold"},{"slug":"etf-premium-tracking","name":"ETF Premium/Discount and Tracking Difference","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Exchange-traded funds (ETFs)","group":"Markets and instruments","aliases":["ETF NAV gap","tracking difference","creation and redemption","ETF cost"],"finds":"Whether an ETF trades fairly and tracks its index","needs":"Price, NAV, ETF and index returns","text":"Premium (or discount) = (Market price - NAV) / NAV; Tracking difference = ETF return - Index return"},{"slug":"gas-fee-cost","name":"Ethereum Gas Fee Cost","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Ethereum and smart contracts","group":"Modern finance and practice","aliases":["Ethereum and smart contracts","gwei","base fee","priority tip","transaction cost on chain"],"finds":"The cost of a blockchain transaction","needs":"Gas used, base fee, tip, ETH price","text":"Fee in ETH = gas used x (base fee + priority tip) in gwei x 0.000000001; Fee in money = fee in ETH x price of ETH; The base fee is burned, so burned part = gas used x base fee; Simple transfers use 21,000 gas and smart-contract calls use much more"},{"slug":"event-study-car","name":"Event Study: Abnormal and Cumulative Abnormal Return","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Market Efficiency","topic":"Event studies","group":"Markets and instruments","aliases":["abnormal return","CAR","market model event study","announcement effect"],"finds":"How much an event moved a stock","needs":"Stock and market returns, alpha, beta, residual risk","text":"Abnormal return = actual return - (alpha + beta x market return); CAR = sum of the abnormal returns; t = CAR / (s x sqrt(N))"},{"slug":"ewma-volatility","name":"EWMA Volatility (RiskMetrics)","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"GARCH volatility models","group":"Risk and quantitative methods","aliases":["exponentially weighted moving average","RiskMetrics","decay factor","GARCH volatility models"],"finds":"A volatility estimate that favors recent returns","needs":"A list of daily returns and a decay factor","text":"Variance today = lambda x yesterday\'s variance + (1 - lambda) x yesterday\'s return squared. RiskMetrics uses lambda = 0.94 for daily data"},{"slug":"ex-dividend-price","name":"Ex-Dividend Price Drop","level":"Beginner","subject":"Corporate Finance","section":"Payout Policy","topic":"Dividend irrelevance theory","group":"Companies and valuation","aliases":["dividend irrelevance","price after dividend","ex dividend date"],"finds":"Share price after a dividend","needs":"Price and dividend","text":"Ex-dividend price = Price before the dividend - Dividend per share"},{"slug":"excess-kurtosis","name":"Excess Kurtosis","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Skewness and kurtosis (fat tails)","group":"Foundations","aliases":["kurtosis","fat tails","fourth moment","tail risk"],"finds":"How fat the tails of returns are","needs":"List of returns","text":"Excess kurtosis = average of ((Ri - mean) / standard deviation)^4, minus 3"},{"slug":"expanded-accounting-equation","name":"Expanded Accounting Equation","level":"Intermediate","subject":"Finance Foundations","section":"Accounting Basics","topic":"Double-entry bookkeeping","group":"Foundations","aliases":["full accounting equation","equity breakdown","accounting equation with revenues and expenses"],"finds":"How revenues, expenses and dividends fit the accounting equation","needs":"Liabilities, capital, retained earnings, revenues, expenses, dividends","text":"Assets = Liabilities + Contributed capital + Beginning retained earnings + Revenues - Expenses - Dividends"},{"slug":"expectations-theory","name":"Expectations Theory with a Liquidity Premium","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Expectations, liquidity preference and segmentation theories","group":"Markets and instruments","aliases":["liquidity preference","segmented markets","pure expectations","term premium"],"finds":"What the curve implies about expected rates and risk premium","needs":"Short rate, expected short rate, premium","text":"(1 + two-year spot)^2 = (1 + one-year spot) x (1 + expected one-year rate next year + liquidity premium)"},{"slug":"expected-unexpected-loss","name":"Expected and Unexpected Credit Loss","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Probability of default, LGD, EAD","group":"Risk and quantitative methods","aliases":["EL","UL","PD LGD EAD","loss given default","exposure at default"],"finds":"Average and variable credit losses","needs":"PD, recovery, exposure, LGD volatility","text":"Expected loss = PD x LGD x EAD; Unexpected loss = EAD x sqrt(PD x (LGD volatility)^2 + LGD^2 x PD x (1 - PD)); LGD = 1 - Recovery rate"},{"slug":"high-yield-expected-return","name":"Expected Return after Defaults: Investment Grade vs. High Yield","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Investment grade vs. high yield","group":"Markets and instruments","aliases":["junk bond","default adjusted yield","promised yield versus expected yield"],"finds":"Return after expected default losses","needs":"Yields, default probabilities, recovery, risk-free rate","text":"Expected return = Promised yield - Probability of default x (1 - Recovery rate)"},{"slug":"portfolio-expected-return","name":"Expected Return of a Portfolio","level":"Beginner","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Expected return and risk of a portfolio","group":"Markets and instruments","aliases":["weighted average return","portfolio return","asset allocation return","core satellite return"],"finds":"Expected return of a mix of assets","needs":"Weights, expected returns","text":"Portfolio expected return = w1 x E(R1) + w2 x E(R2) + ... + wn x E(Rn)"},{"slug":"expected-shortfall","name":"Expected Shortfall (CVaR)","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Expected shortfall (CVaR)","group":"Risk and quantitative methods","aliases":["CVaR","conditional value at risk","average tail loss","ES"],"finds":"The average loss beyond VaR","needs":"Portfolio value, mean and standard deviation, returns, confidence","text":"Parametric ES = V x (sd x pdf(z) / (1 - c) - mean); Historical ES = -V x the average of the returns that fall at or below the VaR cut-off"},{"slug":"expected-value","name":"Expected Value","level":"Beginner","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Probability basics: expected value and conditional probability","group":"Foundations","aliases":["expected return","probability weighted average","E(X)"],"finds":"Probability-weighted average outcome","needs":"Probabilities, outcomes","text":"E(X) = p1 x x1 + p2 x x2 + ... + pn x xn"},{"slug":"evpi","name":"Expected Value of Perfect Information","level":"Intermediate","subject":"Decision-Making, Risk & Model Limitations","section":"Decision quality","topic":"Decision quality","group":"Risk and quantitative methods","aliases":["value of information","decision tree","expected monetary value","EMV","how much to pay for research"],"finds":"The most a forecast or study could be worth","needs":"State probabilities and a payoff table","text":"Expected value of perfect information = (expected payoff if you could pick the best action after seeing the state) - (best expected payoff when you must choose before seeing it)"},{"slug":"ema-crossover","name":"Exponential Moving Average Crossover","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Technical analysis","group":"Markets and instruments","aliases":["EMA","MACD idea","golden cross","death cross","trend following"],"finds":"A trend signal from two moving averages","needs":"Prices, two periods","text":"EMA today = alpha x Price today + (1 - alpha) x EMA yesterday, with alpha = 2 / (n + 1)"},{"slug":"fama-french-model","name":"Fama-French Factor Model Return","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Fama-French three- and five-factor models","group":"Markets and instruments","aliases":["Fama French three factor","five factor model","SMB HML RMW CMA","size and value factors"],"finds":"Return implied by market, size and value exposure","needs":"Risk-free rate, factor betas, factor premiums","text":"Expected return = rf + b_mkt x MKT + b_smb x SMB + b_hml x HML (+ b_rmw x RMW + b_cma x CMA for five factors)"},{"slug":"family-office-breakeven","name":"Family Office Break-Even Size","level":"Beginner","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Family offices","group":"Money, banks and the economy","aliases":["family offices","single family office","multi-family office","cost of wealth management"],"finds":"The wealth level where a family office pays for itself","needs":"Fixed and variable costs, alternative fee, wealth","text":"Break-even wealth = fixed annual cost / (fee rate of the outside alternative - variable cost rate); Cost as a share of wealth = fixed cost / wealth + variable cost rate"},{"slug":"fi-number-4-percent","name":"Financial Independence Number and the 4% Rule","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Financial independence and the 4% rule","group":"Personal finance","aliases":["financial independence","FIRE","4 percent rule","safe withdrawal rate","25 times expenses"],"finds":"The portfolio size that supports your spending and the years to reach it","needs":"Spending, withdrawal rate, portfolio, saving, real return","text":"Financial independence number = annual spending / safe withdrawal rate (4% gives 25 x spending); Years to get there = ln[(FI x r + s) / (current portfolio x r + s)] / ln(1 + r), where s is the yearly saving and r is the real return"},{"slug":"fd-explicit-step","name":"Finite Difference: Explicit Scheme Step and Stability","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Finite difference methods","group":"Risk and quantitative methods","aliases":["finite difference methods","heat equation","explicit scheme","numerical PDE","CFL condition"],"finds":"One explicit finite difference step and whether it is stable","needs":"Neighbouring values, diffusion coefficient, steps","text":"New value at a grid point = Old value + alpha x (Value on the right - 2 x Old value + Value on the left), with alpha = D x time step / (grid spacing)^2; the scheme is stable only if alpha <= 0.5"},{"slug":"fiscal-multiplier","name":"Fiscal Multiplier","level":"Intermediate","subject":"Economics for Finance","section":"Money, Rates and Policy","topic":"Fiscal policy: government spending, taxes and deficits","group":"Money, banks and the economy","aliases":["fiscal policy","spending multiplier","tax cut multiplier","balanced budget multiplier"],"finds":"How much output a fiscal change adds","needs":"MPC, tax rate, import share, size of the change","text":"Spending multiplier = 1 / (1 - MPC x (1 - tax rate) + import share); Tax-cut multiplier = - MPC / (1 - MPC x (1 - tax rate) + import share). Change in GDP = multiplier x change in spending"},{"slug":"fixed-charge-net-debt","name":"Fixed Charge Coverage and Net Debt to EBITDA","level":"Intermediate","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Solvency ratios: debt/equity, interest coverage","group":"Companies and valuation","aliases":["solvency ratios","lease adjusted coverage","leverage ratio","net leverage"],"finds":"How safely debts and fixed charges are covered","needs":"EBIT, lease payments, interest, debt, cash, EBITDA","text":"Fixed charge coverage = (EBIT + Lease payments) / (Interest + Lease payments); Net debt to EBITDA = (Total debt - Cash) / EBITDA"},{"slug":"mortgage-fixed-vs-arm","name":"Fixed vs Adjustable-Rate Mortgage","level":"Intermediate","subject":"Personal Finance","section":"Personal Finance","topic":"Mortgages: fixed vs. adjustable","group":"Personal finance","aliases":["mortgages","ARM reset","teaser rate","mortgage payment shock"],"finds":"What each mortgage costs, including a rate reset","needs":"Loan, both rates, reset timing, reset rate","text":"Payment = i x Loan / (1 - (1 + i)^(-n)); Balance after k payments = Loan x ((1 + i)^n - (1 + i)^k) / ((1 + i)^n - 1); after the rate resets, the new payment is the payment formula on the remaining balance over the remaining months"},{"slug":"frn-price","name":"Floating Rate Note Coupon and Price","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Floating rate notes","group":"Markets and instruments","aliases":["FRN","quoted margin","discount margin","SOFR plus spread","floating rate bond"],"finds":"The price of a floating rate note","needs":"Reference rate, margins, term, frequency","text":"Coupon = (Reference rate + Quoted margin) / payments per year x Face value; Price = coupons and face value discounted at (Reference rate + Discount margin) / payments per year"},{"slug":"forecast-calibration","name":"Forecast Calibration and Brier Score","level":"Beginner","subject":"Behavioral Finance","section":"Behavioral","topic":"Overconfidence","group":"Modern finance and practice","aliases":["overconfidence","calibration","hit rate versus confidence","probability forecast accuracy"],"finds":"Whether your confidence matches reality","needs":"A list of probability forecasts and what happened","text":"Overconfidence = average stated probability - share of forecasts that came true; Brier score = average of (stated probability - outcome)^2, where the outcome is 1 if the event happened and 0 if not (0 is perfect and 0.25 is what always saying 50% scores)"},{"slug":"foreign-project-npv","name":"Foreign Project NPV: Two Equivalent Methods","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"International capital budgeting","group":"Money, banks and the economy","aliases":["international capital budgeting","NPV in home currency","foreign currency discount rate","project in another country"],"finds":"A foreign project\'s value to the parent company, by two routes","needs":"Local cash flows, spot, inflation, home required return","text":"Method 1: convert each foreign cash flow at its expected spot rate and discount at the home required return. Method 2: discount the foreign cash flows at the foreign required return, then convert the NPV at today\'s spot. Expected spot S_t = S_0 x ((1 + home inflation) / (1 + foreign inflation))^t; Foreign required return = (1 + home) x (1 + foreign inflation) / (1 + home inflation) - 1"},{"slug":"forward-contract-value","name":"Forward Contract: Fair Price, Value and Payoff","level":"Beginner","subject":"Derivatives","section":"Derivatives","topic":"Forwards","group":"Markets and instruments","aliases":["forward","forward agreement","long forward","short forward"],"finds":"A forward\'s fair price, value and payoff","needs":"Spot, delivery price, rate, times","text":"Fair forward price = Spot x (1 + r)^T; Value of a long forward = Spot now - Delivery price / (1 + r)^(time left); Payoff to the long at expiry = Spot at expiry - Delivery price"},{"slug":"fx-forward-points","name":"Forward Exchange Rate and Forward Points","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Spot and forward exchange rates","group":"Money, banks and the economy","aliases":["spot and forward exchange rates","forward premium","forward discount","swap points"],"finds":"The forward rate and its premium or discount","needs":"Spot rate, both interest rates, days","text":"Forward rate = spot x (1 + domestic rate x days / 360) / (1 + foreign rate x days / 360), where rates are quoted as domestic currency per 1 unit of foreign currency; Forward points = (forward - spot) x 10,000; Annualized forward premium = (F / S - 1) x 360 / days"},{"slug":"forward-rate","name":"Forward Rate from Spot Rates","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Spot rates, forward rates and bootstrapping","group":"Markets and instruments","aliases":["implied forward rate","forward interest rate","no arbitrage forward rate"],"finds":"The rate for a future period implied by today\'s curve","needs":"Two spot rates and their times","text":"Forward rate = [(1 + spot rate to t2)^t2 / (1 + spot rate to t1)^t1]^(1 / (t2 - t1)) - 1"},{"slug":"fcfe","name":"Free Cash Flow to Equity (FCFE)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Free cash flow to equity (FCFE)","group":"Companies and valuation","aliases":["FCFE","free cash flow to equity","levered free cash flow"],"finds":"Cash available to shareholders","needs":"FCFF, interest, tax rate, net borrowing","text":"FCFE = FCFF - Interest x (1 - T) + Net borrowing"},{"slug":"fcff","name":"Free Cash Flow to the Firm (FCFF)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Free cash flow to firm (FCFF)","group":"Companies and valuation","aliases":["FCFF","unlevered free cash flow","free cash flow to firm","UFCF"],"finds":"Cash flow available to all capital providers","needs":"EBIT, tax rate, D&A, capex, change in NWC","text":"FCFF = EBIT x (1 - T) + Depreciation and amortization - Capital expenditure - Increase in net working capital"},{"slug":"free-cash-flow-conversion","name":"Free Cash Flow vs. Net Income","level":"Beginner","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Free cash flow vs. net income","group":"Companies and valuation","aliases":["FCF conversion","cash conversion of earnings","free cash flow yield"],"finds":"Cash left after investment compared with reported profit","needs":"Operating cash flow, capex, net income, market cap","text":"Free cash flow = Cash flow from operations - Capital expenditure; Conversion = FCF / Net income; FCF yield = FCF / Market cap"},{"slug":"fundamental-law-active","name":"Fundamental Law of Active Management","level":"Intermediate","subject":"Advanced Investment Practice","section":"Portfolio construction and evaluation","topic":"Portfolio construction and evaluation","group":"Modern finance and practice","aliases":["portfolio construction and evaluation","information coefficient","breadth","transfer coefficient","expected active return"],"finds":"How much skill and breadth an active manager needs","needs":"IC, breadth, transfer coefficient, tracking error","text":"Information ratio (expected) = transfer coefficient x information coefficient x square root of breadth; Expected active return (alpha) = information ratio x tracking error; Information coefficient is the correlation between forecasts and outcomes; Breadth is the number of independent bets per year; Transfer coefficient is how much of the forecast makes it into the portfolio (1 = fully, below 1 with constraints); Breadth needed for a target IR = (IR / (TC x IC))^2"},{"slug":"funded-ratio","name":"Funded Ratio (Liability-Driven Investing)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Management","topic":"Liability-driven investing","group":"Markets and instruments","aliases":["pension funded status","liability driven investing","surplus","LDI"],"finds":"Whether assets cover future obligations","needs":"Assets, discount rate, liability payments","text":"Funded ratio = Assets / Present value of liabilities, where each liability payment is discounted at rate r"},{"slug":"fv-lump-sum","name":"Future Value of a Lump Sum","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Future value","group":"Foundations","aliases":["compound interest formula","future value","FV","compound interest"],"finds":"Future value of one amount","needs":"Amount today, rate, periods","text":"FV = PV x (1 + r)^n"},{"slug":"fv-annuity-due","name":"Future Value of an Annuity Due","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Annuities and annuities due","group":"Foundations","aliases":["savings at the start of the period","FV annuity due"],"finds":"Future value of deposits made at the start of each period","needs":"Deposit, rate, number of deposits","text":"FV(due) = PMT x ((1 + r)^n - 1) / r x (1 + r)"},{"slug":"fv-ordinary-annuity","name":"Future Value of an Ordinary Annuity","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Annuities and annuities due","group":"Foundations","aliases":["future value of annuity","savings plan formula","regular deposits","FV annuity"],"finds":"Future value of regular deposits","needs":"Payment, rate, number of payments","text":"FV = PMT x ((1 + r)^n - 1) / r"},{"slug":"fv-compounding-m","name":"Future Value with Compounding m Times a Year","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Future value","group":"Foundations","aliases":["compound interest monthly","compounding frequency","quarterly compounding","compound interest formula with frequency"],"finds":"Future value with monthly, quarterly or daily compounding","needs":"Amount today, annual rate, times per year, years","text":"FV = PV x (1 + r/m)^(m x t)"},{"slug":"futures-margin-account","name":"Futures Daily Settlement and Margin Account","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Futures and margining","group":"Markets and instruments","aliases":["marking to market","variation margin","initial margin","maintenance margin","margin call futures"],"finds":"A futures margin account\'s balance and any margin call","needs":"Contracts, multiplier, settlement prices, margins","text":"Daily gain on a long position = Contracts x Multiplier x (Today\'s futures price - Yesterday\'s futures price); Margin balance = Previous balance + Daily gain"},{"slug":"forward-price-cost-of-carry","name":"Futures Price: Cost of Carry","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Pricing forwards and futures (cost of carry)","group":"Markets and instruments","aliases":["cost of carry","convenience yield","storage cost","fair value of a futures","basis"],"finds":"The no-arbitrage futures price","needs":"Spot, rate, storage cost, yield, time","text":"Futures price = Spot x e^((risk-free rate + storage cost - yield) x time)"},{"slug":"fx-forward-hedge","name":"FX Forward Hedge and Covered Interest Parity","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Foreign exchange risk hedging","group":"Risk and quantitative methods","aliases":["forward exchange rate","currency hedge","covered interest parity","forward points","hedging receivables"],"finds":"A locked-in exchange rate and what hedging is worth","needs":"Spot, interest rates, time, amount","text":"Forward rate = Spot rate x (1 + home rate x time) / (1 + foreign rate x time), with rates quoted per year and the rate quoted as home currency per unit of foreign currency"},{"slug":"garch-forecast","name":"GARCH(1,1) Variance Forecast","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"GARCH volatility models","group":"Risk and quantitative methods","aliases":["GARCH volatility models","conditional variance","volatility clustering","long-run variance"],"finds":"Tomorrow\'s volatility and the path back to normal","needs":"Parameters, last return and last volatility","text":"Next-period variance = omega + alpha x (last return)^2 + beta x (last variance); Long-run variance = omega / (1 - alpha - beta); k periods ahead: long-run + (alpha + beta)^k x (next variance - long-run)"},{"slug":"gdp-nominal-real","name":"GDP: Expenditure Approach, Real GDP and Deflator","level":"Beginner","subject":"Economics for Finance","section":"How the Economy Works","topic":"GDP and how it is measured","group":"Money, banks and the economy","aliases":["GDP and how it is measured","C+I+G+NX","GDP deflator","real growth"],"finds":"GDP, real GDP and growth","needs":"The four spending components, the deflator and last year\'s real GDP","text":"GDP = Consumption + Investment + Government spending + (Exports - Imports); Real GDP = Nominal GDP / (GDP deflator / 100); Growth = Real GDP this year / Real GDP last year - 1"},{"slug":"gdpr-maximum-fine","name":"GDPR Maximum Fine Cap","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Data privacy rules (GDPR, Taiwan PDPA, India DPDP Act)","group":"Modern finance and practice","aliases":["data privacy rules","GDPR","4% of turnover","20 million euros","administrative fine"],"finds":"The largest fine under the GDPR","needs":"Worldwide annual turnover","text":"Under the EU GDPR, the highest tier of fines (for breaches of core principles, consent and data-subject rights) can reach the larger of 20 million euros and 4% of the firm\'s total worldwide annual turnover of the previous year; The lower tier (for example, record-keeping and security duties) reaches the larger of 10 million euros and 2% of turnover; Turnover above 500 million euros makes the percentage cap the larger one"},{"slug":"gbm-terminal-distribution","name":"Geometric Brownian Motion: Terminal Price Distribution","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Geometric Brownian motion","group":"Risk and quantitative methods","aliases":["lognormal price","GBM","median vs mean price","probability above strike"],"finds":"Mean, median and chances for a price after some years","needs":"Price, return, volatility, time, threshold","text":"Price at T = S0 x e^((mu - sigma^2 / 2) x T + sigma x sqrt(T) x Z), where Z is a standard normal; Mean = S0 x e^(mu T); Median = S0 x e^((mu - sigma^2 / 2) T); P(S_T > K) = N([ln(S0 / K) + (mu - sigma^2 / 2) T] / (sigma sqrt(T)))"},{"slug":"geometric-mean-return","name":"Geometric Mean Return","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Arithmetic vs. geometric mean returns","group":"Foundations","aliases":["compound average return","time-weighted return","average compound return"],"finds":"Average compound growth when returns vary","needs":"List of returns","text":"Geometric mean = ((1 + R1) x (1 + R2) x ... x (1 + Rn))^(1/n) - 1"},{"slug":"good-debt-test","name":"Good Debt vs Bad Debt Test","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Good debt vs. bad debt","group":"Personal finance","aliases":["good debt bad debt","borrowing to invest","return on borrowed money","after-tax cost of debt"],"finds":"Whether a loan is likely to pay for itself","needs":"Loan amount, rate, tax treatment, expected return","text":"After-tax borrowing cost = interest rate x (1 - tax rate on deductible interest); Spread = expected return of what the debt buys - after-tax borrowing cost; Annual gain = amount borrowed x spread"},{"slug":"purchase-price-allocation-goodwill","name":"Goodwill from Purchase Price Allocation","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Purchase price allocation","group":"Companies and valuation","aliases":["goodwill","PPA","purchase accounting","excess purchase price"],"finds":"Goodwill created by an acquisition","needs":"Price, fair value of assets and liabilities","text":"Goodwill = Purchase price - (Fair value of identifiable assets - Fair value of liabilities assumed)"},{"slug":"goodwill-impairment-test","name":"Goodwill Impairment Test","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Goodwill and impairments","group":"Companies and valuation","aliases":["impairment loss","recoverable amount","cash generating unit","carrying amount"],"finds":"The write-down when a unit is worth less than its book value","needs":"Carrying amount, goodwill, fair value, value in use","text":"Recoverable amount = higher of (Fair value less costs of disposal) and (Value in use); Impairment loss = Carrying amount - Recoverable amount, if positive; it first reduces goodwill"},{"slug":"debt-dynamics","name":"Government Debt Dynamics","level":"Intermediate","subject":"Economics for Finance","section":"Money, Rates and Policy","topic":"Fiscal policy: government spending, taxes and deficits","group":"Money, banks and the economy","aliases":["fiscal policy","debt to GDP","primary balance","r minus g","debt sustainability"],"finds":"Whether debt is rising and what surplus stops it","needs":"Debt ratio, interest rate, growth, primary balance","text":"Next year\'s debt-to-GDP = this year\'s x (1 + interest rate) / (1 + GDP growth) - primary balance (as a share of GDP; a surplus is positive); The primary balance that holds debt steady = debt ratio x (r - g) / (1 + g)"},{"slug":"graham-number","name":"Graham Number","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Investment styles of famous investors (Graham, Buffett, Lynch)","group":"Markets and instruments","aliases":["Benjamin Graham","defensive investor","intrinsic value Graham","margin of safety"],"finds":"A ceiling price for a defensive value investor","needs":"EPS, book value, price","text":"Graham number = square root of (22.5 x Earnings per share x Book value per share)"},{"slug":"grant-element","name":"Grant Element of a Concessional Loan","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Development banks and multilaterals","group":"Money, banks and the economy","aliases":["development banks","multilateral lending","concessionality","subsidy in a soft loan"],"finds":"How much of a soft loan is a grant","needs":"Loan size, interest rate, maturity, commercial rate","text":"Grant element = (face value of the loan - present value of its repayments discounted at a commercial rate) / face value. For a loan that pays interest each year and the principal at the end: PV = coupon x annuity factor + face / (1 + d)^N"},{"slug":"greenium-and-step-up","name":"Green Bonds: Greenium Saving and Sustainability-Linked Step-Up Cost","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"Green, social and sustainability-linked bonds","group":"Modern finance and practice","aliases":["green, social and sustainability-linked bonds","greenium","coupon step-up","use of proceeds bond","KPI-linked bond"],"finds":"What a green label saves and what a missed target costs","needs":"Notional, yields, years, step-up size","text":"Greenium = yield on a similar ordinary bond - yield on the green bond; Present value of the saving to the issuer = sum over years of (notional x greenium) discounted at the ordinary yield; For a sustainability-linked bond, extra interest if the target is missed = notional x coupon step-up x remaining years after the test date"},{"slug":"greenwashing-alignment-gap","name":"Greenwashing Check: Claimed vs Aligned Share","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"Greenwashing","group":"Modern finance and practice","aliases":["greenwashing","taxonomy alignment","green revenue share","claim gap","green claims"],"finds":"How far a green claim runs ahead of the evidence","needs":"Total revenue, aligned revenue, claimed share","text":"Aligned share = revenue from activities that meet an official green taxonomy criteria / total revenue; Claim gap = share claimed in marketing - aligned share; Overstatement ratio = claimed share / aligned share; Fund version: share of holdings that meet the fund\'s stated sustainability criteria vs share claimed"},{"slug":"growing-perpetuity","name":"Growing Perpetuity","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Perpetuities and growing perpetuities","group":"Foundations","aliases":["Gordon growth","growing perpetuity formula","constant growth"],"finds":"Value of payments that grow forever","needs":"First payment, rate, growth rate","text":"PV = C1 / (r - g)"},{"slug":"growth-accounting","name":"Growth Accounting and Productivity","level":"Intermediate","subject":"Economics for Finance","section":"How the Economy Works","topic":"Productivity and long-run growth","group":"Money, banks and the economy","aliases":["productivity and long-run growth","Solow residual","total factor productivity","labor productivity"],"finds":"How much growth comes from better productivity","needs":"Output, capital and labor growth, capital share","text":"Productivity growth (Solow residual) = output growth - capital share x capital growth - (1 - capital share) x labor growth; Labor productivity growth = output growth - labor growth"},{"slug":"health-cost-sharing","name":"Health Plan Cost Comparison","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Insurance: life, health, property, disability","group":"Personal finance","aliases":["deductible","out of pocket maximum","coinsurance","health insurance plan comparison"],"finds":"Which health plan costs less at a given level of use","needs":"Each plan\'s deductible, coinsurance, maximum and premium","text":"What you pay = the smaller of (out-of-pocket maximum) and [the part of the bill up to the deductible + coinsurance % x the part of the bill above the deductible]; Total yearly cost = what you pay + annual premiums"},{"slug":"hedge-fund-fees","name":"Hedge Fund Fees: Management, Performance, Hurdle and High-Water Mark","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Hedge funds","group":"Money, banks and the economy","aliases":["hedge funds","2 and 20","incentive fee","net of fee return"],"finds":"The net return an investor keeps after fees","needs":"Starting NAV, return, fee rates, hurdle, high-water mark","text":"Management fee = rate x starting NAV; Performance fee = performance rate x the amount by which NAV after the management fee exceeds the higher of (starting NAV x (1 + hurdle)) and the high-water mark; Net return = (NAV after both fees / starting NAV) - 1"},{"slug":"money-market-hedge","name":"Hedging a Foreign Currency Receivable","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Currency risk for multinationals","group":"Money, banks and the economy","aliases":["currency risk for multinationals","transaction exposure","forward hedge vs money market hedge","natural hedge"],"finds":"What a hedge locks in compared with leaving the exposure open","needs":"Amount, spot, forward, rates, scenarios","text":"Forward hedge: dollars received = foreign amount x forward rate. Money market hedge: borrow the present value of the receivable in foreign currency (amount / (1 + foreign rate x T)), convert it at spot, and invest the dollars at the domestic rate; dollars at the due date = that amount x (1 + domestic rate x T). Unhedged: dollars = foreign amount x the spot rate at the due date"},{"slug":"information-cascade-posterior","name":"Herding: Information Cascade Posterior","level":"Intermediate","subject":"Behavioral Finance","section":"Behavioral","topic":"Herding","group":"Modern finance and practice","aliases":["herding","information cascade","follow the crowd","Bayesian updating from others"],"finds":"How strongly the crowd should sway you","needs":"Signal accuracy, buys and sells observed","text":"If each earlier trader acted on a private signal that is right with probability q, the probability the asset is good after observing d more buys than sells = q^d / (q^d + (1 - q)^d). When d reaches 2, your own opposing signal cannot change the decision, so it is rational to follow the crowd, and the crowd stops adding information"},{"slug":"herfindahl-index","name":"Herfindahl-Hirschman Index (Industry Concentration)","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Industry and sector analysis","group":"Markets and instruments","aliases":["HHI","market concentration","industry analysis","concentration ratio"],"finds":"How concentrated an industry is","needs":"Market shares of the firms","text":"HHI = sum of the squared market shares (in percent); CR4 = sum of the four largest shares"},{"slug":"heston-variance","name":"Heston Model: Average Variance and Feller Condition","level":"Beginner","subject":"Quantitative Finance","section":"Quant","topic":"Stochastic volatility models (Heston)","group":"Risk and quantitative methods","aliases":["stochastic volatility","Heston","variance mean reversion","vol of vol"],"finds":"The volatility level Heston expects over a horizon","needs":"Current and long-run variance, speed, vol of vol","text":"Expected average variance over T = theta + (v0 - theta) x (1 - e^(-kappa T)) / (kappa T); variance stays above zero if 2 x kappa x theta >= xi^2"},{"slug":"holding-period-return","name":"Holding Period Return","level":"Beginner","subject":"Finance Foundations","section":"What Finance Is","topic":"Risk and return: the core trade-off","group":"Foundations","aliases":["HPR","total return","return on an investment","investment return"],"finds":"Total return over a holding period","needs":"Start price, end price, income","text":"HPR = (End price - Start price + Income) / Start price"},{"slug":"home-bias-measure","name":"Home Bias Measure and Diversification Cost","level":"Intermediate","subject":"Behavioral Finance","section":"Behavioral","topic":"Home bias","group":"Modern finance and practice","aliases":["home bias","domestic overweight","global market cap weight","foregone diversification"],"finds":"How strongly a portfolio leans toward home and what that does to risk","needs":"Weights, volatilities, correlation","text":"Home bias = (domestic weight held - domestic share of world market value) / (1 - domestic share of world market value); Portfolio risk is the two-asset formula, evaluated at the actual weight and at the market-value weight"},{"slug":"household-cash-flow-ratios","name":"Household Financial Health Ratios","level":"Beginner","subject":"Personal Financial Planning","section":"Household finance","topic":"Household finance","group":"Personal finance","aliases":["household finance","savings rate","debt service ratio","liquidity ratio","solvency ratio"],"finds":"A quick scorecard of a household\'s finances","needs":"Income, saving, debt payments, essentials, assets, liabilities","text":"Savings rate = monthly saving / monthly income; Debt service ratio = monthly debt payments / monthly income; Liquidity ratio = liquid assets / monthly essential spending (months of cover); Solvency ratio = (assets - liabilities) / assets"},{"slug":"bond-immunization-weights","name":"Immunization: Matching Duration to a Liability","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Immunization and bond portfolio strategies","group":"Markets and instruments","aliases":["liability matching","duration matching","bullet and barbell","bond portfolio strategies"],"finds":"How to split money between two bonds to match a liability","needs":"Liability duration and value, two bond durations","text":"Weight in bond 1 = (Duration of bond 2 - Duration of the liability) / (Duration of bond 2 - Duration of bond 1); weight in bond 2 = 1 - weight in bond 1"},{"slug":"social-return-on-investment","name":"Impact Investing: Social Return on Investment","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"Impact investing","group":"Modern finance and practice","aliases":["impact investing","SROI","impact multiple of money","social value","blended return"],"finds":"The social value created for each unit invested","needs":"Investment, valued benefits by year, cash returns, discount rate","text":"Social return on investment = present value of social benefits (valued in money, after removing what would have happened anyway) / amount invested; Financial multiple = present value of cash returned / amount invested; Blended multiple = (PV of cash returns + PV of social benefits) / amount invested; Net social value = PV of benefits - investment"},{"slug":"impermanent-loss","name":"Impermanent Loss for Liquidity Providers","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Decentralized finance (DeFi)","group":"Modern finance and practice","aliases":["LP loss","DeFi liquidity providing","holding vs providing liquidity","price divergence loss"],"finds":"Whether fees pay for the loss from price moves","needs":"Price ratio and fees earned","text":"If the price of token A relative to token B changes by a factor r, a liquidity provider\'s pool share is worth 2 x sqrt(r) / (1 + r) of what the same tokens would be worth if simply held, so Impermanent loss = 2 x sqrt(r) / (1 + r) - 1 (zero when r = 1, and the same for r and 1/r); Fees earned must exceed this loss for the pool to beat holding"},{"slug":"implementation-shortfall","name":"Implementation Shortfall and Market Impact","level":"Intermediate","subject":"Advanced Investment Practice","section":"Trading and market structure","topic":"Trading and market structure","group":"Modern finance and practice","aliases":["trading and market structure","transaction cost analysis","TCA","square-root impact","arrival price","delay cost"],"finds":"What a trade cost versus the price at the decision","needs":"Prices, shares, fees, volume, volatility","text":"For a buy: Delay cost = (price when trading started - price at the decision) x shares; Trading cost = (average fill price - price at the start of trading) x shares; Total shortfall = delay cost + trading cost + fees; In basis points = total / (arrival price x shares) x 10,000; Typical impact model: impact as a fraction of price = k x daily volatility x square root of (shares traded / daily volume), with k about 0.5 to 1"},{"slug":"implied-erp","name":"Implied Equity Risk Premium","level":"Intermediate","subject":"Corporate Finance","section":"Cost of Capital","topic":"Equity risk premium","group":"Companies and valuation","aliases":["implied ERP","market risk premium estimate","forward looking risk premium"],"finds":"Equity risk premium from market prices","needs":"Dividend yield, growth, risk-free rate","text":"Implied ERP = Market dividend yield + Expected growth - Risk-free rate"},{"slug":"implied-growth","name":"Implied Growth Rate from the Share Price (Reverse DCF)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Reverse DCF: what the share price implies","group":"Companies and valuation","aliases":["reverse DCF","what the price implies","market implied growth","implied g"],"finds":"The growth rate hidden in a price","needs":"Price, dividend, required return","text":"Implied g = (Price x r - D0) / (Price + D0)"},{"slug":"implied-volatility","name":"Implied Volatility","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Implied volatility and the volatility smile","group":"Markets and instruments","aliases":["volatility smile","implied vol","market implied volatility","vol surface"],"finds":"The volatility an option\'s price implies","needs":"Option price, stock, strike, rate, dividend yield, time","text":"Implied volatility is the volatility that makes the Black-Scholes price equal to the price seen in the market. It has no formula and is found by trial and error."},{"slug":"income-driven-payment","name":"Income-Driven Student Loan Payment","level":"Intermediate","subject":"Personal Finance","section":"Personal Finance","topic":"Student loans","group":"Personal finance","aliases":["income based repayment","IDR","discretionary income","student loans"],"finds":"A payment that follows your income","needs":"Income, poverty line, plan percentages, loan details","text":"Monthly payment = percentage x max(income - multiple x poverty line, 0) / 12, where the percentage, the multiple and the poverty line are set by the plan"},{"slug":"tracking-difference","name":"Index Fund Tracking Difference and Error","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Index funds and passive investing for individuals","group":"Personal finance","aliases":["index funds","passive investing","tracking error of an index fund","expense ratio drag"],"finds":"How closely and how cheaply a fund follows its index","needs":"Yearly returns of the fund and its index","text":"Tracking difference each year = fund return - index return; Average tracking difference = mean of those differences; Tracking error = standard deviation of the differences; Cumulative gap = growth of the fund / growth of the index - 1"},{"slug":"tips-inflation-adjustment","name":"Inflation-Linked Bond (TIPS) Cash Flows and Breakeven Inflation","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Inflation-linked bonds","group":"Markets and instruments","aliases":["TIPS","index linked gilt","real return bond","inflation protected","breakeven inflation"],"finds":"Cash flows of an inflation-linked bond and priced-in inflation","needs":"Face value, real coupon, CPI levels, yields","text":"Adjusted principal = Face x CPI now / CPI at issue; Coupon = Adjusted principal x real coupon rate / payments per year; Breakeven inflation = (1 + nominal yield) / (1 + real yield) - 1"},{"slug":"information-ratio","name":"Information Ratio and Tracking Error","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Information ratio and tracking error","group":"Markets and instruments","aliases":["IR","tracking error","active return per unit of active risk"],"finds":"Reward for active risk against a benchmark","needs":"Portfolio and benchmark returns, periods per year","text":"Tracking error = standard deviation of (Portfolio return - Benchmark return); IR = average active return / tracking error"},{"slug":"infrastructure-dscr-llcr","name":"Infrastructure Project: DSCR and Loan Life Cover","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Infrastructure investing","group":"Modern finance and practice","aliases":["infrastructure investing","project finance cover ratios","LLCR","DSCR lock-up","CFADS"],"finds":"Whether project cash flows cover the debt","needs":"CFADS and debt service by year, loan rate","text":"Cash flow available for debt service (CFADS) = operating cash flow after tax and capex; DSCR in year t = CFADS / (interest + principal due); LLCR = present value of CFADS over the loan life at the loan rate / debt outstanding; A project typically needs a minimum DSCR near 1.2 to 1.4 for stable assets, and pays no dividends below a lock-up level"},{"slug":"insider-trading-disgorgement","name":"Insider Trading: Profit Gained and Maximum Civil Penalty","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Insider trading","group":"Modern finance and practice","aliases":["insider trading","loss avoided","disgorgement","three times profit"],"finds":"The profit and maximum civil penalty in an insider case","needs":"Shares, price paid, price after the news","text":"Profit gained (buyer) = shares x (price after the news is public - price paid); Loss avoided (seller) = shares x (price paid originally - price after bad news); Disgorgement = profit gained or loss avoided; The US civil penalty can be up to three times that amount, in addition to disgorgement, and criminal penalties may apply"},{"slug":"insurance-float-profit","name":"Insurance Underwriting Profit and Float","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Insurance companies: underwriting and float","group":"Money, banks and the economy","aliases":["insurance companies","cost of float","combined ratio and investment income","Berkshire float"],"finds":"Whether an insurer\'s float is cheap","needs":"Premiums, claims, expenses, float, yield","text":"Underwriting profit = premiums - claims - expenses; Cost of float = underwriting loss / float (negative if underwriting is profitable); Pretax profit = underwriting profit + investment yield x float"},{"slug":"insurtech-automation-savings","name":"Insurtech: Underwriting Result after Automation","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Insurtech","group":"Modern finance and practice","aliases":["insurtech","claims automation","loss ratio","expense ratio","straight-through processing"],"finds":"How much technology changes an insurer\'s underwriting profit","needs":"Premiums, claims, expenses, expected improvement","text":"Combined ratio = loss ratio + expense ratio; Underwriting profit = premiums x (1 - combined ratio); New loss ratio = old x (1 - claims improvement from better pricing and fraud detection); New expense ratio = old x (1 - expense saving from automation)"},{"slug":"loan-interest-split","name":"Interest and Principal in a Loan Payment","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Loan amortization schedules","group":"Foundations","aliases":["amortization schedule row","how much of my payment is interest","principal portion"],"finds":"Interest versus principal in one payment","needs":"Balance, rate, payment","text":"Interest = starting balance x r, and Principal repaid = PMT - Interest"},{"slug":"interest-coverage","name":"Interest Coverage Ratio","level":"Beginner","subject":"Corporate Finance","section":"Capital Structure","topic":"Credit ratings and their impact","group":"Companies and valuation","aliases":["times interest earned","TIE","credit rating ratio","debt service cover"],"finds":"Ability to pay interest from operating profit","needs":"EBIT, interest expense","text":"Interest coverage = EBIT / Interest expense"},{"slug":"circular-interest-sweep","name":"Interest on Average Debt with a Cash Sweep (Circularity Solved)","level":"Intermediate","subject":"Accounting Mastery & Financial Modeling","section":"Modeling craft","topic":"Modeling craft","group":"Companies and valuation","aliases":["circular reference","average balance interest","cash sweep","debt schedule"],"finds":"Closing debt and interest with no circular reference","needs":"Opening debt, rate, tax rate, cash available","text":"Closing debt B1 = [Opening debt x (1 + (1 - t) x r / 2) - Cash available F] / [1 - (1 - t) x r / 2]; Interest = Rate x (Opening + Closing) / 2"},{"slug":"interest-rate-build-up","name":"Interest Rate Build-Up","level":"Beginner","subject":"Economics for Finance","section":"Money, Rates and Policy","topic":"How interest rates are set and why they move","group":"Money, banks and the economy","aliases":["how interest rates are set","real rate plus inflation","term premium","risk premium components"],"finds":"What makes up a quoted interest rate","needs":"The component premiums","text":"Nominal rate = real risk-free rate + expected inflation + maturity premium + default premium + liquidity premium; Exact link between real and nominal: (1 + nominal) = (1 + real) x (1 + expected inflation)"},{"slug":"cap-floor-payoffs","name":"Interest Rate Cap and Floor Payoffs","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Swaptions, caps and floors","group":"Markets and instruments","aliases":["caplet","floorlet","interest rate cap","interest rate floor","collar on rates"],"finds":"Payments from an interest rate cap and floor","needs":"Notional, strike, accrual fraction, floating rates","text":"Caplet payment = Notional x Accrual fraction x max(Floating rate - Cap rate, 0); Floorlet payment = Notional x Accrual fraction x max(Floor rate - Floating rate, 0); a cap or floor is the sum of its caplets or floorlets"},{"slug":"swap-fixed-rate","name":"Interest Rate Swap: Fair Fixed Rate","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Interest rate swaps","group":"Markets and instruments","aliases":["swap rate","par swap rate","plain vanilla swap","pay fixed receive floating"],"finds":"The fixed rate that makes a swap worth zero","needs":"Discount factors, notional, floating rate","text":"Fair fixed rate = (1 - Discount factor for the last payment date) / Sum of all the discount factors"},{"slug":"swap-value","name":"Interest Rate Swap: Value After Inception","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Interest rate swaps","group":"Markets and instruments","aliases":["mark to market swap","swap valuation","fixed leg and floating leg"],"finds":"What a swap is worth part way through","needs":"Fixed rate, notional, current discount factors","text":"Value to the fixed payer (just after a floating reset) = Notional x (1 - Final discount factor - Fixed rate x Sum of discount factors)"},{"slug":"day-count-interest","name":"Interest with a Day-Count Convention","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Interest rate and day-count conventions","group":"Foundations","aliases":["actual/360","actual/365","day count","interest for a number of days"],"finds":"Interest for a number of days","needs":"Principal, rate, days, basis","text":"I = P x r x days / basis"},{"slug":"irr","name":"Internal Rate of Return (IRR)","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Internal rate of return (IRR)","group":"Foundations","aliases":["IRR","internal rate of return formula","project return"],"finds":"A project\'s return as a percentage","needs":"List of cash flows","text":"0 = sum of CF_t / (1 + IRR)^t, for t = 0 to n"},{"slug":"international-fisher","name":"International Fisher Effect","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"International Fisher effect","group":"Money, banks and the economy","aliases":["Fisher effect across countries","real interest rate parity","interest differential and inflation differential"],"finds":"The currency move implied by interest and inflation gaps","needs":"Nominal rates and domestic expected inflation","text":"Fisher: nominal rate = (1 + real rate)(1 + expected inflation) - 1. International Fisher: the expected change in the exchange rate (domestic per foreign) = (1 + domestic nominal rate) / (1 + foreign nominal rate) - 1. If real rates are equal, the interest differential equals the expected inflation differential"},{"slug":"change-in-nwc","name":"Investment in Net Working Capital (Projects)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Working capital in project analysis","group":"Companies and valuation","aliases":["working capital in project analysis","change in NWC","NWC as percent of sales"],"finds":"Cash tied up by growth","needs":"NWC share of sales, sales in two years","text":"Change in NWC = w x (Sales this year - Sales last year), where w is NWC as a share of sales"},{"slug":"platform-cost-comparison","name":"Investment Platform Cost Comparison","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Choosing a broker or investment platform","group":"Personal finance","aliases":["choosing a broker","broker fees","platform fee","flat fee vs percentage fee"],"finds":"Which platform costs less over a holding period","needs":"Balance, trading frequency, each platform\'s fees","text":"Total cost over n years = trades per year x fee per trade x years + percentage fee x starting balance x ((1 + growth)^n - 1) / growth (percentage fee charged on the balance at the start of each year); Break-even balance = trades x (fee A - fee B) / (percentage B - percentage A)"},{"slug":"thesis-expected-return-margin","name":"Investment Thesis: Expected Return and Margin of Safety","level":"Intermediate","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Form and defend your own investment thesis","group":"Modern finance and practice","aliases":["form and defend your own investment thesis","margin of safety","kill criteria","thesis scenario"],"finds":"Whether a thesis has enough edge to act on","needs":"Purchase price, target price, failure price, confidence, years","text":"Margin of safety = (estimated value - price) / estimated value; Expected total return = probability the thesis works x its return + probability it fails x its return (a loss); Annualized = (1 + expected return)^(1 / years) - 1; Break-even probability = loss / (gain + loss), the chance the thesis must have to just cover itself"},{"slug":"investor-sentiment-composite","name":"Investor Sentiment Composite Index","level":"Beginner","subject":"Behavioral Finance","section":"Behavioral","topic":"Investor sentiment","group":"Modern finance and practice","aliases":["investor sentiment","fear and greed","z-score composite","contrarian signal"],"finds":"One number that summarizes market mood","needs":"Indicator values with their history and signs","text":"Each indicator\'s z-score = sign x (current value - its average) / its standard deviation, where the sign is -1 for indicators that rise when fear rises; Composite sentiment = average of the z-scores. Above +1 reads as greed and below -1 as fear"},{"slug":"ipo-underpricing","name":"IPO Underpricing (Initial Return)","level":"Beginner","subject":"Corporate Finance","section":"Raising Capital","topic":"IPO underpricing","group":"Companies and valuation","aliases":["IPO first day return","money left on the table","initial return"],"finds":"First-day gain to IPO buyers","needs":"Offer price, closing price, shares sold","text":"Underpricing = (First-day closing price - Offer price) / Offer price"},{"slug":"underwriting-economics","name":"IPO Underwriting Spread and Greenshoe","level":"Beginner","subject":"Banking & Financial Institutions","section":"Banking","topic":"Investment banking: advisory, underwriting, trading","group":"Money, banks and the economy","aliases":["investment banking","underwriting fees","gross spread","overallotment option","money left on the table"],"finds":"What an offering raises and costs","needs":"Shares, price, spread, costs, greenshoe, first-day price","text":"Gross spread = spread % x offer price x shares; Net proceeds to the issuer = price x shares x (1 - spread %) - other costs; Greenshoe adds up to 15% more shares if demand is strong; Money left on the table = (first-day close - offer price) x shares sold"},{"slug":"iqr-outlier-fences","name":"IQR Outlier Fences","level":"Beginner","subject":"Data, Statistics & Computational Skills","section":"Data and coding workflow","topic":"Data and coding workflow","group":"Risk and quantitative methods","aliases":["data and coding workflow","data cleaning","Tukey fences","detect outliers","interquartile range"],"finds":"Values that sit far outside the bulk of the data","needs":"A list of values","text":"IQR = third quartile - first quartile; Lower fence = Q1 - k x IQR; Upper fence = Q3 + k x IQR; values outside the fences are flagged (k = 1.5 is the usual choice)"},{"slug":"ito-lemma-drift","name":"It\xf4\'s Lemma: Drift and Volatility of a Function","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"It\xf4\'s lemma","group":"Risk and quantitative methods","aliases":["Ito formula","stochastic calculus","drift correction","change of variable"],"finds":"The drift and volatility of a function of a random price","needs":"Price, return, volatility and derivatives of the function","text":"If dS = mu x S dt + sigma x S dW then a function f(S, t) has drift f_t + mu x S x f_S + 0.5 x sigma^2 x S^2 x f_SS and volatility sigma x S x f_S"},{"slug":"j-curve-cumulative-cash","name":"J-Curve: Cumulative Net Cash Flow of a Fund","level":"Beginner","subject":"Alternative Investments","section":"Alternatives","topic":"J-curve and fund structures (GP/LP, carried interest)","group":"Modern finance and practice","aliases":["J-curve","capital calls and distributions","fund trough","breakeven year"],"finds":"Depth and length of the J-curve","needs":"Capital called and distributions by year","text":"Net cash flow in year t = distributions - capital called; Cumulative net cash = running total; The trough (lowest point) is the most capital an investor has out at once; Breakeven year = first year the running total is zero or more"},{"slug":"jensens-alpha","name":"Jensen\'s Alpha","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Jensen\'s alpha","group":"Markets and instruments","aliases":["alpha","manager skill","risk adjusted excess return","CAPM alpha"],"finds":"Value added beyond market risk","needs":"Portfolio return, risk-free rate, beta, market return","text":"Alpha = Portfolio return - (rf + beta x (Market return - rf))"},{"slug":"justified-price-to-book","name":"Justified Price-to-Book Ratio (Banks)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Valuing banks and insurers","group":"Companies and valuation","aliases":["P/B","price to book","bank valuation","justified P/B"],"finds":"Price-to-book a bank deserves","needs":"ROE, growth, required return, book value","text":"Justified P/B = (ROE - g) / (r - g)"},{"slug":"kelly-criterion","name":"Kelly Criterion","level":"Intermediate","subject":"Decision-Making, Risk & Model Limitations","section":"Decision quality","topic":"Decision quality","group":"Risk and quantitative methods","aliases":["bet sizing","optimal fraction","position sizing","growth optimal","half Kelly"],"finds":"How much of your capital to put on a bet with an edge","needs":"Win probability and payoff","text":"Best fraction of capital to stake = p - (1 - p) / b, where p is the chance of winning and b is the net payoff per 1 staked; Growth rate = p x ln(1 + b x f) + (1 - p) x ln(1 - f)"},{"slug":"autocorrelation","name":"Lag-1 Autocorrelation","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Time series basics","group":"Foundations","aliases":["serial correlation","time series correlation","persistence","momentum check"],"finds":"Whether a series carries on or reverses","needs":"List of values in time order","text":"Lag-1 autocorrelation = sum of (xt - mean)(x(t-1) - mean) / sum of (xt - mean)^2"},{"slug":"lbo-debt-paydown-schedule","name":"LBO Capstone: Debt Paydown with a Cash Sweep","level":"Intermediate","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Build an LBO model","group":"Modern finance and practice","aliases":["build an LBO model","cash sweep","leverage ratio over time","debt schedule"],"finds":"How fast a buyout pays down its debt","needs":"Debt, rate, sweep, tax rate, EBITDA and capital spending","text":"Interest = opening debt x rate; Cash available for repayment = EBITDA - capital spending - interest - tax, where tax = tax rate x (EBITDA - capital spending - interest) (depreciation is ignored to keep it simple); Repayment = sweep share x cash available, but no more than the debt; Closing debt = opening debt - repayment; Leverage = closing debt / EBITDA"},{"slug":"lbo-returns","name":"LBO Returns (MOIC and IRR)","level":"Intermediate","subject":"Corporate Finance","section":"Mergers & Restructuring","topic":"Leveraged buyouts (LBOs)","group":"Companies and valuation","aliases":["leveraged buyout returns","multiple of invested capital","private equity returns","sponsor IRR"],"finds":"Sponsor return from a leveraged buyout","needs":"Entry and exit EV, debt, holding period","text":"MOIC = Exit equity / Entry equity; IRR = MOIC^(1/years) - 1, when there are no interim cash flows"},{"slug":"lbo-sources-and-uses","name":"LBO Sources and Uses (Equity Check)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"LBO model","group":"Companies and valuation","aliases":["sources and uses","LBO financing","debt capacity","equity contribution"],"finds":"How an LBO is funded","needs":"Purchase EV, fees, EBITDA, leverage multiple","text":"Uses = Purchase EV + Fees; Debt = EBITDA x Leverage multiple; Equity check = Uses - Debt"},{"slug":"lease-liability-pv","name":"Lease Liability and First-Year Expense (IFRS 16 / ASC 842)","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Leases accounting (IFRS 16 / ASC 842)","group":"Companies and valuation","aliases":["right of use asset","operating lease","finance lease","lease accounting"],"finds":"The lease liability and first-year expense","needs":"Payment, discount rate, term","text":"Lease liability = Present value of the lease payments at the discount rate; Year-1 interest = Rate x Liability; Depreciation = Right-of-use asset / Lease term; IFRS 16 expense = Interest + Depreciation"},{"slug":"lc-discounting-cost","name":"Letter of Credit and Discounting: All-In Cost","level":"Beginner","subject":"International Finance","section":"Global Finance","topic":"Trade finance: letters of credit","group":"Money, banks and the economy","aliases":["trade finance","letter of credit fees","banker\'s acceptance","receivables discounting"],"finds":"What early payment under a letter of credit really costs","needs":"Face value, days, discount rate, fees","text":"Discount = face value x discount rate x days / 360; Total cost = discount + issuance fee (% of face) + confirmation fee (% a year x days / 360 x face); Net proceeds = face - total cost; All-in annualized cost = total cost / net proceeds x 365 / days"},{"slug":"life-insurance-need","name":"Life Insurance Needs Analysis","level":"Intermediate","subject":"Personal Finance","section":"Personal Finance","topic":"Insurance: life, health, property, disability","group":"Personal finance","aliases":["insurance","income replacement","DIME method","human life value"],"finds":"How much life cover a family needs","needs":"Income, years of support, debts, goals, existing assets","text":"Cover needed = present value of the income to replace (first-year amount, growing at g, discounted at r for n years) + debts to clear + future goals (such as education) - existing assets and cover"},{"slug":"arbitrage-holding-cost","name":"Limits to Arbitrage: Holding Cost and Adverse Move","level":"Intermediate","subject":"Behavioral Finance","section":"Behavioral","topic":"Limits to arbitrage","group":"Modern finance and practice","aliases":["limits to arbitrage","mispricing persistence","short selling cost","noise trader risk"],"finds":"Whether a mispricing is worth trading and how it could hurt","needs":"Price, value, borrow fee, margin, time, adverse move","text":"Net profit per share from shorting an overpriced stock = gap to fundamental value - borrow fee x price x years - financing rate x margin share x price x years; Break-even holding time = gap / (price x (borrow fee + financing rate x margin share)); Loss if the price moves further away by a = a x price"},{"slug":"supply-demand-equilibrium","name":"Linear Supply and Demand Equilibrium","level":"Beginner","subject":"Economics for Finance","section":"How the Economy Works","topic":"Supply, demand and prices","group":"Money, banks and the economy","aliases":["supply, demand and prices","market clearing price","price ceiling shortage","demand shift"],"finds":"The market price, and the effect of a shift or a ceiling","needs":"Demand and supply intercepts and slopes","text":"Demand: Qd = a - b x P. Supply: Qs = c + d x P. Equilibrium price P* = (a - c) / (b + d); equilibrium quantity Q* = a - b x P*"},{"slug":"cash-flow-statement-link","name":"Linking the Three Statements: Cash Flow and Balance Check","level":"Intermediate","subject":"Accounting Mastery & Financial Modeling","section":"Financial statement mechanics","topic":"Financial statement mechanics","group":"Companies and valuation","aliases":["indirect method","cash flow statement","balance sheet check","three statement model"],"finds":"Ending cash and a check that the balance sheet balances","needs":"Net income, depreciation, working capital, capex, financing flows, opening cash","text":"Cash flow from operations = Net income + Depreciation - Increase in working capital; Cash flow from investing = -Capex; Cash flow from financing = Debt issued - Debt repaid - Dividends + Shares issued; Ending cash = Opening cash + total cash flow"},{"slug":"liquidity-adjusted-var","name":"Liquidity-Adjusted VaR","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Liquidity risk and funding risk","group":"Risk and quantitative methods","aliases":["LVaR","exogenous liquidity cost","bid ask cost in VaR","funding gap"],"finds":"Market risk plus the cost of exiting","needs":"Position value, volatility, days, confidence, spreads","text":"Liquidity-adjusted VaR = VaR + 0.5 x Position value x Relative bid-ask spread"},{"slug":"loan-payment","name":"Loan Payment (Amortization)","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Loan amortization schedules","group":"Foundations","aliases":["mortgage payment","monthly payment formula","amortization formula","PMT"],"finds":"The regular payment on a loan","needs":"Loan amount, annual rate, years, payments per year","text":"PMT = P x r / (1 - (1 + r)^-n)"},{"slug":"long-short-factor-return","name":"Long-Short Factor Return","level":"Beginner","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Factor investing / smart beta","group":"Markets and instruments","aliases":["factor premium","smart beta","factor investing","winners minus losers"],"finds":"What a factor earned","needs":"Returns of the long and short portfolios","text":"Factor return = Return of the long portfolio - Return of the short portfolio"},{"slug":"long-short-fund-net-return","name":"Long/Short Hedge Fund: Exposure, Gross and Net Return","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Hedge fund strategies (long/short, macro, event-driven, arbitrage)","group":"Modern finance and practice","aliases":["hedge fund strategies","gross and net exposure","2 and 20","long short equity return","hedge fund fees"],"finds":"Market exposure and the return left after fees","needs":"Long and short exposure and returns, rebate, fee terms","text":"Gross exposure = long weight + short weight; Net exposure = long weight - short weight; Gross return = long weight x long return - short weight x short stock return + short weight x interest on short proceeds; Fund return after management fee = gross - fee; Incentive fee = share x amount above the hurdle; Net return = after management fee - incentive fee"},{"slug":"duration","name":"Macaulay and Modified Duration","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Duration: Macaulay and modified","group":"Markets and instruments","aliases":["bond duration","interest rate sensitivity","weighted average time to cash flows"],"finds":"How sensitive a bond is to interest rates","needs":"Bond terms and yield","text":"Macaulay duration = sum of (time x present value of each cash flow) / Price; Modified duration = Macaulay duration / (1 + yield / payments per year)"},{"slug":"margin-analysis","name":"Margin Analysis with Year-on-Year Change","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Profitability ratios: gross, operating, net margin","group":"Companies and valuation","aliases":["gross margin","operating margin","net margin","EBITDA margin","profitability ratios"],"finds":"Profit as a share of sales at each level, and its trend","needs":"Revenue, COGS, operating profit, net income for two years","text":"Gross margin = (Revenue - COGS) / Revenue; Operating margin = Operating profit / Revenue; Net margin = Net income / Revenue; the change is shown in basis points"},{"slug":"margin-call-price","name":"Margin Call Price","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Margin trading","group":"Markets and instruments","aliases":["maintenance margin","margin call","liquidation price"],"finds":"The price that triggers a margin call","needs":"Purchase price, initial margin, maintenance margin","text":"Margin call price = Start price x (1 - Initial margin) / (1 - Maintenance margin)"},{"slug":"market-manipulation-ratios","name":"Market Manipulation Screens: Order-to-Trade and Cancel Ratios","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Market manipulation","group":"Modern finance and practice","aliases":["spoofing","layering","wash trading","order-to-trade ratio","cancellation rate"],"finds":"Whether trading patterns look like manipulation","needs":"Orders, trades, cancellations, self-trade share, limits","text":"Order-to-trade ratio = orders entered / trades executed; Cancellation rate = orders canceled / orders entered; Self-trade share = volume where the same beneficial owner is on both sides / total volume; Very high ratios and quick cancellations are warning signs of spoofing or layering, and a high self-trade share of wash trading"},{"slug":"market-ratios-pb-ps-ev","name":"Market Ratios: P/B, P/S and EV/EBITDA","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Market ratios: EPS, P/E, P/B, dividend yield","group":"Companies and valuation","aliases":["price to book","price to sales","EV to EBITDA","market capitalization","enterprise value"],"finds":"How the market prices earnings, book value, sales and the whole business","needs":"Price, shares, equity, sales, EBITDA, net debt, net income","text":"P/B = Price / Book value per share; P/S = Market cap / Sales; EV/EBITDA = (Market cap + Net debt) / EBITDA; P/E = Price / EPS"},{"slug":"market-value-added","name":"Market Value Added (MVA)","level":"Beginner","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Goal of the firm: shareholder value maximization","group":"Companies and valuation","aliases":["MVA","shareholder value created","goal of the firm"],"finds":"Value created for investors","needs":"Market values and capital invested","text":"MVA = (Market value of equity + Market value of debt) - Capital invested"},{"slug":"cap-weighted-index","name":"Market-Cap-Weighted Index","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Stock indices: construction and weighting","group":"Markets and instruments","aliases":["S&P 500 method","value weighted index","free float index","index weights"],"finds":"An index level and the weight of each company","needs":"Start and current prices, shares, starting level","text":"Index level = Starting level x (Total market value now / Total market value at the start)"},{"slug":"martingale-check","name":"Martingale Check for Discounted Prices","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Martingales","group":"Risk and quantitative methods","aliases":["martingale","fair game","discounted price process","no arbitrage test"],"finds":"Whether discounted prices are fair games","needs":"Prices in each state, rate, real-world probability","text":"Under risk-neutral probabilities the expected discounted future price equals today\'s price: e^(-rT) x [q x Su + (1 - q) x Sd] = S0"},{"slug":"maximum-drawdown","name":"Maximum Drawdown","level":"Beginner","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Maximum drawdown","group":"Markets and instruments","aliases":["max drawdown","peak to trough","worst loss","drawdown"],"finds":"The worst peak-to-trough loss","needs":"A series of values","text":"Maximum drawdown = the largest fall from a previous peak, as a percentage of that peak"},{"slug":"mbs-pass-through-month","name":"MBS Pass-Through Cash Flow for One Month","level":"Intermediate","subject":"Fixed Income","section":"Securitized Products","topic":"Mortgage-backed securities (MBS)","group":"Markets and instruments","aliases":["mortgage backed securities","pass through rate","servicing fee","scheduled principal","prepayment"],"finds":"A mortgage pool\'s monthly cash flow to investors","needs":"Balance, WAC, pass-through rate, months, prepayment speed","text":"Investor cash flow = Balance x Pass-through rate / 12 + Scheduled principal + SMM x (Balance - Scheduled principal)"},{"slug":"ou-process-moments","name":"Mean-Reverting (Ornstein-Uhlenbeck) Process Moments","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Stochastic processes basics","group":"Risk and quantitative methods","aliases":["stochastic processes","mean reversion","OU process","Vasicek dynamics"],"finds":"Where a mean-reverting variable is expected to be, and how fast","needs":"Start, long-run mean, speed, volatility, time","text":"Expected value at time t = Long-run mean + (Start - Long-run mean) x e^(-speed x t); Variance = sigma^2 / (2 x speed) x (1 - e^(-2 x speed x t))"},{"slug":"mental-accounting-cost","name":"Mental Accounting: Cost of Separate Pots","level":"Beginner","subject":"Behavioral Finance","section":"Behavioral","topic":"Mental accounting","group":"Modern finance and practice","aliases":["mental accounting","saving while in debt","money is not fungible","opportunity cost of low-interest savings"],"finds":"What keeping savings and debt apart costs per year","needs":"Savings, debt, rates, buffer","text":"Amount you could pay off = smaller of the debt and (savings - emergency buffer you decide to keep); Interest saved = amount x debt rate; Interest given up = amount x savings rate; Net gain per year = amount x (debt rate - savings rate)"},{"slug":"merchant-payment-cost","name":"Merchant Cost of a Digital Payment","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Digital payments and mobile wallets","group":"Modern finance and practice","aliases":["digital payments","mobile wallets","merchant discount rate","interchange","effective payment cost"],"finds":"What a payment costs a merchant","needs":"Amount, fee components, fixed fee","text":"Merchant discount rate (MDR) = interchange (paid to the card issuer) + scheme fee (card network) + acquirer margin; Cost of one payment = amount x MDR + fixed fee per transaction; Effective rate = cost / amount; Break-even amount against a flat-fee method = flat fee / (MDR - 0)"},{"slug":"merton-model","name":"Merton Credit Model (Equity as a Call on Assets)","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Credit risk models (Merton, credit scoring)","group":"Risk and quantitative methods","aliases":["structural credit model","distance to default","Merton default probability","KMV"],"finds":"Equity value, default probability and spread from the balance sheet","needs":"Asset value, debt, asset volatility, rate, time","text":"Equity value E = V x N(d1) - D x e^(-rT) x N(d2); Default probability = N(-d2); Credit spread = -(1/T) x ln[(Firm value - Equity) / Debt] - risk-free rate; d1 = [ln(V/D) + (r + sigma^2 / 2) x T] / (sigma x sqrt(T))"},{"slug":"minimum-variance-hedge-ratio","name":"Minimum-Variance Hedge Ratio","level":"Intermediate","subject":"Corporate Finance","section":"Corporate Risk Management","topic":"Corporate hedging policy: FX, interest rates and commodities","group":"Companies and valuation","aliases":["hedge ratio","number of futures contracts","optimal hedge"],"finds":"How much to hedge and with how many contracts","needs":"Correlation, volatilities, exposure, contract size","text":"Hedge ratio h = correlation x (Volatility of the exposure / Volatility of the hedge); Contracts N = h x Exposure / Contract size"},{"slug":"minimum-variance-portfolio","name":"Minimum-Variance Portfolio (Two Assets)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Markowitz mean-variance optimization","group":"Markets and instruments","aliases":["Markowitz","mean variance optimization","efficient frontier","global minimum variance"],"finds":"The lowest-risk mix of two assets","needs":"Two standard deviations, correlation, expected returns","text":"Weight in asset 1 = (s2^2 - rho x s1 x s2) / (s1^2 + s2^2 - 2 x rho x s1 x s2), and asset 2 gets the rest"},{"slug":"model-error-metrics","name":"Model Risk: Pricing Error Metrics","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Model risk","group":"Risk and quantitative methods","aliases":["model validation","MAE RMSE bias","model error","calibration error"],"finds":"How far a model is from market prices","needs":"Model prices and market prices","text":"Bias = average of (Model - Market); MAE = average of |Model - Market|; RMSE = square root of the average of (Model - Market)^2; Largest error = max |Model - Market|"},{"slug":"mirr","name":"Modified Internal Rate of Return (MIRR)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"IRR and its pitfalls (multiple IRRs)","group":"Companies and valuation","aliases":["MIRR","IRR pitfalls","multiple IRRs fix"],"finds":"One reliable return rate for a project","needs":"Finance rate, reinvestment rate, cash flows","text":"MIRR = (FV of inflows at the reinvestment rate / PV of outflows at the finance rate)^(1/n) - 1"},{"slug":"mmf-nav-break-the-buck","name":"Money Market Fund NAV and Breaking the Buck","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Banking","topic":"Shadow banking","group":"Money, banks and the economy","aliases":["shadow banking","stable NAV","run on a money fund","redemptions at par"],"finds":"How redemptions at par shift losses onto remaining holders","needs":"Assets, shares, loss, redemption size","text":"Net asset value per share = value of assets after losses / shares outstanding; If investors redeem a share fraction w at the stable price of 1.00 while the true value is lower, the NAV left for remaining holders = (assets after losses - w x shares x 1.00) / (shares x (1 - w)). The fund breaks the buck if NAV falls below 0.995"},{"slug":"money-multiplier","name":"Money Multiplier and Deposit Expansion","level":"Beginner","subject":"Banking & Financial Institutions","section":"Banking","topic":"Fractional reserve banking","group":"Money, banks and the economy","aliases":["fractional reserve banking","deposit creation","reserve requirement","excess reserves"],"finds":"How far new reserves can multiply into money","needs":"Reserve ratio, currency ratio, excess reserves, injection","text":"Simple deposit multiplier = 1 / reserve ratio; Money multiplier with leakages = (1 + currency ratio) / (currency ratio + reserve ratio + excess reserve ratio); Deposit expansion from new reserves = new reserves / reserve ratio"},{"slug":"money-weighted-return","name":"Money-Weighted Return","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Time-weighted vs. money-weighted returns","group":"Markets and instruments","aliases":["MWR","dollar weighted return","investor return","IRR of cash flows"],"finds":"The return the investor actually experienced","needs":"Cash flows including the ending value","text":"Money-weighted return = the IRR of the investor\'s cash flows, including the ending value"},{"slug":"monte-carlo-standard-error","name":"Monte Carlo Standard Error and Confidence Interval","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Monte Carlo pricing","group":"Risk and quantitative methods","aliases":["Monte Carlo pricing","simulation error","number of paths","confidence interval for price"],"finds":"How accurate a simulated price is and how many paths you need","needs":"A list of simulated discounted payoffs","text":"Price estimate = average of the discounted payoffs; Standard error = sample standard deviation / sqrt(N); Paths needed for a target error = (sample standard deviation / target error)^2"},{"slug":"two-stage-ddm","name":"Multi-Stage Dividend Discount Model (Two Stages)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Multi-stage DDM","group":"Companies and valuation","aliases":["two stage DDM","H model alternative","high growth then stable growth","multi stage dividend"],"finds":"Value of a company with a growth stage then steady growth","needs":"Dividend, two growth rates, years, required return","text":"Price = PV of the high-growth dividends for n years + PV of the terminal value at year n"},{"slug":"multiple-testing-false-positives","name":"Multiple Testing: False Positives and the Bonferroni Correction","level":"Intermediate","subject":"Advanced Investment Practice","section":"Research integrity","topic":"Research integrity","group":"Modern finance and practice","aliases":["research integrity","p-hacking","data mining","backtest overfitting","family-wise error rate"],"finds":"Whether a best-of-many result could be luck","needs":"Number of tests tried, significance level, best p-value","text":"If you test n unrelated ideas at significance level alpha, the chance of at least one false discovery = 1 - (1 - alpha)^n; Expected number of false positives = n x alpha; Bonferroni-adjusted threshold = alpha / n; A result is credible only if its p-value is below the adjusted threshold; Required t-statistic rises from about 2 to 3 or more when many strategies are tried"},{"slug":"muni-tax-equivalent-yield","name":"Municipal Bond Tax-Equivalent Yield (with State Tax)","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Municipal and local government bonds","group":"Markets and instruments","aliases":["tax free yield","muni bond","after tax yield","triple tax free"],"finds":"Whether a tax-exempt bond beats a taxable one","needs":"Yields and tax rates","text":"Combined tax rate = Federal rate + State rate x (1 - Federal rate); Tax-equivalent yield = Muni yield / (1 - Combined tax rate)"},{"slug":"murabaha-implied-rate","name":"Murabaha Mark-Up and Implied Rate","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Banking","topic":"Islamic banking","group":"Money, banks and the economy","aliases":["Islamic banking","cost-plus financing","profit rate","sale on deferred payment"],"finds":"The all-in price and the comparable annual rate of a cost-plus sale","needs":"Asset cost, mark-up, number of installments","text":"Sale price = cost x (1 + mark-up); Installment = sale price / number of installments; Implied periodic rate i solves: cost = installment x (1 - (1 + i)^(-n)) / i; Effective annual rate = (1 + i)^12 - 1 for monthly installments"},{"slug":"narrative-contagion-sir","name":"Narrative Contagion (SIR Model)","level":"Intermediate","subject":"Behavioral Finance","section":"Behavioral","topic":"Narrative economics (Shiller)","group":"Modern finance and practice","aliases":["narrative economics","Shiller epidemic of ideas","R0 of a story","spread of a rumor"],"finds":"Whether a narrative takes off and how far it spreads","needs":"Contagion and fading rates","text":"Basic reproduction number R0 = contagion rate / forgetting (recovery) rate. If R0 > 1 the story spreads. Peak share actively spreading = 1 - (1 + ln R0) / R0; Share who ever hear and believe it, z, solves z = 1 - e^(-R0 x z). A story dies out if R0 is 1 or less"},{"slug":"neobank-unit-economics","name":"Neobank Unit Economics: Margin per Customer and Payback","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Neobanks","group":"Modern finance and practice","aliases":["neobanks","digital bank profitability","ARPU","cost to serve","customer lifetime"],"finds":"Whether a digital bank earns enough per customer","needs":"Income per customer, cost to serve, acquisition cost, churn, fixed costs","text":"Margin per customer per year = fee and interchange income + net interest income - cost to serve; Payback in months = acquisition cost / (monthly margin); Lifetime value = yearly margin / yearly churn; Breakeven customers = fixed cost / margin per customer"},{"slug":"net-advantage-to-leasing","name":"Net Advantage to Leasing (Lease vs. Buy)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Lease vs. buy decisions","group":"Companies and valuation","aliases":["NAL","lease or buy","lease versus buy decision"],"finds":"Whether leasing beats buying","needs":"Asset cost, lease payment, years, tax rate, borrowing rate","text":"NAL = Asset cost - PV of after-tax lease payments - PV of depreciation tax shields given up"},{"slug":"nav-per-share","name":"Net Asset Value per Share","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Mutual funds","group":"Markets and instruments","aliases":["NAV","mutual fund price","fund unit price"],"finds":"The price of a mutual fund share","needs":"Assets, liabilities, shares","text":"NAV per share = (Fund assets - Fund liabilities) / Number of fund shares"},{"slug":"net-book-value","name":"Net Book Value","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Depreciation and amortization","group":"Foundations","aliases":["book value","carrying value","NBV","written down value"],"finds":"The balance sheet value of an asset","needs":"Cost, accumulated depreciation","text":"Net book value = Cost - Accumulated depreciation"},{"slug":"net-change-in-cash","name":"Net Change in Cash","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Cash flow statement","group":"Foundations","aliases":["cash flow statement total","cash flow from operations investing financing","ending cash"],"finds":"How cash moved over the period","needs":"Three cash flow totals, beginning cash","text":"Change in cash = CFO + CFI + CFF, and Ending cash = Beginning cash + Change in cash"},{"slug":"net-income","name":"Net Income","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Income statement","group":"Foundations","aliases":["profit","bottom line","earnings","profit and loss"],"finds":"Profit for a period","needs":"Revenues, expenses","text":"Net income = Revenues - Expenses"},{"slug":"net-interest-margin","name":"Net Interest Margin","level":"Intermediate","subject":"Finance Foundations","section":"What Finance Is","topic":"Savers, borrowers and financial intermediaries","group":"Foundations","aliases":["NIM","bank spread","intermediation margin"],"finds":"Profit from the gap between lending and borrowing rates","needs":"Interest income, interest expense, earning assets","text":"NIM = (Interest income - Interest expense) / Earning assets"},{"slug":"cap-rate-valuation","name":"Net Operating Income and Cap-Rate Valuation","level":"Beginner","subject":"Alternative Investments","section":"Alternatives","topic":"Real estate valuation (cap rates, NOI)","group":"Modern finance and practice","aliases":["NOI","capitalization rate","direct capitalization","property value from income"],"finds":"Property value from its income","needs":"Rent, vacancy, expenses, cap rate, loan terms","text":"Net operating income = potential rent x (1 - vacancy) - operating expenses (before debt service, tax and depreciation); Value = NOI / cap rate; Cap rate = NOI / value; Debt service coverage = NOI / annual loan payment"},{"slug":"npv","name":"Net Present Value (NPV)","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Net present value (NPV)","group":"Foundations","aliases":["NPV","net present value formula","project value","discounted cash flow"],"finds":"Whether a project adds value","needs":"Discount rate, list of cash flows","text":"NPV = sum of CF_t / (1 + r)^t, for t = 0 to n"},{"slug":"net-working-capital","name":"Net Working Capital","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Balance sheet","group":"Foundations","aliases":["working capital","NWC","current assets minus current liabilities"],"finds":"Short-term cushion in money terms","needs":"Current assets, current liabilities","text":"NWC = Current assets - Current liabilities"},{"slug":"net-worth","name":"Net Worth and Balance Sheet Ratios","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Net worth and your personal balance sheet","group":"Personal finance","aliases":["personal balance sheet","assets minus liabilities","solvency ratio","debt to asset ratio"],"finds":"What you own minus what you owe","needs":"Lists of assets and debts","text":"Net worth = total assets - total liabilities; Debt-to-asset ratio = total liabilities / total assets; Solvency ratio = net worth / total assets"},{"slug":"netting-efficiency","name":"Netting Efficiency in Payment Clearing","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Banking","topic":"Payment systems and clearing","group":"Money, banks and the economy","aliases":["payment systems and clearing","multilateral netting","bilateral netting","settlement liquidity"],"finds":"How much cash netting saves","needs":"A matrix of payments among three banks","text":"Each bank\'s net position = payments received - payments sent; Multilateral net settlement = sum of the positive net positions; Bilateral netting = for each pair, the difference between the two payments; Liquidity saving = 1 - settled amount / gross payments"},{"slug":"newton-implied-vol","name":"Newton\'s Method for Implied Volatility","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Optimization methods","group":"Risk and quantitative methods","aliases":["Newton Raphson","root finding","iterative solution","optimization methods"],"finds":"How an iterative solver closes in on an answer","needs":"Option inputs, market price, starting guess","text":"Next guess = Current guess - (Model price at the guess - Market price) / Vega at the guess"},{"slug":"noise-variance-share","name":"Noise Trading: Share of Price Variance Explained by Fundamentals","level":"Intermediate","subject":"Behavioral Finance","section":"Behavioral","topic":"Noise traders","group":"Modern finance and practice","aliases":["noise traders","price vs fundamental value","excess volatility","noise variance"],"finds":"How much price movement is not explained by value","needs":"Prices and fundamental value estimates","text":"Noise = price - fundamental value; Variance of price = variance of fundamental + variance of noise + 2 x covariance; Share of price variation explained by fundamentals (R-squared) = Cov(P, F)^2 / (Var(P) x Var(F))"},{"slug":"non-gaap-reconciliation","name":"Non-GAAP Earnings Reconciliation","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Non-GAAP / adjusted metrics","group":"Companies and valuation","aliases":["adjusted earnings","adjusted EPS","pro forma earnings","add backs"],"finds":"How far adjusted earnings are above reported earnings","needs":"GAAP net income, add-backs, tax rate, shares","text":"Adjusted net income = GAAP net income + sum of the pre-tax add-backs x (1 - tax rate); Adjusted EPS = Adjusted net income / Shares"},{"slug":"futures-hedge-contracts","name":"Number of Futures Contracts to Hedge a Portfolio","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Hedging with futures","group":"Markets and instruments","aliases":["hedge ratio","beta adjusted hedge","stock index futures hedge","change portfolio beta"],"finds":"How many futures to sell or buy","needs":"Portfolio value, beta, futures price, multiplier","text":"Contracts = (Target beta - Current beta) x Portfolio value / (Futures price x Multiplier); a negative number means sell"},{"slug":"loan-term","name":"Number of Payments to Repay a Loan","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Loan amortization schedules","group":"Foundations","aliases":["how long to pay off a loan","time to repay","solve for n loan","nper"],"finds":"How long a loan takes to repay","needs":"Loan amount, annual rate, payments per year, payment","text":"n = -ln(1 - P x r / PMT) / ln(1 + r)"},{"slug":"solve-for-periods","name":"Number of Periods to Reach a Target","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Future value","group":"Foundations","aliases":["how long to reach a goal","solve for n","time to grow","years to reach target"],"finds":"Time needed to reach a target","needs":"Starting amount, target, rate","text":"n = ln(FV / PV) / ln(1 + r)"},{"slug":"okun-law","name":"Okun\'s Law","level":"Beginner","subject":"Economics for Finance","section":"How the Economy Works","topic":"Unemployment and the labor market","group":"Money, banks and the economy","aliases":["unemployment and growth","output loss from unemployment","growth needed to keep unemployment steady"],"finds":"A rough change in unemployment from growth","needs":"Unemployment, growth, trend growth, coefficient","text":"Change in the unemployment rate = - beta x (real GDP growth - trend growth), with beta about 0.5 in the United States"},{"slug":"working-capital-analysis","name":"Operating Working Capital Analysis","level":"Intermediate","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Working capital analysis","group":"Companies and valuation","aliases":["working capital to sales","operating working capital","incremental working capital","NWC intensity"],"finds":"How much working capital growth requires","needs":"Operating current assets and liabilities, sales for two years","text":"Operating working capital = (Receivables + Inventory + Prepaid) - (Payables + Accrued liabilities); Intensity = OWC / Sales; Incremental intensity = Change in OWC / Change in sales"},{"slug":"op-risk-capital-bia","name":"Operational Risk: Basic Indicator Capital and Expected Loss","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Operational risk and cyber risk","group":"Risk and quantitative methods","aliases":["basic indicator approach","operational risk capital","loss frequency severity","op risk"],"finds":"Capital and expected loss for operational risk","needs":"Gross income, loss frequency and severity","text":"Basic Indicator capital = 15% x Average of the positive annual gross income over three years; Expected annual operational loss = Number of loss events per year x Average loss per event"},{"slug":"tangency-portfolio-two-assets","name":"Optimal Risky Portfolio (Maximum Sharpe, Two Assets)","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Optimization methods","group":"Risk and quantitative methods","aliases":["optimization methods","tangency portfolio","maximum Sharpe ratio","mean variance optimization","Lagrange"],"finds":"The risky mix with the best return per unit of risk","needs":"Returns, volatilities, correlation, risk-free rate","text":"Weight in asset 1 = [(m1 - rf) x s2^2 - (m2 - rf) x rho x s1 x s2] / [(m1 - rf) x s2^2 + (m2 - rf) x s1^2 - (m1 - rf + m2 - rf) x rho x s1 x s2]; weight in asset 2 = 1 - weight in asset 1"},{"slug":"option-greeks","name":"Option Greeks: Delta, Gamma, Vega, Theta, Rho","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"The Greeks: delta, gamma, vega, theta, rho","group":"Markets and instruments","aliases":["delta","gamma","vega","theta","rho","option sensitivities"],"finds":"How an option price responds to price, time, volatility and rates","needs":"Stock, strike, rate, dividend yield, volatility, time","text":"Call delta = e^(-qT) x N(d1); Put delta = call delta - e^(-qT); Gamma = e^(-qT) x pdf(d1) / (S x sigma x sqrt(T)); Vega = S x e^(-qT) x pdf(d1) x sqrt(T); Call theta = [-S e^(-qT) pdf(d1) sigma / (2 sqrt(T)) - r K e^(-rT) N(d2) + q S e^(-qT) N(d1)]; Call rho = K T e^(-rT) N(d2)"},{"slug":"option-intrinsic-time-value","name":"Option Intrinsic Value and Time Value","level":"Beginner","subject":"Derivatives","section":"Derivatives","topic":"Options: calls and puts","group":"Markets and instruments","aliases":["moneyness","in the money","out of the money","time premium"],"finds":"How much of an option price is time value","needs":"Stock price, strike, option prices","text":"Intrinsic value of a call = max(Spot - Strike, 0), of a put = max(Strike - Spot, 0); Time value = Option price - Intrinsic value"},{"slug":"option-price-bounds","name":"Option Price Bounds and Early Exercise Check","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"American vs. European options","group":"Markets and instruments","aliases":["American option","European option","early exercise","no arbitrage bounds"],"finds":"Sensible price limits and whether early exercise can pay","needs":"Stock, strike, rate, dividend yield, time","text":"European call lower bound = max(S x e^(-qT) - K x e^(-rT), 0); European put lower bound = max(K x e^(-rT) - S x e^(-qT), 0); American put lower bound = max(K - S, 0)"},{"slug":"oos-r-squared","name":"Out-of-Sample R-Squared","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Machine learning in finance","group":"Risk and quantitative methods","aliases":["machine learning in finance","Campbell Thompson","forecast evaluation","overfitting check","OOS R2"],"finds":"Whether a forecasting model beats a simple benchmark on unseen data","needs":"Realized returns, forecasts, benchmark forecasts","text":"Out-of-sample R-squared = 1 - (sum of squared errors of the model forecasts) / (sum of squared errors of a benchmark forecast, usually the historical average)"},{"slug":"output-gap-annualized","name":"Output Gap and Annualized Growth","level":"Beginner","subject":"Economics for Finance","section":"How the Economy Works","topic":"The business cycle","group":"Money, banks and the economy","aliases":["business cycle","potential output","quarterly growth annualized","overheating"],"finds":"How far output is from potential and the annual pace of growth","needs":"Actual and potential GDP, quarterly growth","text":"Output gap = (actual real GDP - potential real GDP) / potential real GDP; Annualized growth = (1 + quarterly growth)^4 - 1"},{"slug":"owner-earnings","name":"Owner Earnings (Buffett)","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Investment styles of famous investors (Graham, Buffett, Lynch)","group":"Markets and instruments","aliases":["Warren Buffett","free cash to owners","intrinsic value Buffett"],"finds":"Cash earnings available to owners","needs":"Net income, D&A, capex, working capital change","text":"Owner earnings = Net income + Depreciation and amortization - Capital spending needed to maintain the business - Increase in working capital"},{"slug":"dilution-from-new-issue","name":"Ownership Dilution from a New Share Issue","level":"Beginner","subject":"Corporate Finance","section":"Raising Capital","topic":"Seasoned equity offerings","group":"Companies and valuation","aliases":["dilution","ownership after new shares","diluted ownership"],"finds":"Ownership after new shares are sold","needs":"Shares held, shares outstanding, amount raised, issue price","text":"New shares = Amount raised / Issue price; Ownership after = Shares you hold / (Old shares + New shares)"},{"slug":"pe-earnings-yield","name":"P/E Ratio and Earnings Yield","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Fundamental analysis","group":"Markets and instruments","aliases":["price earnings ratio","earnings multiple","fundamental analysis","earnings yield"],"finds":"How much you pay for each unit of earnings","needs":"Price, earnings per share","text":"P/E = Share price / Earnings per share; Earnings yield = Earnings per share / Share price"},{"slug":"pairs-trade-sizing","name":"Pairs Trade Sizing and Reversion Profit","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Statistical arbitrage and pairs trading","group":"Risk and quantitative methods","aliases":["statistical arbitrage","stat arb","pairs trading","spread trade"],"finds":"How big to make a pairs trade and what reversion would earn","needs":"Spread statistics, hedge ratio, prices, capital","text":"z-score = (spread - mean spread) / sd of spread; Units of the pair = floor(capital / (price Y + hedge ratio x price X)); Profit if the spread returns to its mean = Units x |spread - mean|"},{"slug":"payback-period","name":"Payback Period","level":"Beginner","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Payback and discounted payback","group":"Companies and valuation","aliases":["simple payback","years to recover investment"],"finds":"How quickly the investment is recovered","needs":"Initial investment, cash flows","text":"Payback = last full year before recovery + unrecovered cost / cash flow in the recovery year"},{"slug":"payment-rail-crossover","name":"Payment Rails: Percentage Fee vs Flat Fee Crossover","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Payment rails: card networks, UPI and real-time payments","group":"Modern finance and practice","aliases":["card networks","UPI","real-time payments","instant payment cost","flat fee vs percentage fee"],"finds":"Which rail is cheaper at a given payment size","needs":"Percentage and fixed fees of two rails","text":"Cost on a card network = amount x percentage fee + fixed fee; Cost on a real-time (account-to-account) rail = amount x percentage fee + fixed fee (often a small flat fee or zero); Crossover amount a* = (flat fee on rail B - flat fee on rail A) / (percentage on A - percentage on B)"},{"slug":"peer-relative-ratio","name":"Peer Comparison: Median, Z-Score and Premium","level":"Intermediate","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Trend and peer analysis","group":"Companies and valuation","aliases":["peer analysis","relative valuation","benchmarking a ratio","peer median"],"finds":"How far a company is from its peers on a ratio","needs":"Company ratio and peers\' ratios","text":"Z-score = (Company ratio - Peer mean) / Peer standard deviation; Premium to the median = Company ratio / Peer median - 1"},{"slug":"p2p-note-net-return","name":"Peer-to-Peer Lending: Investor Net Return","level":"Beginner","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Peer-to-peer lending","group":"Modern finance and practice","aliases":["P2P lending","marketplace lending","note portfolio","platform fee","default loss"],"finds":"What a P2P lender really earns","needs":"Interest rate, fee, default rate, loss given default, number of notes","text":"Net return = loan interest rate - platform servicing fee - (annual default rate x loss given default); Break-even default rate = (rate - fee) / loss given default; Investor with n equal notes loses 1/n of the money per default"},{"slug":"peg-ratio","name":"PEG Ratio","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Growth vs. value investing","group":"Markets and instruments","aliases":["price earnings to growth","growth at a reasonable price","GARP","growth vs value"],"finds":"Price relative to growth","needs":"P/E and growth for each stock","text":"PEG = P/E ratio / Expected annual earnings growth rate (as a whole number, such as 15 for 15%)"},{"slug":"brinson-attribution","name":"Performance Attribution (Brinson)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Performance attribution","group":"Markets and instruments","aliases":["Brinson Fachler","allocation effect","selection effect","attribution analysis"],"finds":"Sources of a portfolio\'s outperformance","needs":"Portfolio and benchmark weights and sector returns","text":"Allocation = (Portfolio weight - Benchmark weight) x (Benchmark sector return - Total benchmark return); Selection = Benchmark weight x (Portfolio sector return - Benchmark sector return); Interaction = (Portfolio weight - Benchmark weight) x (Portfolio sector return - Benchmark sector return)"},{"slug":"perpetuity","name":"Perpetuity","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Perpetuities and growing perpetuities","group":"Foundations","aliases":["present value of a perpetuity","perpetual payments","infinite payments"],"finds":"Value of payments that never end","needs":"Payment, rate","text":"PV = C / r"},{"slug":"budget-net-worth-dashboard","name":"Personal Budget and Net Worth Dashboard","level":"Beginner","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Build a personal budget and net worth tracker","group":"Modern finance and practice","aliases":["build a personal budget","net worth tracker","savings rate","months of runway","debt to assets"],"finds":"Where you stand financially this month","needs":"Income, spending, assets, debts","text":"Savings rate = (income - spending) / income; Net worth = total assets - total liabilities; Runway in months = liquid assets / monthly spending; Debt-to-assets = liabilities / assets; Change in net worth = savings + investment gains - debt interest and fees"},{"slug":"pmi-surprise","name":"PMI Diffusion Index and Data Surprise","level":"Beginner","subject":"Economics for Finance","section":"Markets and the Economy","topic":"Economic indicators markets watch (CPI, jobs reports, PMI)","group":"Money, banks and the economy","aliases":["economic indicators","jobs report surprise","CPI surprise","consensus forecast"],"finds":"Whether a survey signals expansion and how big a data surprise was","needs":"Survey shares, actual, consensus and typical surprise","text":"Diffusion index (PMI) = % of firms reporting better + 0.5 x % reporting no change (above 50 means expansion); Surprise z-score = (actual - consensus forecast) / standard deviation of past surprises"},{"slug":"policy-rate-pass-through","name":"Policy Rate Pass-Through to Banks and Borrowers","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Banking","topic":"How monetary policy reaches banks and borrowers","group":"Money, banks and the economy","aliases":["how monetary policy reaches banks and borrowers","deposit beta","loan beta","transmission mechanism"],"finds":"How a policy move changes bank income and borrower costs","needs":"Rate change, betas, floating balances","text":"Change in loan rate = loan beta x change in policy rate; Change in deposit rate = deposit beta x change in policy rate; Change in bank net interest income = loan beta x rate-sensitive loans x change - deposit beta x rate-sensitive deposits x change; Extra annual interest for a floating borrower = loan rate change x balance"},{"slug":"portfolio-esg-score","name":"Portfolio ESG Score and Tilt vs Benchmark","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Sustainable Finance","topic":"ESG investing","group":"Modern finance and practice","aliases":["ESG investing","weighted average ESG score","ESG tilt","negative screening"],"finds":"How a portfolio compares on ESG scores","needs":"Weights, ESG scores, benchmark weights, screen level","text":"Portfolio ESG score = sum of (weight x ESG score) over holdings; Benchmark score = same with benchmark weights; Tilt = portfolio score - benchmark score; Share excluded by a screen = weight of holdings below a minimum score"},{"slug":"portfolio-variance-matrix","name":"Portfolio Variance in Matrix Form","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Linear algebra for finance","group":"Risk and quantitative methods","aliases":["linear algebra","covariance matrix","w transpose sigma w","n asset portfolio risk"],"finds":"The risk of a portfolio of any number of assets","needs":"Weights, volatilities, correlation matrix","text":"Portfolio variance = w-transpose x Covariance matrix x w = sum over all pairs i, j of (w_i x w_j x sd_i x sd_j x correlation_ij)"},{"slug":"position-size-stop-loss","name":"Position Size from a Stop-Loss","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Order types: market, limit, stop","group":"Markets and instruments","aliases":["stop order","risk per trade","stop loss position sizing","order types"],"finds":"How many shares fit a risk limit","needs":"Account size, risk per trade, entry, stop","text":"Shares = (Account size x Risk per trade) / (Entry price - Stop price)"},{"slug":"ppe-rollforward","name":"PP&E Roll-Forward","level":"Beginner","subject":"Accounting Mastery & Financial Modeling","section":"Financial statement mechanics","topic":"Financial statement mechanics","group":"Companies and valuation","aliases":["fixed asset schedule","capex from balance sheets","supporting schedule"],"finds":"Closing PP&E, or the capex implied by two balance sheets","needs":"Opening and closing balances, depreciation, disposals","text":"Ending PP&E = Opening PP&E + Capex - Depreciation - Net book value of disposals; so Capex = Ending - Opening + Depreciation + Disposals"},{"slug":"vc-post-money","name":"Pre-Money and Post-Money Valuation","level":"Beginner","subject":"Corporate Finance","section":"Raising Capital","topic":"Venture capital stages (seed, Series A-D)","group":"Companies and valuation","aliases":["post money valuation","startup ownership after investment","venture capital valuation","series A ownership"],"finds":"Ownership given up in a funding round","needs":"Pre-money valuation, investment","text":"Post-money = Pre-money + Investment; Investor ownership = Investment / Post-money"},{"slug":"preferred-stock-value","name":"Preferred Stock Value","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Common vs. preferred stock","group":"Markets and instruments","aliases":["preferred share price","perpetual preferred","preference shares"],"finds":"The price of a preferred share","needs":"Par value, dividend rate, required return","text":"Value of a preferred share = Fixed dividend per year / Required return"},{"slug":"pv-growing-annuity","name":"Present Value of a Growing Annuity","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Annuities and annuities due","group":"Foundations","aliases":["growing annuity","payments that grow each year","salary stream value"],"finds":"Value today of payments that grow for a fixed number of periods","needs":"First payment, rate, growth, number of payments","text":"PV = C1 / (r - g) x (1 - ((1 + g) / (1 + r))^n)"},{"slug":"pv-lump-sum","name":"Present Value of a Lump Sum","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Present value and discounting","group":"Foundations","aliases":["discounting","present value","PV","discount formula"],"finds":"Value today of a future amount","needs":"Future amount, rate, periods","text":"PV = FV / (1 + r)^n"},{"slug":"pv-annuity-due","name":"Present Value of an Annuity Due","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Annuities and annuities due","group":"Foundations","aliases":["annuity due","payments at the start of the period","PV annuity due"],"finds":"Value today of payments made at the start of each period","needs":"Payment, rate, number of payments","text":"PV(due) = PMT x (1 - (1 + r)^-n) / r x (1 + r)"},{"slug":"pv-ordinary-annuity","name":"Present Value of an Ordinary Annuity","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Annuities and annuities due","group":"Foundations","aliases":["present value of annuity","PV annuity","value of regular payments"],"finds":"Value today of regular payments","needs":"Payment, rate, number of payments","text":"PV = PMT x (1 - (1 + r)^-n) / r"},{"slug":"price-elasticity","name":"Price Elasticity of Demand (Midpoint)","level":"Beginner","subject":"Economics for Finance","section":"How the Economy Works","topic":"Supply, demand and prices","group":"Money, banks and the economy","aliases":["elasticity","revenue effect of price change","elastic vs inelastic"],"finds":"How strongly quantity responds to price","needs":"Two price and quantity pairs","text":"Elasticity = (change in quantity / average quantity) / (change in price / average price). Revenue = price x quantity"},{"slug":"price-improvement","name":"Price Improvement (Order Flow)","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Retail trading and payment for order flow","group":"Markets and instruments","aliases":["payment for order flow","PFOF","NBBO","retail execution"],"finds":"How much better than the best quote your order filled","needs":"Best quote, execution price, shares","text":"Price improvement = (Best quoted price - Price you got) x Shares; for a sell it is (Price you got - Best quoted price) x Shares"},{"slug":"price-target-upside","name":"Price Target and Upside (Equity Research)","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Equity research reports","group":"Markets and instruments","aliases":["analyst price target","target price","research report valuation","implied return"],"finds":"The price an analyst\'s assumptions imply","needs":"Forward EPS, target P/E, current price","text":"Target price = Forward EPS x Target P/E; Upside = Target price / Current price - 1"},{"slug":"price-weighted-index","name":"Price-Weighted Index and Divisor","level":"Beginner","subject":"Equity Markets","section":"Equities","topic":"Stock indices: construction and weighting","group":"Markets and instruments","aliases":["Dow Jones","stock split divisor","index divisor","Nikkei"],"finds":"An index level and its divisor after a split","needs":"Prices, divisor, split ratio","text":"Index = Sum of the share prices / Divisor; New divisor after a split = New sum of prices / Index level before the split"},{"slug":"price-yield-approximation","name":"Price-Yield Relationship: Duration and Convexity Estimate","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Price-yield relationship","group":"Markets and instruments","aliases":["price change estimate","bond price sensitivity","interest rate risk","price yield curve"],"finds":"An estimate of how far a bond price moves","needs":"Bond terms, current yield, yield change","text":"Percentage price change = -Modified duration x Change in yield + 0.5 x Convexity x (Change in yield)^2"},{"slug":"pca-variance-explained","name":"Principal Component Analysis: Variance Explained (Two Assets)","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Principal component analysis and factor models","group":"Risk and quantitative methods","aliases":["PCA","eigenvalues","factor models","first principal component"],"finds":"How much of the risk one common factor explains","needs":"Volatilities and correlation","text":"Eigenvalues of the covariance matrix = (var1 + var2) / 2 plus or minus sqrt(((var1 - var2) / 2)^2 + cov^2); Share of variance explained by the first component = first eigenvalue / (sum of eigenvalues)"},{"slug":"private-credit-net-yield","name":"Private Credit: Net Yield after Losses and Fees","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Private credit and direct lending","group":"Modern finance and practice","aliases":["direct lending","private credit and direct lending","all-in yield","illiquidity premium","levered private credit return"],"finds":"A private loan fund\'s return after losses, fees and leverage","needs":"Base rate, spread, discount, default and loss assumptions, fees, leverage","text":"All-in yield = base rate + spread + upfront discount spread over the life; Expected credit loss = probability of default x loss given default; Net return = all-in yield - expected loss - fund fees; Return with leverage = net return + (debt / equity) x (net return - cost of debt)"},{"slug":"pe-carry-waterfall","name":"Private Equity Distribution Waterfall and Carry","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Private equity firms","group":"Money, banks and the economy","aliases":["private equity firms","carried interest","preferred return","catch-up","TVPI DPI"],"finds":"How a private equity fund splits its profit","needs":"Capital, proceeds, hurdle, carry, years","text":"Order of payment: (1) return of capital to investors, (2) preferred return, (3) catch-up to the manager until it holds the carry share of all profit, (4) remaining profit split with carry % to the manager. With full catch-up the manager ends with carry % x total profit once profits are large enough"},{"slug":"fund-performance-metrics","name":"Private Fund Metrics: IRR, MOIC, TVPI, DPI, RVPI","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Fund performance metrics: IRR, MOIC, TVPI, DPI","group":"Modern finance and practice","aliases":["TVPI","DPI","RVPI","MOIC","PME","net IRR"],"finds":"How much a private fund has returned and what it is worth in total","needs":"Calls, distributions by year, remaining value","text":"DPI = total distributions / total paid-in capital (cash actually returned); RVPI = remaining net asset value / paid-in capital (value still held); TVPI = DPI + RVPI (total value per unit paid in, also called the net multiple); IRR = rate that sets the net present value of calls, distributions and final NAV to zero"},{"slug":"normal-probability","name":"Probability from a Normal Distribution","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Normal and lognormal distributions","group":"Foundations","aliases":["normal cdf","chance of a loss","probability of return below","bell curve probability"],"finds":"Chance of an outcome under a bell curve","needs":"Value, mean, standard deviation","text":"P(X <= x) = Phi((x - mean) / standard deviation)"},{"slug":"profit-margins","name":"Profit Margins","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Income statement","group":"Foundations","aliases":["gross margin","operating margin","net margin","margin ratios"],"finds":"Profit as a share of sales","needs":"Revenue, COGS, operating expenses, net income","text":"Gross margin = (Revenue - COGS) / Revenue; Operating margin = (Revenue - COGS - Opex) / Revenue; Net margin = Net income / Revenue"},{"slug":"profitability-index","name":"Profitability Index","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Profitability index","group":"Companies and valuation","aliases":["PI","benefit cost ratio","value per unit invested"],"finds":"Value per unit invested","needs":"Initial investment, discount rate, future cash flows","text":"PI = PV of future cash flows / Initial investment"},{"slug":"income-tax-brackets","name":"Progressive Income Tax: Marginal and Effective Rates","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Personal taxes and tax-advantaged investing","group":"Personal finance","aliases":["personal taxes","tax brackets","marginal tax rate","effective tax rate"],"finds":"Tax due and the rate that applies to the next unit of income","needs":"Taxable income and a bracket schedule","text":"Tax = for each bracket k, bracket rate x the part of taxable income that falls inside that bracket (between its lower and upper limits), added up; Effective rate = tax / taxable income; Marginal rate = rate of the bracket the last unit of income falls in"},{"slug":"project-operating-cash-flow","name":"Project Operating Cash Flow","level":"Intermediate","subject":"Corporate Finance","section":"Capital Budgeting","topic":"Incremental cash flows","group":"Companies and valuation","aliases":["OCF","tax shield approach","incremental cash flow","operating cash flow capital budgeting"],"finds":"Yearly cash flow from a project","needs":"Sales, costs, depreciation, tax rate","text":"OCF = (Sales - Cash costs) x (1 - T) + Depreciation x T"},{"slug":"promised-return-reality-check","name":"Promised Return Reality Check","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Avoiding scams and fraud","group":"Personal finance","aliases":["avoiding scams and fraud","Ponzi scheme warning","too good to be true","guaranteed returns"],"finds":"What a promised return implies per year and versus the market","needs":"Promised return, amount, years","text":"Equivalent annual rate = (1 + monthly return)^12 - 1; Value after n years = Principal x (1 + monthly return)^(12 x n); Months to double = ln 2 / ln(1 + monthly return)"},{"slug":"coinsurance-penalty","name":"Property Insurance Coinsurance Penalty","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Insurance: life, health, property, disability","group":"Personal finance","aliases":["underinsurance","property insurance","coinsurance clause","insurance to value"],"finds":"How much a property claim pays when you are underinsured","needs":"Value, requirement, cover carried, loss, deductible","text":"Required cover = coinsurance % x property value; If cover carried is below that, Payout = Loss x (cover carried / required cover) - deductible, capped at cover carried; otherwise Payout = Loss - deductible, capped at cover carried"},{"slug":"prospect-theory-value","name":"Prospect Theory Value of a Gamble","level":"Intermediate","subject":"Behavioral Finance","section":"Behavioral","topic":"Prospect theory and loss aversion","group":"Modern finance and practice","aliases":["loss aversion","Kahneman Tversky","probability weighting","value function"],"finds":"Whether a gamble feels attractive despite its expected value","needs":"Gain, loss, probability and preference parameters","text":"Value of an outcome x: gains = x^alpha; losses = - lambda x (-x)^beta... precisely: gain value = x^alpha, loss value = - lambda x |x|^beta, with typical alpha = beta = 0.88 and loss aversion lambda = 2.25; Decision weight of a probability p = p^gamma / (p^gamma + (1 - p)^gamma)^(1/gamma), gamma about 0.61 for gains and 0.69 for losses; Prospect value of a gamble = w(p) x v(gain) + w(1 - p) x v(loss)"},{"slug":"psa-prepayment","name":"PSA Prepayment Speed, CPR and SMM","level":"Intermediate","subject":"Fixed Income","section":"Securitized Products","topic":"Prepayment risk","group":"Markets and instruments","aliases":["PSA benchmark","conditional prepayment rate","single monthly mortality","prepayment risk","extension risk","contraction risk"],"finds":"Prepayment speed in annual and monthly terms","needs":"PSA speed, age of the pool","text":"CPR = PSA speed x 6% x min(month / 30, 1); SMM = 1 - (1 - CPR)^(1/12)"},{"slug":"purchasing-power","name":"Purchasing Power of Money Over Time","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Real vs. nominal returns and inflation adjustment","group":"Foundations","aliases":["value of money after inflation","inflation erosion","real value of future money"],"finds":"What a future amount buys in today\'s prices","needs":"Future amount, inflation, years","text":"Real value today = Amount / (1 + i)^n"},{"slug":"ppp-expected-rate","name":"Purchasing Power Parity: Valuation and Expected Rate","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Purchasing power parity","group":"Money, banks and the economy","aliases":["PPP","Big Mac index","real exchange rate","relative PPP"],"finds":"Whether a currency looks over or under-valued and where parity points","needs":"Basket prices, spot, inflation rates","text":"Absolute PPP rate (foreign currency per 1 domestic) = foreign price of a basket / domestic price of the same basket; Misvaluation = spot / PPP rate - 1; Relative PPP: the foreign currency per domestic unit changes by (1 + foreign inflation) / (1 + domestic inflation) each year"},{"slug":"put-call-parity","name":"Put-Call Parity","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Put-call parity","group":"Markets and instruments","aliases":["synthetic put","synthetic call","conversion arbitrage","parity relationship"],"finds":"Whether call and put prices fit together","needs":"Stock, strike, rate, dividend yield, time, call and put prices","text":"Call price - Put price = Spot x e^(-dividend yield x T) - Strike x e^(-r x T)"},{"slug":"quantity-theory-of-money","name":"Quantity Theory of Money","level":"Intermediate","subject":"Monetary Economics & the Financial System","section":"Money, banking, and central banks","topic":"Money, banking, and central banks","group":"Money, banks and the economy","aliases":["equation of exchange","MV=PY","velocity of money","money growth and inflation"],"finds":"Inflation implied by money growth","needs":"Money, nominal GDP, growth rates","text":"Money supply x velocity = price level x real output (= nominal GDP); Velocity = nominal GDP / money supply; Inflation = (1 + money growth) x (1 + velocity growth) / (1 + real output growth) - 1"},{"slug":"quick-ratio","name":"Quick Ratio (Acid Test)","level":"Beginner","subject":"Finance Foundations","section":"What Finance Is","topic":"Liquidity, solvency and leverage (concepts)","group":"Foundations","aliases":["acid test","liquidity ratio without inventory"],"finds":"Short-term liquidity without counting inventory","needs":"Cash, securities, receivables, current liabilities","text":"Quick ratio = (Cash + Marketable securities + Receivables) / Current liabilities"},{"slug":"r-squared","name":"R-Squared (Coefficient of Determination)","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Correlation vs. causation","group":"Foundations","aliases":["R2","goodness of fit","share of variation explained"],"finds":"How closely two series move together","needs":"Two lists of returns","text":"R-squared = correlation squared"},{"slug":"raroc-limit-utilization","name":"RAROC and Risk Limit Utilization","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Risk appetite and limits","group":"Risk and quantitative methods","aliases":["risk adjusted return on capital","risk appetite","VaR limit","hurdle rate"],"finds":"Return on risk capital and how much of a risk limit is used","needs":"Revenue, costs, expected loss, economic capital, VaR, limit","text":"RAROC = (Revenue - Costs - Expected loss) / Economic capital; Limit utilization = Risk used / Limit"},{"slug":"fed-funds-futures-probability","name":"Rate Expectations from Policy Rate Futures","level":"Intermediate","subject":"Economics for Finance","section":"Markets and the Economy","topic":"How markets react to economic data","group":"Money, banks and the economy","aliases":["how markets react to economic data","FedWatch","implied policy rate","probability of a rate hike"],"finds":"The odds markets assign to a policy move","needs":"Futures price, current rate, meeting timing, move size","text":"Implied average rate for the month = 100 - futures price; Rate after the meeting = (implied rate x days in month - current rate x days before the meeting) / days after the meeting; Probability of a move = (rate after meeting - current rate) / size of the move"},{"slug":"rational-bubble-growth","name":"Rational Bubble: Required Growth and Survival","level":"Intermediate","subject":"Behavioral Finance","section":"Behavioral","topic":"Bubbles and manias","group":"Modern finance and practice","aliases":["bubbles and manias","Blanchard Watson","bubble burst probability","explosive growth"],"finds":"How fast a bubble must grow and how likely it is to last","needs":"Required return, burst probability, bubble size, years","text":"If a bubble bursts with probability pi each period, holders require the bubble part of the price to grow, while it survives, at g = (1 + r) / (1 - pi) - 1 so that the expected return stays at r; Chance it survives n periods = (1 - pi)^n; Bubble size after n periods if it survives = B0 x (1 + g)^n"},{"slug":"news-move-significance","name":"Reading the News: Is This Move Unusual?","level":"Beginner","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Follow financial news critically","group":"Modern finance and practice","aliases":["follow financial news critically","headline move","z-score of a daily move","how often does this happen"],"finds":"How unusual a market move is for that asset","needs":"Return on the day and typical daily volatility","text":"Size of the move in standard deviations = daily return / typical daily volatility; Chance of a move at least this large in either direction under a normal distribution = 2 x (1 - normal cumulative of |z|); About how many trading days between such moves = 1 / that chance; Real markets have fatter tails, so large moves happen more often than a normal curve suggests"},{"slug":"real-return","name":"Real Return (Inflation-Adjusted)","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Real vs. nominal returns and inflation adjustment","group":"Foundations","aliases":["Fisher equation","real interest rate","inflation adjusted return","nominal vs real"],"finds":"Growth in buying power","needs":"Nominal return, inflation","text":"real = (1 + nominal) / (1 + inflation) - 1"},{"slug":"real-value-of-savings","name":"Real Value of Savings After Inflation","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Inflation and the real value of savings","group":"Personal finance","aliases":["inflation and the real value of savings","purchasing power of cash","real interest rate","inflation erosion"],"finds":"What your savings will really buy","needs":"Balance, interest rate, inflation, years","text":"Real value = Balance x (1 + interest rate)^n / (1 + inflation)^n; Real interest rate = (1 + interest rate) / (1 + inflation) - 1"},{"slug":"rebalancing-trades","name":"Rebalancing Trades","level":"Beginner","subject":"Investments & Portfolio Theory","section":"Portfolio Management","topic":"Rebalancing","group":"Markets and instruments","aliases":["portfolio rebalancing","back to target weights","asset allocation drift","strategic asset allocation"],"finds":"How much to buy and sell to restore target weights","needs":"Current values, target weights","text":"Trade for asset i = Target weight x Total portfolio value - Current value of asset i"},{"slug":"recovery-rate","name":"Recovery Rate and Loss Given Default","level":"Beginner","subject":"Corporate Finance","section":"Mergers & Restructuring","topic":"Bankruptcy and insolvency: liquidation vs. reorganization","group":"Companies and valuation","aliases":["LGD","loss given default","bankruptcy recovery","creditor recovery"],"finds":"What lenders get back after default","needs":"Claim, amount recovered","text":"Recovery rate = Amount recovered / Claim; Loss given default = 1 - Recovery rate"},{"slug":"regression-line","name":"Regression Line (Alpha and Beta)","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Linear regression and beta estimation","group":"Foundations","aliases":["linear regression","OLS","line of best fit","jensen alpha","intercept and slope"],"finds":"The best-fit line and a stock\'s beta and alpha","needs":"Two lists of returns","text":"y-hat = alpha + beta x, with beta = Cov(x,y) / Var(x) and alpha = mean y - beta x mean x"},{"slug":"sinking-fund-payment","name":"Regular Saving Needed to Reach a Goal","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Annuities and annuities due","group":"Foundations","aliases":["sinking fund","how much to save each year","savings goal payment","required deposit"],"finds":"The regular deposit needed for a savings goal","needs":"Goal amount, rate, number of deposits","text":"PMT = FV x r / ((1 + r)^n - 1)"},{"slug":"reinsurance-recoveries","name":"Reinsurance: Quota Share and Excess of Loss","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Reinsurance","group":"Money, banks and the economy","aliases":["reinsurance","ceded loss","retention","layer"],"finds":"What the insurer keeps after reinsurance","needs":"Loss, quota share, retention and limit","text":"Quota share: the reinsurer takes a fixed share q of every loss and premium; Excess of loss: the reinsurer pays the part of a loss above the retention R, up to the limit; Net retained loss = gross loss - recovery"},{"slug":"reit-ffo-affo","name":"REIT Funds From Operations (FFO) and AFFO","level":"Beginner","subject":"Alternative Investments","section":"Alternatives","topic":"Real estate investing and REITs","group":"Modern finance and practice","aliases":["FFO","AFFO","P/FFO","REIT payout ratio"],"finds":"A REIT\'s cash earnings, valuation multiple and dividend cover","needs":"Net income, depreciation, gains, capex, rent adjustment, shares, price, dividend","text":"FFO = net income + depreciation and amortization - gains on property sales; AFFO = FFO - recurring maintenance capital spending - straight-line rent adjustments; Price / FFO = share price / FFO per share; Payout ratio = dividend per share / AFFO per share"},{"slug":"rsi","name":"Relative Strength Index (RSI)","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Technical analysis","group":"Markets and instruments","aliases":["technical analysis","overbought oversold","momentum oscillator","RSI 14"],"finds":"Recent price momentum on a 0 to 100 scale","needs":"A list of closing prices","text":"RSI = 100 - 100 / (1 + RS), where RS = average of the up-moves / average of the down-moves over the period"},{"slug":"relever-beta","name":"Relevering Beta","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Unlevering and relevering beta","group":"Companies and valuation","aliases":["levered beta","Hamada equation","beta with target capital structure"],"finds":"Beta for a chosen capital structure","needs":"Unlevered beta, target debt-to-equity, tax rate","text":"Levered beta = Unlevered beta x (1 + (1 - T) x D/E)"},{"slug":"loan-balance","name":"Remaining Loan Balance","level":"Intermediate","subject":"Finance Foundations","section":"Financial Math","topic":"Loan amortization schedules","group":"Foundations","aliases":["outstanding balance","balance after k payments","amortization balance","how much do I still owe"],"finds":"How much of a loan is still owed","needs":"Loan amount, rate, term, payments made","text":"Balance after k payments = P x (1 + r)^k - PMT x ((1 + r)^k - 1) / r"},{"slug":"rent-vs-buy-user-cost","name":"Rent vs Buy: Annual Cost of Owning","level":"Intermediate","subject":"Personal Finance","section":"Personal Finance","topic":"Renting vs. buying a home","group":"Personal finance","aliases":["renting vs buying a home","user cost of housing","price to rent ratio","break even rent"],"finds":"Whether owning costs more or less than renting, per year","needs":"Price, mortgage, tax, upkeep, growth, rent","text":"Annual cost of owning = Price x [mortgage rate x (1 - down payment share) + opportunity return x down payment share + property tax rate + maintenance rate - price growth rate]; Price-to-rent ratio = Price / (12 x monthly rent)"},{"slug":"replicating-portfolio","name":"Replicating Portfolio (One-Step Binomial)","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Delta hedging and replication","group":"Markets and instruments","aliases":["replication","synthetic option","no arbitrage option price","hedge ratio"],"finds":"A portfolio that copies an option, and its value","needs":"Stock, up and down factors, rate, strike","text":"Shares held (delta) = (Option value if up - Option value if down) / (Stock price up - Stock price down); Bond holding B = (Option value if up - Delta x Stock price up) / (1 + r); Option value = Delta x S + B"},{"slug":"repo-interest","name":"Repo: Interest, Haircut and Repurchase Price","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Repo markets","group":"Markets and instruments","aliases":["repurchase agreement","repo rate","haircut","collateral","reverse repo"],"finds":"The cash, interest and repayment on a repo","needs":"Collateral value, haircut, repo rate, days","text":"Cash lent = Collateral value x (1 - Haircut); Interest = Cash x Repo rate x Days / 360; Repurchase price = Cash + Interest"},{"slug":"repricing-gap","name":"Repricing Gap and Net Interest Income","level":"Beginner","subject":"Banking & Financial Institutions","section":"Banking","topic":"Asset-liability management","group":"Money, banks and the economy","aliases":["asset liability management","rate sensitivity gap","NII sensitivity"],"finds":"How a rate move changes next-year income","needs":"Rate-sensitive assets and liabilities, rate change","text":"Repricing gap = rate-sensitive assets - rate-sensitive liabilities (those that reset within the horizon); Change in net interest income = gap x change in interest rates"},{"slug":"reserve-adequacy","name":"Reserve Adequacy Metrics","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Exchange rate regimes","group":"Money, banks and the economy","aliases":["exchange rate regimes","foreign exchange reserves","Greenspan-Guidotti","IMF ARA metric","import cover"],"finds":"Whether reserves are large enough for the exchange rate regime","needs":"Reserves, imports, exports, money, short-term debt, other liabilities","text":"Import cover (months) = reserves / (annual imports / 12); Short-term debt cover = reserves / short-term external debt (Greenspan-Guidotti: at least 1); IMF reserve adequacy metric (fixed exchange rate) = 5% of exports + 5% of broad money + 30% of short-term debt + 15% of other liabilities (weights for a fixed regime; floating regimes use lower ones)"},{"slug":"reserve-requirement-cost-of-funds","name":"Reserve Requirement Wedge and Offshore Deposit Rates","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Eurodollar and offshore markets","group":"Money, banks and the economy","aliases":["eurodollar and offshore markets","euro market","reserve requirement tax","deposit insurance cost"],"finds":"The cost advantage of an offshore bank","needs":"Deposit rate, reserve requirement, insurance charges","text":"Domestic bank\'s effective cost per dollar it can lend = (deposit rate + insurance fee) / (1 - reserve requirement); Offshore bank\'s cost = deposit rate (no reserve requirement or insurance); Wedge = domestic cost - offshore cost"},{"slug":"residual-income","name":"Residual Income Valuation","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Residual income / economic value added (EVA)","group":"Companies and valuation","aliases":["RI","residual income model","excess earnings","abnormal earnings"],"finds":"Equity value from book value and excess profit","needs":"Book value, net income, cost of equity, growth","text":"Residual income = Net income - Required return x Opening book value; Value = Book value + RI next year / (r - g)"},{"slug":"retained-earnings","name":"Retained Earnings Roll-Forward","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Statement of shareholders\' equity","group":"Foundations","aliases":["retained earnings formula","statement of equity","ending retained earnings"],"finds":"Retained earnings at the end of a period","needs":"Beginning retained earnings, net income, dividends","text":"Ending RE = Beginning RE + Net income - Dividends"},{"slug":"retirement-nest-egg","name":"Retirement Nest Egg and Required Saving","level":"Intermediate","subject":"Personal Finance","section":"Personal Finance","topic":"Retirement accounts and pension schemes","group":"Personal finance","aliases":["retirement accounts","pension target","retirement savings goal","how much to save for retirement"],"finds":"The nest egg you need and what to save each year","needs":"Ages, income goal, inflation, returns, current savings","text":"Nest egg needed at retirement = first-year income / (r - inflation) x [1 - ((1 + inflation) / (1 + r))^L]; Yearly saving needed = (nest egg - current savings x (1 + g)^N) x g / ((1 + g)^N - 1)"},{"slug":"margin-return","name":"Return on a Margin Purchase","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Margin trading","group":"Markets and instruments","aliases":["buying on margin","leverage return","margin loan","levered equity return"],"finds":"How borrowing magnifies a return","needs":"Own money, margin, prices, loan rate, years","text":"Return on equity = (Shares x Price change - Loan x Interest rate x Years) / Your own money; Loan = Shares x Start price - Your own money"},{"slug":"return-on-assets","name":"Return on Assets (ROA)","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Return on assets (ROA)","group":"Companies and valuation","aliases":["ROA","asset profitability","unlevered ROA"],"finds":"Profit earned per unit of assets","needs":"Net income, interest, tax rate, opening and closing assets","text":"ROA = Net income / Average total assets; Unlevered ROA = (Net income + Interest x (1 - tax rate)) / Average total assets"},{"slug":"return-on-equity","name":"Return on Equity (ROE)","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Return on equity (ROE)","group":"Companies and valuation","aliases":["ROE","return to shareholders","return on common equity"],"finds":"Return earned on shareholders\' money","needs":"Net income, preferred dividends, opening and closing equity","text":"ROE = (Net income - Preferred dividends) / Average common shareholders\' equity"},{"slug":"percentage-of-completion","name":"Revenue Recognized by Percentage of Completion","level":"Intermediate","subject":"Finance Foundations","section":"Accounting Basics","topic":"Revenue recognition","group":"Foundations","aliases":["revenue recognition formula","contract revenue","cost-to-cost method"],"finds":"Revenue to record on a long contract","needs":"Contract price, costs to date, estimated total costs, earlier revenue","text":"Revenue to date = Contract price x (Costs to date / Estimated total costs)"},{"slug":"rights-issue-terp","name":"Rights Issue: Ex-Rights Price and Value of a Right","level":"Intermediate","subject":"Corporate Finance","section":"Raising Capital","topic":"Rights issues","group":"Companies and valuation","aliases":["TERP","theoretical ex-rights price","value of a right","rights offering"],"finds":"Share price after a rights issue","needs":"Price, subscription price, rights ratio","text":"TERP = (N x P + n x S) / (N + n), and Value of a right = P - TERP"},{"slug":"portfolio-variance-two-assets","name":"Risk of a Two-Asset Portfolio","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Expected return and risk of a portfolio","group":"Markets and instruments","aliases":["portfolio standard deviation","portfolio variance","diversification benefit","two asset portfolio risk"],"finds":"Portfolio risk and diversification benefit","needs":"Weight, two standard deviations, correlation","text":"Portfolio variance = w1^2 x s1^2 + w2^2 x s2^2 + 2 x w1 x w2 x rho x s1 x s2"},{"slug":"risk-parity-weights","name":"Risk Parity Weights (Inverse Volatility)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Management","topic":"Risk parity","group":"Markets and instruments","aliases":["risk parity","inverse volatility weights","equal risk contribution"],"finds":"Weights that equalize risk","needs":"Volatility of each asset","text":"Weight of asset i = (1 / its volatility) / sum of (1 / volatility) across all assets"},{"slug":"risk-premium","name":"Risk Premium","level":"Beginner","subject":"Finance Foundations","section":"What Finance Is","topic":"Risk and return: the core trade-off","group":"Foundations","aliases":["excess return","equity risk premium","return above risk-free"],"finds":"Extra return earned for taking risk","needs":"Expected return, risk-free rate","text":"Risk premium = Expected return - Risk-free rate"},{"slug":"risk-neutral-pricing","name":"Risk-Neutral Probability and Pricing","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Risk-neutral valuation","group":"Risk and quantitative methods","aliases":["risk neutral valuation","equivalent martingale measure","state prices","Q measure"],"finds":"An option price from risk-neutral probabilities","needs":"Prices in the two states, rate, strike","text":"Risk-neutral probability of the up state = (Spot x e^(rT) - Down price) / (Up price - Down price); Value = e^(-rT) x [q x Payoff if up + (1 - q) x Payoff if down]"},{"slug":"rule-of-40","name":"Rule of 40","level":"Beginner","subject":"Valuation","section":"Valuation","topic":"Valuing startups and high-growth firms","group":"Companies and valuation","aliases":["SaaS metric","growth plus margin","startup health"],"finds":"Balance of growth and profit","needs":"Revenue growth, profit margin","text":"Rule of 40 score = Revenue growth rate + Profit margin (often free cash flow or EBITDA margin)"},{"slug":"rule-of-72","name":"Rule of 72","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Rule of 72","group":"Foundations","aliases":["doubling time","how long to double money","rule of seventy two"],"finds":"Years for money to double","needs":"Annual rate","text":"Years to double = 72 / r, with r as a percentage"},{"slug":"sahm-rule-indicator","name":"Sahm Rule Recession Indicator","level":"Intermediate","subject":"Economics for Finance","section":"Markets and the Economy","topic":"Recessions and their warning signs","group":"Money, banks and the economy","aliases":["recessions and their warning signs","unemployment trigger","yield curve inversion"],"finds":"Two classic recession warning signals","needs":"A run of monthly unemployment rates and two yields","text":"Sahm indicator = latest 3-month average unemployment rate - the lowest 3-month average of the previous 12 months. A reading of 0.5 percentage points or more has signaled the start of past US recessions. Yield curve spread = 10-year yield - 3-month yield (negative means inverted)"},{"slug":"sample-size-mean","name":"Sample Size for Estimating a Mean","level":"Beginner","subject":"Data, Statistics & Computational Skills","section":"Quantitative foundations","topic":"Quantitative foundations","group":"Risk and quantitative methods","aliases":["quantitative foundations","margin of error","confidence interval width","how many observations"],"finds":"How many observations an estimate needs","needs":"Standard deviation, margin of error, confidence level","text":"Sample size = (z-value for the confidence level x standard deviation / margin of error)^2, rounded up"},{"slug":"sanctions-ownership-aggregation","name":"Sanctions: 50% Ownership Aggregation Rule","level":"Beginner","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Financial sanctions","group":"Modern finance and practice","aliases":["financial sanctions","OFAC 50 percent rule","blocked persons","ownership screening"],"finds":"Whether an entity counts as sanctioned through its owners","needs":"Ownership stakes of sanctioned owners","text":"Under the US Treasury (OFAC) 50 percent rule, an entity owned 50% or more in total by one or more sanctioned persons is itself treated as sanctioned; Add up the stakes of all sanctioned owners (each stake alone can be below 50%); Total = sum of the stakes of blocked owners; Check whether total is 50% or more"},{"slug":"sdr-basket-value","name":"SDR Basket Valuation","level":"Beginner","subject":"International Finance","section":"Global Finance","topic":"IMF, World Bank and BIS","group":"Money, banks and the economy","aliases":["IMF, World Bank and BIS","special drawing right","IMF reserve asset","basket currency"],"finds":"The dollar value and composition of the SDR","needs":"Basket amounts and exchange rates","text":"Value of 1 SDR in dollars = sum over the basket currencies of (fixed amount of the currency in the basket x its dollar exchange rate); Weight of currency i = its dollar value in the basket / total value"},{"slug":"secondary-purchase-irr","name":"Secondaries: Price Versus NAV and Buyer IRR","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Secondaries and continuation funds","group":"Modern finance and practice","aliases":["secondaries and continuation funds","discount to NAV","LP stake sale","unfunded commitment"],"finds":"What a buyer earns on a fund stake bought at a discount","needs":"NAV, discount, expected distributions, unfunded call","text":"Price paid = reported NAV x (1 - discount); Buyer cash flows = distributions received - further capital the buyer must fund (unfunded commitment); Buyer IRR solves NPV = 0; Buyer multiple = total distributions / (price + unfunded capital called)"},{"slug":"securities-lending-income","name":"Securities Lending Income","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Securities lending","group":"Markets and instruments","aliases":["stock lending","rebate rate","collateral reinvestment","lending fee"],"finds":"Extra income earned by lending shares","needs":"Collateral, reinvestment rate, rebate, days, agent share","text":"Income = Collateral x (Reinvestment return - Rebate rate) x Days / 365 x (1 - Agent share)"},{"slug":"security-market-line","name":"Security Market Line and Alpha","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Security market line and beta","group":"Markets and instruments","aliases":["SML","required return","over or undervalued","CAPM alpha check"],"finds":"Whether a stock offers enough return for its risk","needs":"Risk-free rate, market return, beta, forecast","text":"Required return = rf + beta x (E(Rm) - rf); alpha = forecast return - required return"},{"slug":"segment-analysis","name":"Segment Reporting Analysis","level":"Beginner","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Segment reporting","group":"Companies and valuation","aliases":["segment margin","business segments","revenue mix","segment contribution"],"finds":"Which segments earn the group\'s profit","needs":"Revenue and profit by segment","text":"Segment margin = Segment profit / Segment revenue; Revenue share = Segment revenue / Total revenue; Profit share = Segment profit / Total profit"},{"slug":"seigniorage","name":"Seigniorage and the Inflation Tax","level":"Intermediate","subject":"Economics for Finance","section":"Money, Rates and Policy","topic":"What central banks do","group":"Money, banks and the economy","aliases":["what central banks do","monetary base","profit from issuing money"],"finds":"What issuing money earns","needs":"Monetary base, growth, interest rate, inflation","text":"Seigniorage from base growth = change in the monetary base; Interest saved = nominal interest rate x monetary base (the base is a free loan from the public); Inflation tax = inflation rate x real money balances"},{"slug":"share-repurchase-eps","name":"Share Repurchase Effect on EPS","level":"Intermediate","subject":"Corporate Finance","section":"Payout Policy","topic":"Share buybacks","group":"Companies and valuation","aliases":["buyback EPS","share buyback accretion","repurchase shares"],"finds":"EPS after a buyback","needs":"Net income, shares, buyback amount, price","text":"Shares bought = Amount spent / Price; New EPS = Net income / (Shares before - Shares bought)"},{"slug":"sharpe-ratio","name":"Sharpe Ratio","level":"Beginner","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Sharpe ratio","group":"Markets and instruments","aliases":["reward to variability","risk adjusted return","excess return per unit of risk"],"finds":"Return per unit of total risk","needs":"Return, risk-free rate, standard deviation","text":"Sharpe ratio = (Portfolio return - Risk-free rate) / Portfolio standard deviation"},{"slug":"short-sale-return","name":"Short Sale Profit and Return","level":"Intermediate","subject":"Equity Markets","section":"Equities","topic":"Short selling","group":"Markets and instruments","aliases":["short selling","borrowing shares","short position return","cost to borrow"],"finds":"The result of a short sale","needs":"Sale and buy-back prices, shares, dividends, fee, days, margin","text":"Profit = (Sale price - Buy-back price) x Shares - Dividends owed - Borrow fee; Borrow fee = Sale value x Fee rate x Days / 365"},{"slug":"short-swing-profit-16b","name":"Short-Swing Profit Recovery (US Section 16(b))","level":"Intermediate","subject":"Regulation, Ethics & ESG","section":"Regulation","topic":"Core securities laws (US Securities Act 1933 and Exchange Act 1934)","group":"Modern finance and practice","aliases":["Securities Exchange Act 1934","insider short-swing rule","lowest-in highest-out"],"finds":"The profit a corporate insider must pay back","needs":"Purchases and sale within six months","text":"For a company insider, a purchase and a sale of the company\'s stock within six months can be matched; the profit to be paid back to the company is calculated by matching the lowest-priced purchases with the highest-priced sales; Recoverable profit = sum over matched shares of (sale price - purchase price) x shares matched; Losses on other matches cannot be used to offset it"},{"slug":"simple-interest","name":"Simple Interest","level":"Beginner","subject":"Finance Foundations","section":"Financial Math","topic":"Simple vs. compound interest","group":"Foundations","aliases":["simple interest formula","interest on principal only"],"finds":"Interest earned and total amount","needs":"Principal, rate, time","text":"I = P x r x t"},{"slug":"moving-average","name":"Simple Moving Average","level":"Beginner","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Time series basics","group":"Foundations","aliases":["SMA","rolling average","trend smoothing","time series average"],"finds":"A smoothed trend value","needs":"List of values in time order, window length","text":"SMA = (sum of the last k values) / k"},{"slug":"simple-vs-log-return","name":"Simple Return and Log Return","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Normal and lognormal distributions","group":"Foundations","aliases":["continuously compounded return","ln return","logarithmic return"],"finds":"Two ways to measure a price change","needs":"Start price, end price","text":"Simple return R = P1 / P0 - 1, and log return r = ln(P1 / P0)"},{"slug":"gbm-step","name":"Simulated Price Step (Monte Carlo)","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Monte Carlo simulation (intro)","group":"Foundations","aliases":["geometric Brownian motion","random price path","monte carlo price","lognormal price simulation"],"finds":"One simulated price step","needs":"Price, return, volatility, step length, a random draw z","text":"S(next) = S x exp((mu - sigma^2 / 2) x dt + sigma x sqrt(dt) x z)"},{"slug":"skewness","name":"Skewness","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Skewness and kurtosis (fat tails)","group":"Foundations","aliases":["asymmetry of returns","third moment","fat tail direction"],"finds":"Whether returns are lopsided","needs":"List of returns","text":"Skewness = average of ((Ri - mean) / standard deviation)^3"},{"slug":"sofr-futures","name":"SOFR Futures Price, Rate and Tick Value","level":"Beginner","subject":"Derivatives","section":"Derivatives","topic":"Interest rate futures: SOFR and bond futures","group":"Markets and instruments","aliases":["interest rate futures","3 month SOFR","Eurodollar futures","basis point value of a future"],"finds":"The rate in a SOFR futures price and your gain or loss","needs":"Futures price, contracts, notional","text":"Futures price = 100 - Implied rate (in %); Value of 1 basis point = Notional x 0.25 x 0.0001"},{"slug":"solow-steady-state","name":"Solow Model Steady State","level":"Intermediate","subject":"Economics for Finance","section":"How the Economy Works","topic":"Productivity and long-run growth","group":"Money, banks and the economy","aliases":["capital per worker","golden rule saving rate","long-run growth model"],"finds":"The long-run level of output per worker","needs":"Saving rate, productivity, depreciation, labor growth, capital share","text":"Steady-state capital per worker k* = (s x A / (depreciation + labor force growth))^(1 / (1 - alpha)); Output per worker y* = A x k*^alpha; Consumption per worker c* = (1 - s) x y*. Consumption is highest when the saving rate s equals alpha"},{"slug":"sortino-ratio","name":"Sortino Ratio","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Sortino ratio","group":"Markets and instruments","aliases":["downside deviation","downside risk adjusted return","minimum acceptable return"],"finds":"Return per unit of downside risk","needs":"Returns, minimum acceptable return","text":"Sortino = (Average return - MAR) / Downside deviation, where Downside deviation = square root of the average of min(Ri - MAR, 0)^2"},{"slug":"debt-restructuring-haircut","name":"Sovereign Debt Restructuring: NPV Haircut","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Sovereign debt and default","group":"Money, banks and the economy","aliases":["sovereign debt and default","haircut","exit yield","bond exchange offer"],"finds":"How much creditors lose in a debt exchange","needs":"Old and new bond terms, exit yield","text":"Nominal haircut = 1 - new face value / old face value; NPV haircut = 1 - present value of the new bonds\' payments, discounted at an exit yield, / face value of the old claim. A bond\'s PV = coupon x annuity factor + face / (1 + y)^n"},{"slug":"swf-permanent-income","name":"Sovereign Wealth Fund Permanent Income","level":"Intermediate","subject":"Banking & Financial Institutions","section":"Other Institutions","topic":"Sovereign wealth funds","group":"Money, banks and the economy","aliases":["sovereign wealth funds","resource revenue saving","Norway 3% rule","intergenerational equity"],"finds":"How much of a resource windfall can be spent each year","needs":"Revenue, years, real return, current fund","text":"Total wealth = present value of the remaining resource revenue (R each year for N years) + current fund; Sustainable spending (permanent income) = real return x total wealth; Amount to save each year = resource revenue - (permanent income - return on the fund)"},{"slug":"srisk","name":"SRISK (Systemic Risk Contribution)","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Systemic risk","group":"Risk and quantitative methods","aliases":["systemic risk","capital shortfall","LRMES","too big to fail"],"finds":"A firm\'s capital shortfall in a market crash","needs":"Debt, equity value, capital ratio, LRMES","text":"SRISK = max[ Capital ratio x Debt - (1 - Capital ratio) x (1 - LRMES) x Market value of equity, 0 ]"},{"slug":"stablecoin-reserve-income","name":"Stablecoin Reserve Backing and Issuer Income","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Stablecoins","group":"Modern finance and practice","aliases":["stablecoins","reserve ratio","collateralization","T-bill income","de-peg buffer"],"finds":"A stablecoin\'s backing, income and run risk","needs":"Cash, bills, coins in circulation, yield, run size","text":"Backing ratio = reserve assets / coins in circulation; Buffer = reserves - coins in circulation; Issuer income per year = government bills held x yield (holders usually receive none); Run loss = coins redeemed in a run that cannot be paid from cash = max(0, redemptions - cash)"},{"slug":"stock-split","name":"Stock Split","level":"Beginner","subject":"Corporate Finance","section":"Payout Policy","topic":"Stock splits","group":"Companies and valuation","aliases":["share split","split ratio","stock split price adjustment"],"finds":"Shares and price after a split","needs":"Shares, price, split ratio","text":"New shares = k x Old shares; New price = Old price / k, for a k-for-1 split"},{"slug":"sbc-adjusted-fcf","name":"Stock-Based Compensation Adjusted Free Cash Flow","level":"Beginner","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Stock-based compensation","group":"Companies and valuation","aliases":["SBC as a cost","dilution yield","real cost of stock compensation"],"finds":"Free cash flow after paying staff in shares","needs":"Free cash flow, SBC, revenue, market cap","text":"Adjusted FCF = Free cash flow - Stock-based compensation; Dilution yield = SBC / Market cap"},{"slug":"straddle-strangle","name":"Straddle and Strangle","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Option strategies: spreads, straddles, strangles, collars","group":"Markets and instruments","aliases":["long volatility","option strategies","straddle breakeven","strangle breakeven"],"finds":"Profit and breakevens for a bet on a big move","needs":"Strikes, premiums, price at expiry","text":"Straddle (buy a call and a put at the same strike): Profit = |ST - K| - total premium; Strangle (put at a lower strike, call at a higher strike): Profit = max(Kp - ST, 0) + max(ST - Kc, 0) - total premium"},{"slug":"straight-line-depreciation","name":"Straight-Line Depreciation","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Depreciation and amortization","group":"Foundations","aliases":["depreciation formula","annual depreciation","SL depreciation"],"finds":"Equal yearly depreciation","needs":"Cost, salvage value, useful life","text":"Annual depreciation = (Cost - Salvage value) / Useful life"},{"slug":"stress-test-loss","name":"Stress Test Loss and Capital Buffer","level":"Beginner","subject":"Risk Management","section":"Risk","topic":"Stress testing and scenario analysis","group":"Risk and quantitative methods","aliases":["scenario analysis","reverse stress test","shock scenario","stress testing"],"finds":"The loss in a named scenario and how it compares with capital","needs":"Weights, shocks, portfolio value, capital","text":"Scenario loss = Portfolio value x sum of (Weight of asset i x Shock to asset i); Multiple of the shock that exhausts capital = Capital / Loss"},{"slug":"student-loan-capitalization","name":"Student Loan Interest Accrual and Capitalization","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Student loans","group":"Personal finance","aliases":["student loans","unsubsidized loan interest","capitalized interest","deferment cost"],"finds":"How much unpaid study-period interest adds to a loan","needs":"Loan amount, rate, years before repayment, repayment term","text":"Interest accrued while studying = Principal x annual rate x years; if added to the balance (capitalized) the new principal = Principal + accrued interest; the payment on it = i x New principal / (1 - (1 + i)^(-N)), with i the monthly rate and N the number of payments"},{"slug":"sum-of-the-parts","name":"Sum-of-the-Parts Valuation","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Sum-of-the-parts valuation","group":"Companies and valuation","aliases":["SOTP","conglomerate valuation","segment valuation","conglomerate discount"],"finds":"Value of a multi-business group","needs":"Segment EBITDA, multiples, discount, net debt","text":"EV = sum of (Segment EBITDA x Segment multiple); Equity = EV x (1 - Conglomerate discount) - Net debt"},{"slug":"sum-of-years-digits","name":"Sum-of-the-Years\'-Digits Depreciation","level":"Intermediate","subject":"Finance Foundations","section":"Accounting Basics","topic":"Depreciation and amortization","group":"Foundations","aliases":["SYD","accelerated depreciation","syd depreciation"],"finds":"Accelerated depreciation in a chosen year","needs":"Cost, salvage, life, year","text":"Depreciation in year t = (Cost - Salvage) x (L - t + 1) / (L x (L + 1) / 2)"},{"slug":"sustainable-growth-rate","name":"Sustainable Growth Rate","level":"Intermediate","subject":"Corporate Finance","section":"Payout Policy","topic":"Dividends: types and process","group":"Companies and valuation","aliases":["SGR","g = ROE x b","internal growth rate"],"finds":"Growth funded by retained profit","needs":"ROE, retention ratio","text":"Sustainable growth rate g = ROE x Retention ratio"},{"slug":"swap-comparative-advantage","name":"Swap Gains from Comparative Advantage","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Interest rate swaps","group":"Markets and instruments","aliases":["quality spread differential","swap dealer","why firms use swaps"],"finds":"How much two firms save by swapping","needs":"Fixed rates and floating spreads for two firms, dealer fee","text":"Total gain from the swap = (Fixed-rate gap between the weaker and stronger borrower) - (Floating-spread gap between them); each side saves half of what remains after the dealer\'s fee"},{"slug":"money-market-yields","name":"T-Bill Discount Yield and Money Market Yields","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Money market instruments: T-bills, commercial paper, CDs","group":"Markets and instruments","aliases":["bank discount yield","bond equivalent yield","commercial paper","certificate of deposit","T-bill"],"finds":"The true return on a short-term discount instrument","needs":"Face value, price, days to maturity","text":"Discount yield = (F - P) / F x 360 / days; Money market yield = (F - P) / P x 360 / days; Bond equivalent yield = (F - P) / P x 365 / days"},{"slug":"t-statistic","name":"t-Statistic for a Mean (Hypothesis Test)","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Hypothesis testing","group":"Foundations","aliases":["t test","hypothesis test for average return","test statistic","is the average return different from zero"],"finds":"Whether an average differs from a target value","needs":"Sample mean, target mean, standard deviation, sample size","text":"t = (sample mean - hypothesized mean) / (s / sqrt(n))"},{"slug":"cornish-fisher-var","name":"Tail Risk: Cornish-Fisher VaR","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Tail risk and black swans","group":"Risk and quantitative methods","aliases":["skewness kurtosis adjusted VaR","modified VaR","fat tails","black swan","tail risk"],"finds":"A VaR that allows for fat tails and skew","needs":"Portfolio value, mean, sd, skew, excess kurtosis","text":"Adjusted z = z + (z^2 - 1) x Skew / 6 + (z^3 - 3z) x Excess kurtosis / 24 - (2z^3 - 5z) x Skew^2 / 36; VaR = V x (adjusted z x sd - mean)"},{"slug":"taylor-rule","name":"Taylor Rule","level":"Intermediate","subject":"Economics for Finance","section":"Money, Rates and Policy","topic":"Monetary policy: policy rates, QE and QT","group":"Money, banks and the economy","aliases":["monetary policy rule","policy rate","interest rate smoothing","neutral rate"],"finds":"The policy rate a simple rule suggests","needs":"Neutral rate, inflation, target, output gap, current rate","text":"Prescribed policy rate = neutral real rate + inflation + 0.5 x (inflation - target) + 0.5 x output gap; With smoothing, rate = rho x last rate + (1 - rho) x prescribed rate"},{"slug":"terminal-value-exit-multiple","name":"Terminal Value (Exit Multiple Method)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Terminal value: perpetuity growth vs. exit multiple","group":"Companies and valuation","aliases":["exit multiple","TV multiple","terminal EBITDA multiple"],"finds":"Terminal value from a market multiple","needs":"EBITDA, multiple, FCFF, WACC","text":"Terminal value = Final-year EBITDA x Exit multiple; Implied g = (TV x WACC - FCFF) / (TV + FCFF)"},{"slug":"terminal-value-growth","name":"Terminal Value (Perpetuity Growth Method)","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Terminal value: perpetuity growth vs. exit multiple","group":"Companies and valuation","aliases":["terminal value","Gordon growth terminal value","TV perpetuity"],"finds":"Value of cash flows after the forecast","needs":"Final FCFF, growth, WACC, EBITDA","text":"Terminal value = Final-year FCFF x (1 + g) / (WACC - g)"},{"slug":"accounting-equation","name":"The Accounting Equation","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"The accounting equation","group":"Foundations","aliases":["assets equal liabilities plus equity","balance sheet equation","A = L + E"],"finds":"Equity from assets and liabilities","needs":"Assets, liabilities","text":"Assets = Liabilities + Equity"},{"slug":"time-weighted-return","name":"Time-Weighted Return","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Time-weighted vs. money-weighted returns","group":"Markets and instruments","aliases":["TWR","geometric linked return","manager return"],"finds":"A manager\'s return, ignoring the timing of client cash flows","needs":"Sub-period returns, years","text":"Time-weighted return = (1 + R1) x (1 + R2) x ... x (1 + Rn) - 1"},{"slug":"token-nav-and-fees","name":"Tokenized Asset: Value per Token and Cost of Access","level":"Intermediate","subject":"Fintech & Digital Finance","section":"Fintech","topic":"Tokenization of real-world assets","group":"Modern finance and practice","aliases":["tokenization of real-world assets","fractional ownership","NAV per token","token premium","RWA tokens"],"finds":"What a token is worth and what trading it costs","needs":"Asset value, tokens, fees, premium or discount","text":"Value per token = (asset value - annual fees x years) / tokens issued; Premium or discount = market price / value per token - 1; Cost to buy and sell = 2 x trading fee + bid-ask spread; Minimum investment = value per token"},{"slug":"trade-off-value","name":"Trade-Off Theory Firm Value","level":"Intermediate","subject":"Corporate Finance","section":"Capital Structure","topic":"Costs of financial distress","group":"Companies and valuation","aliases":["costs of financial distress","optimal debt trade off","distress costs"],"finds":"Value after weighing tax savings against distress risk","needs":"Unlevered value, tax rate, debt, distress probability and cost","text":"Value of levered firm = Unlevered value + Tax shield - (Probability of distress x Cost of distress)"},{"slug":"traditional-vs-roth","name":"Traditional vs Roth Account After Tax","level":"Beginner","subject":"Personal Finance","section":"Personal Finance","topic":"Personal taxes and tax-advantaged investing","group":"Personal finance","aliases":["tax-advantaged investing","pre-tax vs after-tax contributions","Roth account","tax deferred"],"finds":"Which tax treatment leaves more money after tax","needs":"Contribution, tax rates now and later, growth, years","text":"Traditional (tax-deferred) after-tax value = Pre-tax contribution x (1 + growth)^n x (1 - tax rate at withdrawal); Roth (tax-free) value = Pre-tax contribution x (1 - tax rate now) x (1 + growth)^n"},{"slug":"tranche-loss","name":"Tranche Loss Allocation (Attachment and Detachment)","level":"Intermediate","subject":"Fixed Income","section":"Securitized Products","topic":"Tranching","group":"Markets and instruments","aliases":["tranching","waterfall losses","attachment point","detachment point","equity mezzanine senior tranche"],"finds":"Which tranche absorbs how much of a pool loss","needs":"Pool loss, tranche boundaries","text":"Share of the tranche lost = min( max(Pool loss - Attachment point, 0), Detachment point - Attachment point ) / (Detachment point - Attachment point)"},{"slug":"treasury-stock-method","name":"Treasury Stock Method (Diluted Shares)","level":"Intermediate","subject":"Financial Statement Analysis","section":"Quality & Red Flags","topic":"Stock-based compensation","group":"Companies and valuation","aliases":["diluted EPS","stock options dilution","in the money options","TSM"],"finds":"Diluted share count and EPS from options","needs":"Basic shares, options, strike, share price, net income","text":"If options are in the money, Net new shares = Options x (1 - Strike / Share price); Diluted shares = Basic shares + Net new shares"},{"slug":"trend-index-analysis","name":"Trend Analysis: Index and Growth Rates","level":"Beginner","subject":"Financial Statement Analysis","section":"Ratio Analysis","topic":"Trend and peer analysis","group":"Companies and valuation","aliases":["horizontal analysis","base year index","year on year growth","trend analysis"],"finds":"Growth and the index of a figure over time","needs":"A series of yearly figures","text":"Index = Value in year t / Value in the base year x 100; Year-on-year growth = Value in year t / Value in year t-1 - 1; CAGR = (Last / First)^(1 / years) - 1"},{"slug":"treynor-ratio","name":"Treynor Ratio","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Performance Measurement","topic":"Treynor ratio","group":"Markets and instruments","aliases":["reward to volatility","return per unit of beta"],"finds":"Return per unit of market risk","needs":"Return, risk-free rate, beta","text":"Treynor ratio = (Portfolio return - Risk-free rate) / Portfolio beta"},{"slug":"hypothesis-test-two-means","name":"Two-Sample Z-Test for a Difference in Means","level":"Beginner","subject":"Data, Statistics & Computational Skills","section":"Quantitative foundations","topic":"Quantitative foundations","group":"Risk and quantitative methods","aliases":["quantitative foundations","compare two strategies","difference in average returns","p-value"],"finds":"Whether two averages differ by more than chance","needs":"Averages, standard deviations and sizes of the two groups","text":"z = (average of group 1 - average of group 2) / sqrt(sd1^2 / n1 + sd2^2 / n2); two-sided p-value = 2 x (1 - N(|z|))"},{"slug":"uncovered-interest-parity","name":"Uncovered Interest Parity and Unhedged Return","level":"Intermediate","subject":"International Finance","section":"Global Finance","topic":"Interest rate parity (covered and uncovered)","group":"Money, banks and the economy","aliases":["UIP","interest rate parity","expected depreciation","forward premium puzzle"],"finds":"The currency move that cancels an interest advantage","needs":"Spot, both rates, future spot","text":"Uncovered parity: the expected future spot equals today\'s spot x (1 + domestic rate) / (1 + foreign rate), so the higher-rate currency is expected to weaken; Unhedged return in domestic currency = (1 + foreign rate) x (future spot / spot) - 1"},{"slug":"labor-market-rates","name":"Unemployment, Participation and Employment Rates","level":"Beginner","subject":"Economics for Finance","section":"How the Economy Works","topic":"Unemployment and the labor market","group":"Money, banks and the economy","aliases":["unemployment and the labor market","labor force participation","discouraged workers","employment population ratio"],"finds":"What a jobs report headline hides","needs":"Population, employed and unemployed counts","text":"Unemployment rate = unemployed / labor force, where labor force = employed + unemployed; Participation rate = labor force / working-age population; Employment-population ratio = employed / working-age population"},{"slug":"units-of-production-depreciation","name":"Units-of-Production Depreciation","level":"Intermediate","subject":"Finance Foundations","section":"Accounting Basics","topic":"Depreciation and amortization","group":"Foundations","aliases":["usage depreciation","depreciation by output","activity method"],"finds":"Depreciation based on how much the asset was used","needs":"Cost, salvage, total units, units used","text":"Depreciation = (Cost - Salvage) / Total expected units x Units used this period"},{"slug":"unlever-beta","name":"Unlevering Beta","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Unlevering and relevering beta","group":"Companies and valuation","aliases":["asset beta","unlevered beta","Hamada unlever","pure play beta"],"finds":"Business risk without the effect of debt","needs":"Levered beta, debt-to-equity, tax rate","text":"Unlevered beta = Levered beta / (1 + (1 - T) x D/E)"},{"slug":"utility-risk-aversion","name":"Utility and Risk Aversion","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Portfolio Theory","topic":"Utility and risk aversion","group":"Markets and instruments","aliases":["mean variance utility","certainty equivalent","risk aversion coefficient"],"finds":"How attractive a risky portfolio is to one investor","needs":"Expected return, standard deviation, risk aversion, risk-free rate","text":"Utility U = E(r) - 0.5 x A x variance"},{"slug":"precedent-transactions","name":"Valuation from Precedent Transactions","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Precedent transactions","group":"Companies and valuation","aliases":["transaction comps","deal multiples","M&A comparables","control premium valuation"],"finds":"Value implied by prices paid in past deals","needs":"Past deal values and EBITDA, your EBITDA","text":"Deal multiple = Deal EV / Target EBITDA for each past deal; Implied EV = Your EBITDA x Median deal multiple"},{"slug":"trading-comparables","name":"Valuation from Trading Comparables","level":"Intermediate","subject":"Valuation","section":"Valuation","topic":"Trading comparables","group":"Companies and valuation","aliases":["comps","relative valuation","peer multiples","comparable companies"],"finds":"Value from peer multiples","needs":"Peer multiples, target metric","text":"Implied value = Target metric (such as EBITDA) x Median multiple of peer companies"},{"slug":"valuation-multiples","name":"Valuation Multiples (EV/EBITDA, EV/Sales, P/E)","level":"Beginner","subject":"Valuation","section":"Valuation","topic":"EV/EBITDA, EV/Sales, P/E multiples","group":"Companies and valuation","aliases":["EV/EBITDA","EV/Sales","P/E ratio","price earnings","multiples"],"finds":"What the market pays for earnings and sales","needs":"EV, EBITDA, sales, price, EPS","text":"EV/EBITDA = Enterprise value / EBITDA; EV/Sales = Enterprise value / Sales; P/E = Share price / Earnings per share"},{"slug":"var-historical","name":"Value at Risk: Historical Simulation","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Value at Risk (VaR): historical, parametric, Monte Carlo","group":"Risk and quantitative methods","aliases":["historical VaR","empirical VaR","percentile VaR"],"finds":"A loss limit read from past returns","needs":"Portfolio value, past returns, confidence","text":"VaR = - Portfolio value x the (1 - confidence) percentile of past returns"},{"slug":"var-parametric","name":"Value at Risk: Parametric (Variance-Covariance)","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Value at Risk (VaR): historical, parametric, Monte Carlo","group":"Risk and quantitative methods","aliases":["VaR","value at risk","normal VaR","delta normal","Monte Carlo VaR"],"finds":"A loss limit at a chosen confidence level","needs":"Portfolio value, mean and standard deviation of returns, confidence, days","text":"VaR = Portfolio value x (z-score x Daily volatility x sqrt(days) - Daily mean return x days)"},{"slug":"acquisition-npv","name":"Value Created by an Acquisition","level":"Intermediate","subject":"Corporate Finance","section":"Mergers & Restructuring","topic":"Synergies and their estimation","group":"Companies and valuation","aliases":["takeover premium","M&A NPV","synergies and premium","acquisition gain"],"finds":"Who gains from an acquisition","needs":"Stand-alone value, synergies, price","text":"Acquirer NPV = Synergies - Premium, where Premium = Price paid - Stand-alone value of the target"},{"slug":"mm-levered-value","name":"Value of a Levered Firm (Modigliani-Miller with Taxes)","level":"Intermediate","subject":"Corporate Finance","section":"Capital Structure","topic":"Tax shield of debt","group":"Companies and valuation","aliases":["MM proposition I","tax shield of debt","value with debt","VL = VU + TD"],"finds":"Value added by the debt tax shield","needs":"Unlevered value, tax rate, debt","text":"Value of levered firm = Value of unlevered firm + Tax rate x Debt"},{"slug":"var-backtest-kupiec","name":"VaR Backtest: Exceptions and Kupiec Test","level":"Intermediate","subject":"Risk Management","section":"Risk","topic":"Backtesting","group":"Risk and quantitative methods","aliases":["backtesting VaR","traffic light test","proportion of failures","VaR exceptions"],"finds":"Whether a VaR model has the right number of exceptions","needs":"Days tested, exceptions, confidence","text":"Kupiec statistic = -2 x ln[(1-p)^(N-x) x p^x] + 2 x ln[(1 - x/N)^(N-x) x (x/N)^x]; compare with 3.84 (5% level, 1 degree of freedom)"},{"slug":"variance-sd","name":"Variance and Standard Deviation of Returns","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Variance and standard deviation of returns","group":"Foundations","aliases":["standard deviation","volatility","risk","variance","sample standard deviation"],"finds":"How much returns vary (risk)","needs":"List of returns","text":"s^2 = sum of (Ri - mean)^2 / (n - 1), and s = square root of s^2"},{"slug":"variance-of-distribution","name":"Variance of a Probability Distribution","level":"Intermediate","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Probability basics: expected value and conditional probability","group":"Foundations","aliases":["scenario variance","standard deviation of expected return","risk across scenarios"],"finds":"Risk measured across scenarios","needs":"Probabilities, outcomes","text":"Variance = sum of pi x (xi - E(X))^2"},{"slug":"variance-ratio","name":"Variance Ratio (Random Walk Test)","level":"Intermediate","subject":"Investments & Portfolio Theory","section":"Market Efficiency","topic":"Random walk theory","group":"Markets and instruments","aliases":["Lo MacKinlay","random walk test","mean reversion test","random walk theory"],"finds":"Whether returns look like a random walk","needs":"1-period and q-period standard deviations","text":"Variance ratio = Variance of q-period returns / (q x Variance of 1-period returns)"},{"slug":"vasicek-zero-bond","name":"Vasicek Model Zero-Coupon Bond Price","level":"Intermediate","subject":"Quantitative Finance","section":"Quant","topic":"Interest rate models (Vasicek, CIR, Hull-White)","group":"Risk and quantitative methods","aliases":["interest rate models","Vasicek","short rate model","mean reverting rate"],"finds":"A zero-coupon bond price and yield from a short-rate model","needs":"Short rate, long-run mean, speed, volatility, maturity","text":"Bond price = A x e^(-B x r0), where B = (1 - e^(-kappa T)) / kappa and A = exp[(theta - sigma^2 / (2 kappa^2)) x (B - T) - sigma^2 x B^2 / (4 kappa)]"},{"slug":"vc-dilution-exit","name":"Venture Capital Dilution and Required Exit Value","level":"Intermediate","subject":"Alternative Investments","section":"Alternatives","topic":"Venture capital economics","group":"Modern finance and practice","aliases":["VC economics","pre-money post-money","dilution across funding rounds","venture return multiple"],"finds":"How much a venture stake shrinks and the exit it needs","needs":"Round valuations and sizes, option pool, target multiple","text":"Post-money value = pre-money value + investment; Ownership bought = investment / post-money; Each later round dilutes existing holders by (new investment / new post-money value); Stake at exit = initial stake x product of (1 - dilution) x (1 - option pool share); Exit value needed for a multiple M = M x investment / stake at exit"},{"slug":"vc-method-ownership","name":"Venture Capital Method (Required Ownership)","level":"Intermediate","subject":"Corporate Finance","section":"Raising Capital","topic":"Venture capital stages (seed, Series A-D)","group":"Companies and valuation","aliases":["VC method","target return ownership","venture capital return multiple"],"finds":"Stake needed to hit a target venture return","needs":"Investment, target multiple, exit value, retention","text":"Required stake at exit = Investment x Target multiple / Exit value; Stake needed today = Required stake / Retention"},{"slug":"vix-variance","name":"VIX-Style Variance from Option Prices","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Volatility indices (VIX and regional equivalents)","group":"Markets and instruments","aliases":["VIX","volatility index","variance swap","model free implied volatility","VSTOXX"],"finds":"A volatility index reading from option prices","needs":"Strikes, option prices, forward, K0, rate, time","text":"Variance = (2 / T) x sum of [ (Strike gap / Strike^2) x e^(rT) x Option price ] - (1 / T) x (Forward / K0 - 1)^2; Index = 100 x square root of variance"},{"slug":"warrant-value-dilution","name":"Warrant Value with Dilution","level":"Intermediate","subject":"Derivatives","section":"Derivatives","topic":"Warrants and convertible bonds","group":"Markets and instruments","aliases":["equity warrant","dilution adjusted option","company issued option"],"finds":"A warrant\'s value after dilution","needs":"Ordinary call value, shares outstanding, new shares","text":"Warrant value = Number of shares outstanding / (Shares outstanding + New shares created if all warrants are exercised) x Value of an ordinary call with the same terms"},{"slug":"wacc","name":"Weighted Average Cost of Capital (WACC)","level":"Intermediate","subject":"Corporate Finance","section":"Cost of Capital","topic":"Weighted average cost of capital (WACC)","group":"Companies and valuation","aliases":["WACC","firm cost of capital","blended cost of capital","discount rate for the firm"],"finds":"Blended cost of all capital","needs":"Market values and costs of each source, tax rate","text":"WACC = E/V x re + D/V x rd x (1 - T) + P/V x rp"},{"slug":"weighted-average-cost","name":"Weighted Average Cost per Unit","level":"Beginner","subject":"Finance Foundations","section":"Accounting Basics","topic":"Inventory accounting (FIFO, LIFO, weighted average)","group":"Foundations","aliases":["inventory weighted average","average cost method","FIFO LIFO alternative"],"finds":"Average cost per unit of inventory","needs":"Units and costs for each purchase","text":"Average cost per unit = Total cost of goods available / Units available"},{"slug":"weighted-average-life","name":"Weighted Average Life (WAL)","level":"Intermediate","subject":"Fixed Income","section":"Securitized Products","topic":"Securitization process","group":"Markets and instruments","aliases":["WAL","average life of a mortgage security","principal weighted time"],"finds":"The average time principal is outstanding","needs":"Payment dates and principal amounts","text":"Weighted average life = Sum of (time x principal repaid at that time) / Total principal"},{"slug":"yield-curve-slope","name":"Yield Curve Slope and Curvature","level":"Beginner","subject":"Fixed Income","section":"Bonds","topic":"Yield curve shapes and what they signal","group":"Markets and instruments","aliases":["term spread","2s10s","inverted yield curve","butterfly spread","recession signal"],"finds":"The slope and shape of the yield curve","needs":"Yields at four maturities","text":"Slope = 10-year yield - 2-year yield; Curvature (butterfly) = 2 x 5-year yield - 2-year yield - 10-year yield"},{"slug":"ytm","name":"Yield to Maturity (YTM)","level":"Intermediate","subject":"Fixed Income","section":"Bonds","topic":"Yield to maturity","group":"Markets and instruments","aliases":["bond yield","internal rate of return of a bond","promised yield","effective yield"],"finds":"The return from buying a bond and holding it to maturity","needs":"Price, face value, coupon rate, years, payments per year","text":"Find the yield y that makes the present value of all coupons and the face value equal to the price. Approximation: y = [C + (F - P) / n] / [(F + P) / 2]"},{"slug":"z-score","name":"Z-Score","level":"Beginner","subject":"Finance Foundations","section":"Statistics for Finance","topic":"Normal and lognormal distributions","group":"Foundations","aliases":["standard score","standardized value","how many standard deviations"],"finds":"How far a value is from average","needs":"Value, mean, standard deviation","text":"z = (x - mean) / standard deviation"},{"slug":"zero-coupon-bond","name":"Zero-Coupon Bond and STRIPS","level":"Beginner","subject":"Fixed Income","section":"Bonds","topic":"Zero-coupon bonds and STRIPS","group":"Markets and instruments","aliases":["STRIPS","zero coupon price","accretion","imputed interest","deep discount bond"],"finds":"The price of a zero-coupon bond and its accretion","needs":"Face value, yield, years","text":"Price = Face value / (1 + yield / payments per year)^(years x payments per year)"}]')}}]);